INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C1','soc',5,2,'u3',1,'식민 통치·저항·광복 — 다른 나라가 힘으로 빼앗아 다스리는 것이 식민 통치, 그에 맞서 싸우는 것이 저항, 빼앗긴 나라를 되찾은 것이 광복 · 이 단원은 ① 식민 통치와 저항으로 달라진 사회와 생활 모습 → ② 8·15 광복과 6·25 전쟁으로 달라진 사회와 생활 모습 · 우리 민족은 감시 속에서도 나라를 되찾을 때까지 여러 방법으로 맞섬(사건을 외우기보다 생활이 어떻게 달라졌는지 따라감)',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C2','soc',5,2,'u3',1,'을사늑약과 외교권 — 조선의 왕이 황제가 되어 세운 나라가 대한 제국 · 한반도를 둘러싼 여러 나라의 다툼 속에 러시아와 싸워 이긴 일제가 본격적으로 침략 · 황제가 반대했는데도 군대를 앞세워 억지로 맺은 조약(늑약)으로 대한 제국은 일본을 거치지 않고는 다른 나라와 조약을 맺을 수 없게 되어 외교권을 빼앗김 · 소식을 들은 상인은 가게 문을 닫고 학생은 등교를 거부함',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C3','soc',5,2,'u3',1,'헤이그 특사 — 황제는 네덜란드 헤이그에서 열린 평화 회의에 특사를 보내 을사늑약이 무효임을 알리려 함 · 일제의 방해로 회의장에는 들어가지 못했지만 여러 나라 기자들 앞에서 대한 제국의 처지와 늑약의 부당함을 알림',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C4','soc',5,2,'u3',1,'항일 의병 — 나라를 지키려고 스스로 일어나 일제와 싸운 사람들 · 낡은 한복 차림의 젊은이부터 농민·여성까지 나이와 신분이 다양(여성 의병장은 노래를 지어 여성들도 함께하자고 함) · 일제의 강요로 대한 제국 군대가 해산되자 군인들이 합류해 더 활발해짐 · 일제가 큰 부대로 탄압하자 만주·연해주로 건너가 싸움을 이어 감',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C5','soc',5,2,'u3',2,'조선 총독부와 헌병 경찰 — 나라를 빼앗은 일제는 조선 총독부를 세우고 군인 출신을 우두머리로 앉혀 강압적으로 다스림 · 헌병(군대에서 경찰 일을 하는 군인)에게 경찰 일을 맡겨 한국인을 감시하고 독립운동을 탄압 · 학교 교사에게도 제복을 입고 칼을 차게 해 공포 분위기를 만들고 국어 교과서에는 일본어를 실음',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C6','soc',5,2,'u3',2,'토지 조사 사업 — 일제가 땅 주인을 확인한다며 전국에서 벌인 사업 · 정해진 기간에 신고하지 못한 땅 등을 빼앗기도 해 많은 농민이 농사지을 땅을 잃거나 불리한 조건으로 계약함 · 시간이 지날수록 남의 땅을 빌려 농사짓는 농민이 늘어 생활이 어려워짐(겉으로 내세운 까닭과 실제로 벌어진 일이 다름)',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C7','soc',5,2,'u3',2,'나라 밖으로 이어진 독립운동 — 감시와 탄압으로 나라 안 독립운동이 어려워지자 독립운동가들이 나라 밖으로 옮겨 가 학교와 단체를 만듦 · 만주에 신흥 무관 학교를 세워 독립군을 기름(재산을 모두 팔고 가족과 함께 떠난 집안도 있음) · 미국에서는 흥사단을 만들어 우리 민족의 실력을 키움 · 남은 기록으로 이름이 덜 알려진 사람들의 고통과 노력도 알 수 있음',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C8','soc',5,2,'u3',3,'3·1 운동 — 일제의 강압적인 통치가 이어지자 민족 대표들이 독립 선언서를 발표하고, 같은 시각 학생과 시민이 서울 탑골 공원에서 독립 선언서를 읽고 만세 시위를 벌임 · 만세는 전국 곳곳으로 퍼져 석 달 넘게 이어짐(농민은 장날에 모이고 상인은 가게 문을 닫음, 학생·종교인·노동자도 함께) · 일제는 폭력적으로 진압함 · 오늘날 삼일절로 기념',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C9','soc',5,2,'u3',3,'대한민국 임시 정부 — 3·1 운동을 겪으며 독립운동을 이끌 힘을 하나로 모아야 함을 깨달아 여러 곳의 임시 정부를 합쳐 중국 상하이에 세움(일제의 탄압을 피하기 쉽고 외교 활동에 유리) · 비밀 연락망으로 독립운동을 지휘하고 자금을 모음 · 신문을 만들어 활동을 알리고 외교 활동으로 세계에 독립 의지를 알림',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C10','soc',5,2,'u3',3,'한인 애국단 — 일제의 탄압으로 임시 정부의 활동이 힘들어지자 만든 단체 · 일제의 주요 인물을 처단하는 활동으로 독립운동에 다시 힘을 불어넣음',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C11','soc',5,2,'u3',4,'3·1 운동 이후 일제의 통치 — 강압적인 통치만으로는 다스리기 어렵다고 여긴 일제가 다스리는 방법을 바꿈 · 일제 편에 서는 친일 세력을 늘려 우리 민족을 분열시키려 함 · 일본에 쌀이 모자라자 우리나라에서 쌀을 더 많이 생산해 일본으로 가져가 우리 민족의 생활은 더 어려워짐(항구에 쌀가마가 쌓여 배로 실려 감)',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C12','soc',5,2,'u3',4,'나라 안에서 힘을 기른 운동 — 물산 장려 운동: 「우리가 만든 것 우리가 쓰자」, 우리 땅에서 나는 토산품을 쓰고 절약해 경제적으로 독립하자 · 농촌 계몽 운동: 학생들이 농촌에서 한글을 가르침 · 조선어 학회: 우리말을 연구하고 우리말 사전을 만들려고 애씀 · 총이 아니라 경제·글·말로 민족의 힘을 길러 식민 통치에서 벗어나려 함',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C13','soc',5,2,'u3',4,'학생들이 앞장선 항일 운동 — 6·10 만세 운동: 마지막 황제의 장례식 날 학생들이 서울에서 만세를 외침 · 광주 학생 항일 운동: 광주에서 한국 학생과 일본 학생이 다투었는데 경찰이 한국 학생만 붙잡자, 학교에서 쌓인 차별에 맞선 학생 시위가 전국으로 퍼짐 · 오늘날 11월 3일 학생 독립운동 기념일로 기억',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C14','soc',5,2,'u3',4,'나라 밖 무장 독립 투쟁 — 만주·연해주에서 무기를 들고 싸우는 독립군 활동이 활발 · 여러 독립군 부대가 봉오동에서 일본군을 물리치고, 이어 독립군 연합 부대가 청산리 일대에서 일본군과 싸워 이김 · 먹을 것이 끊기고 추위에 시달리면서도 싸움을 이어 감 · 나라 안 실력 기르기와 나라 밖 무장 투쟁이 함께 독립을 향함',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C15','soc',5,2,'u3',5,'철도와 도시의 두 얼굴 — 일제는 다스리기 쉽게 도로·항구·철도를 새로 놓고 정비(땅을 강제로 거두고 한국인을 강제로 동원) · 사람과 물자가 빨라졌지만 철도는 주로 군대를 빠르게 옮기고 빼앗은 자원(쌀 등)을 일본으로 실어 나르는 데 쓰임(군산선 임피역 — 평야의 쌀을 군산항으로) · 철도역·항구를 중심으로 도시가 발달했지만 일본인이 모여 산 곳에는 은행·백화점·상가가 들어서고 한국인이 모여 산 곳은 전기가 잘 들어오지 않고 공동 우물을 씀, 가난한 사람은 변두리 토막집에 삶',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C16','soc',5,2,'u3',5,'인공 조미료와 달라진 음식 문화 — 일제 통치 시기 일본에서 만든 인공 조미료가 처음 들어와 국물 요리가 많은 우리나라에서 인기 · 비싼 재료 없이도 맛을 쉽고 일정하게 내 시간·비용이 줄고 식당이 음식을 많이 만듦(여름철 냉면 전화 주문·자전거 배달) · 그러나 대부분의 한국인은 배달 문화를 누리지 못했고 집집마다 다르던 맛이 비슷해지는 그늘도 있음',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C17','soc',5,2,'u3',5,'민족정신을 없애려는 정책과 강제 동원 — 아시아·태평양 곳곳에서 침략 전쟁을 일으킨 일제는 우리 민족이 일본 왕에게 충성하고 전쟁에 협조하게 하려고 신사에 강제로 절하게 하고, 성과 이름을 일본식으로 바꾸게 하고, 일본어를 강요하며 학교에서 우리말과 역사를 배우지 못하게 함 · 학생들은 몸뻬 교복을 입고 전쟁을 미화하는 수업과 군사 훈련을 받음 · 전쟁에 필요한 사람(전쟁터·공장 등)과 물자(놋그릇·숟가락까지)를 강제로 동원, 일부 여성은 일본군 ‘위안부’로 강제로 끌려가 큰 고통을 겪음',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C18','soc',5,2,'u3',5,'민족 문화를 지킨 노력과 한국광복군 — 탄압 속에서도 우리 역사를 연구해 일제의 역사 왜곡에 맞서고, 일제에 저항하는 글을 써 민족의식을 일깨움 · 대한민국 임시 정부는 한국광복군을 만들어 일본과의 전쟁에 나섬 · 미군과 협력해 국내로 들어갈 작전을 세웠지만 일제가 항복해 실행하지 못함',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C19','soc',5,2,'u3',6,'8·15 광복과 달라진 생활 — 임시 정부와 나라 안팎 독립운동가들의 끊임없는 노력 속에 연합국이 승리하며 우리 민족은 8월 15일 광복을 맞음 · 사람들은 태극기를 들고 만세를 부름, 감옥의 독립운동가가 풀려나고 나라 밖 동포와 임시 정부 지도자들이 돌아옴 · 학교에서 우리말로 수업하고 우리글·우리 역사를 배움, 일제가 강제로 없앤 한글 신문·잡지가 다시 나옴, 일본식 성과 이름 대신 원래 성과 이름을 씀',ARRAY['[6사06-02] 8·15 광복과 6·25 전쟁이 사회와 생활에 미친 영향을 파악한다.']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C20','soc',5,2,'u3',6,'대한민국 정부 수립 — 일본군의 무장 해제를 이유로 38도선 남쪽에 미군, 북쪽에 소련군이 들어옴 · 우리 민족은 통일 정부를 세우려 했지만 남과 북, 미국과 소련의 의견이 달라 어려워짐 · 국제 연합(UN)의 결정으로 선거가 가능한 남한에서만 5·10 총선거를 치러 국회의원을 뽑음(우리 역사의 첫 민주 선거, 일정한 나이가 된 모든 국민이 남녀 구분 없이 참여) · 제헌 국회가 헌법을 만들어 공포(7월 17일, 제헌절) → 헌법에 따라 첫 대통령 선출 → 8월 15일 대한민국 정부 수립',ARRAY['[6사06-02] 8·15 광복과 6·25 전쟁이 사회와 생활에 미친 영향을 파악한다.']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C21','soc',5,2,'u3',7,'6·25 전쟁의 전개 — 남과 북에 서로 다른 정부가 선 뒤 북한이 소련의 지원으로 군사력을 키워 무력으로 통일하려고 기습적으로 38도선을 넘어 쳐들어옴(남침) → 사흘 만에 서울을 빼앗기고 낙동강 남쪽까지 밀림 → 국제 연합이 여러 나라가 참여한 국제 연합군과 물자를 보냄 → 인천 상륙 작전으로 서울을 되찾고 압록강 부근까지 나아감 → 중국군 참전으로 다시 서울을 빼앗기고 물러남 → 서울을 되찾은 뒤 38도선 부근에서 치열한 전투와 회담이 이어짐 → 정전 협정(전투를 잠시 멈추기로 함)으로 휴전선이 정해짐(전쟁이 끝난 것이 아니라 멈춘 것)',ARRAY['[6사06-02] 8·15 광복과 6·25 전쟁이 사회와 생활에 미친 영향을 파악한다.']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C22','soc',5,2,'u3',7,'전쟁 중 사람들의 생활 — 많은 사람이 고향을 떠나 피란함, 피란민이 낙동강 남쪽과 임시 수도 부산으로 모여 산등성이에 움막이나 판잣집을 짓고 삶 · 마실 물과 먹을 것이 부족해 줄을 서서 물을 받음 · 학생들은 임시로 만든 천막 학교에서 배움을 이어 감 · 흥남 철수: 중국군 참전으로 물러날 때 흥남 부두에서 군인과 피란민이 배로 빠져나옴(짐을 버리고 정원보다 훨씬 많은 피란민을 태운 배) · 밀면: 북쪽에서 내려온 피란민이 고향의 냉면을 부산에서 구할 수 있는 밀가루 등으로 만든 음식',ARRAY['[6사06-02] 8·15 광복과 6·25 전쟁이 사회와 생활에 미친 영향을 파악한다.']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C23','soc',5,2,'u3',8,'6·25 전쟁의 피해와 오늘날까지 이어진 영향 — 군인뿐 아니라 많은 민간인이 목숨을 잃거나 다침 · 국토가 황폐해지고 집·산업 시설·도로·철도·다리가 파괴되고 수원 화성 같은 국가유산이 훼손됨 · 가족과 헤어진 이산가족과 부모를 잃은 전쟁고아가 많이 생기고 생활필수품과 먹을 것이 오래 부족함 · 남북이 서로를 적으로 여기는 감정이 깊어지고 분단이 오늘날까지 이어져 헤어진 가족을 끝내 만나지 못한 사람도 많음(방송국의 이산가족 찾기 생방송으로 다시 만난 가족도 있음)',ARRAY['[6사06-02] 8·15 광복과 6·25 전쟁이 사회와 생활에 미친 영향을 파악한다.']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-2-u3-C24','soc',5,2,'u3',9,'기념일을 알리는 옷 만들기 — 단원에서 공부한 일과 관련된 기념일(삼일절·대한민국 임시 정부 수립 기념일·6·10 만세 운동 기념일·제헌절·광복절·학생 독립운동 기념일·유엔군 참전의 날 등)을 조사 → 기념하는 것·기념일이 된 까닭·그날 하는 일을 정리 → 핵심어를 뽑아 그림과 문구를 구상 → 옷을 완성해 소개 · 그림과 문구는 자유롭게 꾸며도 기념일의 뜻과 역사적 사실에 맞아야 함',ARRAY['[6사06-02] 8·15 광복과 6·25 전쟁이 사회와 생활에 미친 영향을 파악한다.']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X01','soc',5,'u3',ARRAY['SO5-2-u3-C1']::text[],'일제가 다스리던 시기에 우리 민족은 아무것도 못 하고 당하기만 했다고 여긴다','감시 속에서도 여러 방법으로 맞섬') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X02','soc',5,'u3',ARRAY['SO5-2-u3-C1']::text[],'식민 통치·저항·광복의 뜻을 바꾸어 안다(광복을 나라를 빼앗긴 일로, 저항을 따르는 일로)','빼앗아 다스림 · 맞섬 · 되찾음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X03','soc',5,'u3',ARRAY['SO5-2-u3-C2']::text[],'을사늑약으로 대한 제국이 빼앗긴 권리를 잘못 안다(화폐·농사·학교를 세우는 권리라고)','다른 나라와 조약을 맺는 외교권') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X04','soc',5,'u3',ARRAY['SO5-2-u3-C2']::text[],'을사늑약을 두 나라가 뜻을 모아 맺은 조약으로 여겨 「억지로 맺은 조약」이라는 뜻을 놓친다','황제 반대 · 군대를 앞세움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X05','soc',5,'u3',ARRAY['SO5-2-u3-C3']::text[],'헤이그 특사가 회의에서 늑약을 바로 없앴다고 여기거나, 아무 뜻 없는 실패였다고만 여긴다','회의장엔 못 들어감 · 기자들에게 알림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X06','soc',5,'u3',ARRAY['SO5-2-u3-C4']::text[],'의병에는 훈련받은 군인만 참여했다고 여긴다','나이·신분 다양 · 농민·여성도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X07','soc',5,'u3',ARRAY['SO5-2-u3-C4']::text[],'의병 운동이 더 활발해진 까닭이나 만주·연해주로 건너간 까닭을 놓친다','해산 군인 합류 · 큰 부대 탄압 → 나라 밖') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X08','soc',5,'u3',ARRAY['SO5-2-u3-C5']::text[],'조선 총독부를 우리가 세운 정부(대한 제국·임시 정부)로 안다','일제가 다스리려고 세운 기관') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X09','soc',5,'u3',ARRAY['SO5-2-u3-C5']::text[],'헌병 경찰과 칼을 찬 교사를 질서를 지키려는 일로만 보아 감시·탄압·공포의 뜻을 놓친다','감시해서 독립운동을 막음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X10','soc',5,'u3',ARRAY['SO5-2-u3-C6']::text[],'토지 조사 사업이 농민의 땅을 지켜 주려는 일이었다고 여긴다','내세운 까닭과 실제로 벌어진 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X11','soc',5,'u3',ARRAY['SO5-2-u3-C6']::text[],'토지 조사 사업 뒤 자기 땅에서 농사짓는 농민이 늘었다고 거꾸로 안다','남의 땅을 빌려 짓는 농민이 늘어남') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X12','soc',5,'u3',ARRAY['SO5-2-u3-C7']::text[],'나라 밖으로 간 독립운동가를 도망간 사람으로만 여긴다','나라 밖에서 힘을 길러 이어 간 저항') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X13','soc',5,'u3',ARRAY['SO5-2-u3-C7']::text[],'신흥 무관 학교와 흥사단의 자리와 하는 일을 바꾸어 안다','만주 독립군 · 미국 실력') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X14','soc',5,'u3',ARRAY['SO5-2-u3-C8']::text[],'3·1 운동이 서울에서 하루 만에 끝났거나 어른 한 무리만 참여했다고 여긴다','전국 · 석 달 넘게 · 여러 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X15','soc',5,'u3',ARRAY['SO5-2-u3-C8']::text[],'3·1 운동을 무기를 든 의병 싸움이나 다른 운동과 헷갈린다','독립 선언서 · 만세 시위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X16','soc',5,'u3',ARRAY['SO5-2-u3-C9']::text[],'임시 정부를 세운 곳과 까닭을 잘못 안다(서울에, 도망가려고)','상하이 · 탄압을 피함 · 외교') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X17','soc',5,'u3',ARRAY['SO5-2-u3-C9']::text[],'임시 정부가 한 일과 일제가 한 일을 섞는다(토지 조사 사업을 임시 정부가 했다고)','비밀 연락망 · 신문 · 외교 활동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X18','soc',5,'u3',ARRAY['SO5-2-u3-C10']::text[],'한인 애국단을 흥사단·신흥 무관 학교와 헷갈린다','활동이 힘들 때 · 일제 주요 인물 처단') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X19','soc',5,'u3',ARRAY['SO5-2-u3-C11']::text[],'3·1 운동 뒤 일제가 부드럽게 다스려 우리 민족의 생활이 나아졌다고 여긴다','방법만 바꿈 · 분열 · 쌀을 더 가져감') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X20','soc',5,'u3',ARRAY['SO5-2-u3-C11']::text[],'쌀을 더 많이 생산했는데 농민이 더 배고팠던 까닭을 놓친다','쌀이 일본으로 실려 감') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X21','soc',5,'u3',ARRAY['SO5-2-u3-C12']::text[],'물산 장려 운동·농촌 계몽 운동·조선어 학회가 한 일을 바꾸어 짝짓는다','토산품 · 한글 가르치기 · 우리말 사전') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X22','soc',5,'u3',ARRAY['SO5-2-u3-C12']::text[],'물건·글·말로 힘을 기른 운동은 독립과 관계없다고 여기거나 무기를 든 싸움으로 안다','경제·글·말로 민족의 힘을 기름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X23','soc',5,'u3',ARRAY['SO5-2-u3-C13']::text[],'6·10 만세 운동과 광주 학생 항일 운동을 바꾸어 안다','장례식 날 서울 · 광주에서 차별에 맞서 전국으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X24','soc',5,'u3',ARRAY['SO5-2-u3-C13']::text[],'광주 학생 항일 운동을 학생끼리의 단순한 다툼으로만 보아 쌓여 있던 차별을 놓친다','한국 학생만 붙잡음 · 학교 속 차별') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X25','soc',5,'u3',ARRAY['SO5-2-u3-C14']::text[],'봉오동·청산리 전투를 나라 안에서 일어난 일이나 실력 기르기 운동으로 안다','만주 · 독립군 · 무장 투쟁') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X26','soc',5,'u3',ARRAY['SO5-2-u3-C12','SO5-2-u3-C14']::text[],'나라 안 실력 기르기와 나라 밖 무장 투쟁 가운데 하나만 독립에 필요했다고 여긴다','둘이 함께 독립을 향함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X27','soc',5,'u3',ARRAY['SO5-2-u3-C15']::text[],'일제가 철도와 항구를 우리 민족을 위해 놓았다고 여긴다','군대 이동 · 자원을 일본으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X28','soc',5,'u3',ARRAY['SO5-2-u3-C15']::text[],'도시가 커지면서 모든 사람이 근대 문물을 똑같이 누렸다고 여긴다','일본인이 산 곳 · 한국인이 산 곳 · 토막집') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X29','soc',5,'u3',ARRAY['SO5-2-u3-C16']::text[],'인공 조미료와 배달 문화를 모든 한국인이 누린 좋은 변화로만 본다','편리함과 그늘이 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X30','soc',5,'u3',ARRAY['SO5-2-u3-C17']::text[],'민족정신을 없애려는 정책의 까닭을 잘못 안다(우리 문화를 아껴서, 공부를 잘하라고)','일본 왕에 충성 · 침략 전쟁에 협조') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X31','soc',5,'u3',ARRAY['SO5-2-u3-C17']::text[],'강제 동원을 사람들이 원해서 간 일이나 물건만 가져간 일로 여긴다','사람과 물자를 모두 강제로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X32','soc',5,'u3',ARRAY['SO5-2-u3-C18']::text[],'한국광복군이 나라 안으로 들어와 일본군을 몰아냈다고 여기거나 의병과 헷갈린다','임시 정부가 만듦 · 작전 준비 중 일제 항복') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X33','soc',5,'u3',ARRAY['SO5-2-u3-C18']::text[],'역사 연구와 글쓰기는 저항이 아니라고 여긴다','역사 왜곡에 맞섬 · 민족의식을 일깨움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X34','soc',5,'u3',ARRAY['SO5-2-u3-C19']::text[],'광복이 연합국의 승리만으로 저절로 왔다고 여겨 우리 민족의 끊임없는 노력을 놓친다','독립운동 + 연합국 승리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X35','soc',5,'u3',ARRAY['SO5-2-u3-C19']::text[],'광복 뒤 달라진 생활을 거꾸로 안다(일본어 수업이 늘었다고, 일본식 이름을 계속 썼다고)','우리말 수업 · 원래 이름 · 한글 신문') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X36','soc',5,'u3',ARRAY['SO5-2-u3-C20']::text[],'대한민국 정부가 세워지는 차례를 바꾼다(정부 수립 뒤 총선거, 대통령 뒤 헌법)','총선거 → 헌법 → 대통령 → 정부 수립') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X37','soc',5,'u3',ARRAY['SO5-2-u3-C20']::text[],'38도선 남북에 들어온 군대를 바꾸거나 처음부터 남북이 따로 나라를 세우려 했다고 여긴다','남쪽 미군 · 북쪽 소련군 · 통일 정부 노력') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X38','soc',5,'u3',ARRAY['SO5-2-u3-C20']::text[],'5·10 총선거를 일부 사람만 뽑은 선거나 남북 모두에서 치른 선거로 안다','남한에서만 · 첫 민주 선거 · 남녀 모두') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X39','soc',5,'u3',ARRAY['SO5-2-u3-C21']::text[],'6·25 전쟁을 남한이 먼저 일으켰다고 하거나 전쟁이 펼쳐진 차례를 바꾼다','남침 → 낙동강 → 인천 상륙 → 압록강 → 중국군 → 정전') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X40','soc',5,'u3',ARRAY['SO5-2-u3-C21']::text[],'정전 협정으로 전쟁이 완전히 끝났다고 여긴다','전투를 잠시 멈춤 · 휴전선 · 분단') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X41','soc',5,'u3',ARRAY['SO5-2-u3-C22']::text[],'전쟁 중에는 배움이 완전히 멈췄다고 여기거나 피란민의 생활을 편했다고 여긴다','천막 학교 · 움막·판잣집 · 물 부족') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X42','soc',5,'u3',ARRAY['SO5-2-u3-C21','SO5-2-u3-C22']::text[],'인천 상륙 작전과 흥남 철수를 바꾸어 안다','인천 = 서울 되찾음 · 흥남 = 피란민을 태운 배') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X43','soc',5,'u3',ARRAY['SO5-2-u3-C23']::text[],'6·25 전쟁의 피해를 군인만의 일이나 그때만의 일로 여겨 오늘날까지 이어진 영향을 놓친다','민간인도 · 이산가족 · 분단이 오늘까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X44','soc',5,'u3',ARRAY['SO5-2-u3-C23']::text[],'이산가족과 전쟁고아를 바꾸어 안다','이산가족 = 헤어진 가족 · 전쟁고아 = 부모를 잃은 아이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X45','soc',5,'u3',ARRAY['SO5-2-u3-C24']::text[],'기념일과 기념하는 일을 잘못 짝짓거나 기념일 옷에 사실과 다른 그림·문구를 넣는다','기념일의 뜻 · 사실에 맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X46','soc',5,'u3',ARRAY['SO5-2-u3-C1','SO5-2-u3-C8','SO5-2-u3-C21']::text[],'단원의 일들을 차례대로 놓지 못하고 섞는다(6·25 전쟁 뒤 3·1 운동, 광복 전 정부 수립)','늑약 → 식민 통치와 저항 → 광복 → 정부 수립 → 6·25 전쟁') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-2-u3-X47','soc',5,'u3',ARRAY['SO5-2-u3-C1','SO5-2-u3-C19','SO5-2-u3-C23']::text[],'사건 이름과 날짜를 외우는 것만 역사 공부로 여겨 사람들의 생활이 어떻게 달라졌는지 놓친다','외우기보다 생활과 잇기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_basic#1','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C1',1,'mc','auto','다른 나라가 힘으로 빼앗아 다스리는 것을 무엇이라고 하나요?',ARRAY['SO5-2-u3-X02']::text[],false,'{"seq":1,"concept":"SO5-2-u3-C1","difficulty":1,"kind":"mc","stem":"다른 나라가 힘으로 빼앗아 다스리는 것을 무엇이라고 하나요?","options":[{"t":"식민 통치","correct":true},{"t":"광복","mis":"SO5-2-u3-X02"},{"t":"개항","mis":"SO5-2-u3-X02"},{"t":"정부 수립","mis":"SO5-2-u3-X02"}],"explanation":["힘으로 빼앗았어요.","그 나라가 다스려요.","식민 통치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_basic#2','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C2',1,'sa','auto','황제가 반대했는데도 일제가 억지로 맺어 대한 제국의 외교권을 빼앗은 조약은 무엇인가요? (을○○○)','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u3-C2","difficulty":1,"kind":"sa","stem":"황제가 반대했는데도 일제가 억지로 맺어 대한 제국의 외교권을 빼앗은 조약은 무엇인가요? (을○○○)","answer":["을사늑약"],"explanation":["억지로 맺었어요.","외교권을 빼앗겼어요.","을사늑약이에요."],"mis":"SO5-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_basic#3','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C4',1,'mc','auto','나라를 지키려고 스스로 일어나 일제와 싸운 사람들을 무엇이라고 하나요?',ARRAY['SO5-2-u3-X05','SO5-2-u3-X09','SO5-2-u3-X06']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C4","difficulty":1,"kind":"mc","stem":"나라를 지키려고 스스로 일어나 일제와 싸운 사람들을 무엇이라고 하나요?","options":[{"t":"의병","correct":true},{"t":"특사","mis":"SO5-2-u3-X05"},{"t":"헌병","mis":"SO5-2-u3-X09"},{"t":"신하","mis":"SO5-2-u3-X06"}],"explanation":["스스로 일어났어요.","일제와 싸웠어요.","의병이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_basic#4','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C3',1,'ox','auto','황제는 을사늑약이 무효임을 알리려고 헤이그의 평화 회의에 특사를 보냈어요.',ARRAY['SO5-2-u3-X05']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C3","difficulty":1,"kind":"ox","stem":"황제는 을사늑약이 무효임을 알리려고 헤이그의 평화 회의에 특사를 보냈어요.","answer":"O","reason_options":[{"t":"늑약의 부당함을 세계에 알리려 했기 때문에","correct":true},{"t":"특사가 늑약에 이름을 쓰러 갔기 때문에","mis":"SO5-2-u3-X05"}],"mis":"SO5-2-u3-X05","explanation":["황제는 반대했어요.","특사를 보냈어요.","무효임을 알리려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_basic#5','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C2',2,'mc','auto','어느 조약의 내용 메모로 보아 이 조약으로 대한 제국이 빼앗긴 권리는 어느 것인가요?',ARRAY['SO5-2-u3-X03']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C2","difficulty":2,"kind":"mc","stem":"어느 조약의 내용 메모로 보아 이 조약으로 대한 제국이 빼앗긴 권리는 어느 것인가요?","options":[{"t":"외교권","correct":true},{"t":"화폐를 만드는 권리","mis":"SO5-2-u3-X03"},{"t":"농사짓는 권리","mis":"SO5-2-u3-X03"},{"t":"학교를 세우는 권리","mis":"SO5-2-u3-X03"}],"explanation":["외교를 일본이 감독해요.","다른 나라와 조약을 못 맺어요.","외교권이에요."],"asset":{"type":"passage","lines":["제1조 — 일본 정부가 대한 제국의 외교에 관한 일을 모두 감독한다.","제2조 — 대한 제국은 일본을 거치지 않고는 다른 나라와 조약을 맺지 못한다.","— 황제는 끝까지 반대했지만 일본 군대가 궁궐을 둘러쌌다."],"title":"어느 조약의 내용 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_basic#6','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C2',2,'mc','auto','을사늑약을 「늑약」이라고 부르는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X04']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C2","difficulty":2,"kind":"mc","stem":"을사늑약을 「늑약」이라고 부르는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"황제가 반대했는데도 일제가 군대를 앞세워 억지로 맺었기 때문에","correct":true},{"t":"두 나라가 뜻을 모아 기쁘게 맺었기 때문에","mis":"SO5-2-u3-X04"},{"t":"대한 제국이 먼저 맺자고 했기 때문에","mis":"SO5-2-u3-X04"},{"t":"조약을 맺은 곳의 이름이 「늑」이기 때문에","mis":"SO5-2-u3-X04"}],"explanation":["늑약은 억지로 맺은 조약이에요.","황제는 반대했어요.","군대를 앞세웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_basic#7','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C4',2,'mc','auto','의병 운동이 더욱 활발해진 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X07','SO5-2-u3-X05']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C4","difficulty":2,"kind":"mc","stem":"의병 운동이 더욱 활발해진 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"대한 제국 군대가 해산되자 군인들이 의병에 들어갔다","correct":true},{"t":"일제가 의병에게 무기를 나누어 주었다","mis":"SO5-2-u3-X07"},{"t":"헤이그 특사가 회의에서 이겼다","mis":"SO5-2-u3-X05"},{"t":"다른 나라 군대가 대신 싸워 주었다","mis":"SO5-2-u3-X07"}],"explanation":["군대가 해산되었어요.","군인들이 합류했어요.","훈련된 솜씨로 싸웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_basic#8','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C1',2,'mc','auto','이 단원에서 공부할 두 주제를 차례로 바르게 놓은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C1","difficulty":2,"kind":"mc","stem":"이 단원에서 공부할 두 주제를 차례로 바르게 놓은 것은 어느 것인가요?","options":[{"t":"식민 통치와 저항으로 달라진 생활 → 8·15 광복과 6·25 전쟁으로 달라진 생활","correct":true},{"t":"8·15 광복과 6·25 전쟁으로 달라진 생활 → 식민 통치와 저항으로 달라진 생활","mis":"SO5-2-u3-X46"},{"t":"조선의 건국 → 개항 이후 달라진 생활","mis":"SO5-2-u3-X46"},{"t":"6·25 전쟁 → 3·1 운동","mis":"SO5-2-u3-X46"}],"explanation":["먼저 나라를 빼앗겼어요.","그다음 되찾았어요.","그 뒤 전쟁이 있었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_basic#9','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C4',2,'ox','auto','외국 기자의 의병 취재 메모를 보면 의병에는 훈련받은 군인만 있었어요.',ARRAY['SO5-2-u3-X06']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C4","difficulty":2,"kind":"ox","stem":"외국 기자의 의병 취재 메모를 보면 의병에는 훈련받은 군인만 있었어요.","answer":"X","reason_options":[{"t":"낡은 한복 차림의 젊은이와 군인이 섞여 여러 사람이 함께했기 때문에","correct":true},{"t":"의병은 나라에서 뽑은 군인으로만 이루어졌기 때문에","mis":"SO5-2-u3-X06"}],"mis":"SO5-2-u3-X06","explanation":["한복 차림 젊은이가 있어요.","군인도 섞였어요.","여러 사람이 함께했어요."],"asset":{"type":"passage","lines":["외국 기자가 산골 마을에서 의병들을 만났다.","낡은 한복 차림의 젊은이와 군복을 입은 군인이 섞여 있었다.","제대로 쓸 만한 총은 몇 자루 없었다.","그래도 「나라를 지키다 죽는 편이 노예로 사는 것보다 낫다」고 했다."],"title":"외국 기자의 의병 취재 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_basic#10','soc',5,2,'u3','L01','g5_2_soc_u3_L01_basic','lesson_basic','SO5-2-u3-C3',3,'error','auto','을사늑약 뒤의 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X05','SO5-2-u3-X01','SO5-2-u3-X07']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C3","difficulty":3,"kind":"error","stem":"을사늑약 뒤의 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「헤이그 특사가 회의에서 연설해서 늑약을 바로 없앴어.」","correct":true,"mis_target":"SO5-2-u3-X05"},{"t":"준우 — 「상인은 가게 문을 닫고 학생은 등교를 거부했어.」","mis":"SO5-2-u3-X01"},{"t":"하린 — 「해산된 군인들이 의병에 들어갔어.」","mis":"SO5-2-u3-X07"}],"explanation":["특사는 회의장에 못 들어갔어요.","기자들에게 알렸어요.","서아의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_challenge#1','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C1',2,'match','auto','단원의 중요한 용어와 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C1","difficulty":2,"kind":"match","stem":"단원의 중요한 용어와 뜻을 알맞게 이으세요.","pairs":[{"l":"식민 통치","r":"힘으로 빼앗아 다스림"},{"l":"저항","r":"빼앗김에 맞서 싸움"},{"l":"광복","r":"빼앗긴 나라를 되찾음"}],"mis":"SO5-2-u3-X02","explanation":["빼앗아 다스리면 식민 통치예요.","맞서면 저항이에요.","되찾으면 광복이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_challenge#2','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C4',2,'mc','auto','의병들이 만주와 연해주로 건너간 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X12','SO5-2-u3-X05','SO5-2-u3-X07']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C4","difficulty":2,"kind":"mc","stem":"의병들이 만주와 연해주로 건너간 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"일제가 큰 부대로 탄압해 나라 안에서 싸우기 어려워졌기 때문에","correct":true},{"t":"만주에서 편히 쉬려고","mis":"SO5-2-u3-X12"},{"t":"특사와 함께 평화 회의에 가려고","mis":"SO5-2-u3-X05"},{"t":"농사지을 땅을 사려고","mis":"SO5-2-u3-X07"}],"explanation":["일제가 큰 부대로 눌렀어요.","나라 안에서 어려워졌어요.","나라 밖에서 싸움을 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_challenge#3','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C2',3,'mc','auto','어느 조약의 내용 메모 제2조 때문에 대한 제국이 겪게 될 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X03']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C2","difficulty":3,"kind":"mc","stem":"어느 조약의 내용 메모 제2조 때문에 대한 제국이 겪게 될 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어려운 처지를 다른 나라에 직접 알리고 도움을 청하기 어려워진다","correct":true},{"t":"다른 나라와 마음대로 조약을 맺을 수 있다","mis":"SO5-2-u3-X03"},{"t":"학교에서 일본어를 배우지 않아도 된다","mis":"SO5-2-u3-X03"},{"t":"백성이 세금을 내지 않아도 된다","mis":"SO5-2-u3-X03"}],"explanation":["일본을 거쳐야 해요.","직접 조약을 못 맺어요.","도움을 청하기 어려워요."],"asset":{"type":"passage","lines":["제1조 — 일본 정부가 대한 제국의 외교에 관한 일을 모두 감독한다.","제2조 — 대한 제국은 일본을 거치지 않고는 다른 나라와 조약을 맺지 못한다.","— 황제는 끝까지 반대했지만 일본 군대가 궁궐을 둘러쌌다."],"title":"어느 조약의 내용 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_challenge#4','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C3',3,'mc','auto','헤이그 특사가 회의장에는 들어가지 못했지만 한 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X05','SO5-2-u3-X04']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C3","difficulty":3,"kind":"mc","stem":"헤이그 특사가 회의장에는 들어가지 못했지만 한 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 나라 기자들 앞에서 대한 제국의 처지와 늑약의 부당함을 알렸다","correct":true},{"t":"아무것도 하지 못하고 돌아와 소용이 없었다","mis":"SO5-2-u3-X05"},{"t":"일본과 새 조약을 맺고 돌아왔다","mis":"SO5-2-u3-X04"},{"t":"회의에서 늑약을 무효로 만들었다","mis":"SO5-2-u3-X05"}],"explanation":["회의장은 막혔어요.","기자들을 만났어요.","세계에 부당함을 알렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_challenge#5','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C1',3,'ox','auto','일제가 다스리던 시기에도 우리 민족은 감시 속에서 여러 방법으로 일제에 맞섰어요.',ARRAY['SO5-2-u3-X01']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C1","difficulty":3,"kind":"ox","stem":"일제가 다스리던 시기에도 우리 민족은 감시 속에서 여러 방법으로 일제에 맞섰어요.","answer":"O","reason_options":[{"t":"의병·만세·몰래 돕기처럼 나라를 되찾을 때까지 저항이 이어졌기 때문에","correct":true},{"t":"힘이 약해 아무것도 하지 못했기 때문에","mis":"SO5-2-u3-X01"}],"mis":"SO5-2-u3-X01","explanation":["감시가 심했어요.","그래도 맞섰어요.","저항은 이어졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_challenge#6','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C4',3,'error','auto','의병을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X06','SO5-2-u3-X07']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C4","difficulty":3,"kind":"error","stem":"의병을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「의병은 나라에서 월급을 받는 군인만 될 수 있었어.」","correct":true,"mis_target":"SO5-2-u3-X06"},{"t":"지안 — 「여성도 노래를 지어 의병을 북돋웠어.」","mis":"SO5-2-u3-X06"},{"t":"민재 — 「탄압을 피해 만주와 연해주로 건너가 싸웠어.」","mis":"SO5-2-u3-X07"}],"explanation":["스스로 일어난 사람들이에요.","여성·농민도 있었어요.","태오의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_challenge#7','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C2',3,'mc','auto','「을사늑약 → 헤이그 특사 → 의병 운동」을 까닭과 일로 바르게 이은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46','SO5-2-u3-X05','SO5-2-u3-X03']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C2","difficulty":3,"kind":"mc","stem":"「을사늑약 → 헤이그 특사 → 의병 운동」을 까닭과 일로 바르게 이은 것은 어느 것인가요?","options":[{"t":"외교권을 빼앗겨서 → 황제는 특사로 부당함을 알리려 했고 → 사람들은 의병을 일으켜 맞섰다","correct":true},{"t":"의병이 일어나서 → 늑약을 맺었고 → 특사를 보냈다","mis":"SO5-2-u3-X46"},{"t":"특사가 회의에서 이겨서 → 늑약이 없어지고 → 의병이 흩어졌다","mis":"SO5-2-u3-X05"},{"t":"외교권을 되찾아서 → 의병이 해산했다","mis":"SO5-2-u3-X03"}],"explanation":["먼저 외교권을 빼앗겼어요.","황제는 세계에 알렸어요.","사람들은 의병으로 맞섰어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_challenge#8','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C1',4,'mc','auto','어느 거리 그림에서 개항 이후 들어온 모습이 아니라 이 단원에서 새로 나타난 모습끼리 짝지은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C1","difficulty":4,"kind":"mc","stem":"어느 거리 그림에서 개항 이후 들어온 모습이 아니라 이 단원에서 새로 나타난 모습끼리 짝지은 것은 어느 것인가요?","options":[{"t":"㉱ 태극기를 든 학생들 · ㉲ 기차역으로 향하는 쌀가마 수레","correct":true},{"t":"㉮ 전차가 지나는 큰길 · ㉯ 양복 가게","mis":"SO5-2-u3-X46"},{"t":"㉯ 자전거 가게 · ㉮ 전차","mis":"SO5-2-u3-X46"},{"t":"㉰ 한복과 서양식 옷 · ㉯ 양복 가게","mis":"SO5-2-u3-X46"}],"explanation":["전차·양복은 개항 뒤 들어왔어요.","태극기는 맞서는 모습이에요.","쌀이 실려 가는 모습도 새로워요."],"asset":{"type":"passage","lines":["㉮ 전차가 지나는 큰길","㉯ 자전거 가게와 양복 가게","㉰ 한복과 서양식 옷을 입은 사람들","㉱ 태극기를 든 학생들","㉲ 기차역으로 향하는 쌀가마 수레"],"title":"어느 거리 그림 살피기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_challenge#9','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C4',4,'mc','auto','「안사람 의병가」를 쉬운 말로 읽고, 노래를 지은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X06','SO5-2-u3-X01']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C4","difficulty":4,"kind":"mc","stem":"「안사람 의병가」를 쉬운 말로 읽고, 노래를 지은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라를 지키는 일에 여성들도 함께하자고 힘을 북돋우려고","correct":true},{"t":"여성은 집안일만 하라고 알리려고","mis":"SO5-2-u3-X06"},{"t":"의병을 그만두라고 말리려고","mis":"SO5-2-u3-X01"},{"t":"일제에게 잘 보이려고","mis":"SO5-2-u3-X01"}],"explanation":["여성 의병장이 지었어요.","집에만 있을 수 없다고 했어요.","함께 나라를 지키자는 노래예요."],"asset":{"type":"passage","lines":["한 여성 의병장이 마을 여성들에게 노래를 지어 불러 주었다.","나라가 위태로운데 여성이라고 집에만 있을 수 없다는 내용이다.","힘을 모아 의병을 돕고 나라를 지키자고 북돋웠다."],"title":"「안사람 의병가」를 쉬운 말로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L01_challenge#10','soc',5,2,'u3','L01','g5_2_soc_u3_L01_challenge','lesson_challenge','SO5-2-u3-C2',4,'essay','teacher','을사늑약이 대한 제국에 준 영향을 쓰고, 이에 맞선 사람들의 노력을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u3-C2","difficulty":4,"kind":"essay","stem":"을사늑약이 대한 제국에 준 영향을 쓰고, 이에 맞선 사람들의 노력을 두 가지 쓰세요.","answer_guide":{"answer":"예: 을사늑약으로 대한 제국은 일본을 거치지 않고는 다른 나라와 조약을 맺을 수 없게 되어 외교권을 빼앗겼다. 황제는 헤이그 평화 회의에 특사를 보내 늑약이 무효임을 세계에 알리려 했고, 사람들은 곳곳에서 의병을 일으켜 일제와 싸웠다.","scoring_points":["외교권을 빼앗긴 영향을 썼는가","맞선 노력 두 가지를 썼는가","노력의 뜻(부당함 알리기·나라 지키기)을 썼는가"]},"explanation":["외교권을 빼앗겼어요.","특사와 의병이 있어요.","뜻을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_basic#1','soc',5,2,'u3','L02','g5_2_soc_u3_L02_basic','lesson_basic','SO5-2-u3-C5',1,'sa','auto','일제가 나라를 빼앗은 뒤 우리나라를 다스리려고 세운 기관은 무엇인가요? (조선 ○○○)','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C5","difficulty":1,"kind":"sa","stem":"일제가 나라를 빼앗은 뒤 우리나라를 다스리려고 세운 기관은 무엇인가요? (조선 ○○○)","answer":["조선 총독부","조선총독부","총독부"],"explanation":["일제가 세웠어요.","군인 출신이 우두머리였어요.","조선 총독부예요."],"mis":"SO5-2-u3-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_basic#2','soc',5,2,'u3','L02','g5_2_soc_u3_L02_basic','lesson_basic','SO5-2-u3-C5',1,'mc','auto','군대에서 경찰 일을 하는 군인으로, 일제가 한국인을 감시하게 한 사람들은 누구인가요?',ARRAY['SO5-2-u3-X09']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C5","difficulty":1,"kind":"mc","stem":"군대에서 경찰 일을 하는 군인으로, 일제가 한국인을 감시하게 한 사람들은 누구인가요?","options":[{"t":"헌병","correct":true},{"t":"의병","mis":"SO5-2-u3-X09"},{"t":"특사","mis":"SO5-2-u3-X09"},{"t":"독립군","mis":"SO5-2-u3-X09"}],"explanation":["군인이에요.","경찰 일을 했어요.","헌병이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_basic#3','soc',5,2,'u3','L02','g5_2_soc_u3_L02_basic','lesson_basic','SO5-2-u3-C6',1,'mc','auto','일제가 땅 주인을 확인한다며 전국에서 벌인 일은 어느 것인가요?',ARRAY['SO5-2-u3-X21','SO5-2-u3-X15']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C6","difficulty":1,"kind":"mc","stem":"일제가 땅 주인을 확인한다며 전국에서 벌인 일은 어느 것인가요?","options":[{"t":"토지 조사 사업","correct":true},{"t":"물산 장려 운동","mis":"SO5-2-u3-X21"},{"t":"농촌 계몽 운동","mis":"SO5-2-u3-X21"},{"t":"3·1 운동","mis":"SO5-2-u3-X15"}],"explanation":["땅을 조사했어요.","일제가 벌였어요.","토지 조사 사업이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_basic#4','soc',5,2,'u3','L02','g5_2_soc_u3_L02_basic','lesson_basic','SO5-2-u3-C7',1,'ox','auto','독립운동가들은 만주에 신흥 무관 학교를 세워 독립군을 길렀어요.',ARRAY['SO5-2-u3-X12']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C7","difficulty":1,"kind":"ox","stem":"독립운동가들은 만주에 신흥 무관 학교를 세워 독립군을 길렀어요.","answer":"O","reason_options":[{"t":"나라 밖에서 힘을 길러 독립을 이루려 했기 때문에","correct":true},{"t":"만주에서 농사만 지으려 했기 때문에","mis":"SO5-2-u3-X12"}],"mis":"SO5-2-u3-X12","explanation":["만주에 세웠어요.","독립군을 길렀어요.","나라 밖 독립운동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_basic#5','soc',5,2,'u3','L02','g5_2_soc_u3_L02_basic','lesson_basic','SO5-2-u3-C5',2,'mc','auto','나라를 빼앗긴 뒤의 어느 교실에서 알 수 있는 일제의 통치 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X09']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C5","difficulty":2,"kind":"mc","stem":"나라를 빼앗긴 뒤의 어느 교실에서 알 수 있는 일제의 통치 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"교사에게도 칼을 차게 해 공포 분위기를 만들고 일본어를 가르쳤다","correct":true},{"t":"우리말과 역사를 마음껏 가르쳤다","mis":"SO5-2-u3-X09"},{"t":"학생들이 자유롭게 묻고 답했다","mis":"SO5-2-u3-X09"},{"t":"교사는 학생을 지켜 주려고 칼을 찼다","mis":"SO5-2-u3-X09"}],"explanation":["선생님이 칼을 찼어요.","교과서가 일본어예요.","겁을 주어 다스렸어요."],"asset":{"type":"passage","lines":["교단의 선생님이 제복을 입고 허리에 칼을 찼다.","국어 교과서에는 우리말이 아니라 일본어가 적혀 있다.","학생들은 고개를 숙인 채 조용히 받아 적었다."],"title":"나라를 빼앗긴 뒤의 어느 교실"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_basic#6','soc',5,2,'u3','L02','g5_2_soc_u3_L02_basic','lesson_basic','SO5-2-u3-C5',2,'mc','auto','일제가 헌병에게 경찰 일을 맡긴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X09']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C5","difficulty":2,"kind":"mc","stem":"일제가 헌병에게 경찰 일을 맡긴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한국인을 감시하고 독립운동을 막으려고","correct":true},{"t":"한국인의 안전을 지켜 주려고","mis":"SO5-2-u3-X09"},{"t":"군인이 남아돌아서","mis":"SO5-2-u3-X09"},{"t":"학교를 많이 세우려고","mis":"SO5-2-u3-X09"}],"explanation":["헌병은 군인이에요.","감시했어요.","독립운동을 막으려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_basic#7','soc',5,2,'u3','L02','g5_2_soc_u3_L02_basic','lesson_basic','SO5-2-u3-C6',2,'mc','auto','토지 조사 사업 탐구 메모로 보아 이 사업 뒤 농민의 생활로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X10','SO5-2-u3-X11']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C6","difficulty":2,"kind":"mc","stem":"토지 조사 사업 탐구 메모로 보아 이 사업 뒤 농민의 생활로 알맞은 것은 어느 것인가요?","options":[{"t":"땅을 잃거나 남의 땅을 빌려 농사짓는 농민이 늘었다","correct":true},{"t":"모든 농민이 땅을 더 많이 갖게 되었다","mis":"SO5-2-u3-X10"},{"t":"자기 땅에서 농사짓는 농민이 늘었다","mis":"SO5-2-u3-X11"},{"t":"농민이 세금을 내지 않게 되었다","mis":"SO5-2-u3-X10"}],"explanation":["신고 못 한 땅을 빼앗겼어요.","빌려 짓는 농민이 늘었어요.","생활이 어려워졌어요."],"asset":{"type":"passage","lines":["① 일제는 땅 주인을 확인한다며 전국의 땅을 조사했다.","② 정해진 기간 안에 땅을 신고해야 했다.","③ 신고하지 못한 땅이나 마을이 함께 쓰던 땅은 빼앗기기도 했다.","④ 시간이 갈수록 남의 땅을 빌려 농사짓는 농민이 늘었다."],"title":"토지 조사 사업 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_basic#8','soc',5,2,'u3','L02','g5_2_soc_u3_L02_basic','lesson_basic','SO5-2-u3-C7',2,'mc','auto','나라 밖 독립운동 카드 나에 해당하는 것은 어느 것인가요?',ARRAY['SO5-2-u3-X13','SO5-2-u3-X08','SO5-2-u3-X18']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C7","difficulty":2,"kind":"mc","stem":"나라 밖 독립운동 카드 나에 해당하는 것은 어느 것인가요?","options":[{"t":"흥사단","correct":true},{"t":"신흥 무관 학교","mis":"SO5-2-u3-X13"},{"t":"조선 총독부","mis":"SO5-2-u3-X08"},{"t":"한인 애국단","mis":"SO5-2-u3-X18"}],"explanation":["미국에서 만들었어요.","실력을 키웠어요.","흥사단이에요."],"asset":{"type":"passage","lines":["가 — 만주에 세워 독립군을 기른 학교","나 — 미국에서 만들어 우리 민족의 실력을 키운 단체"],"title":"나라 밖 독립운동 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_basic#9','soc',5,2,'u3','L02','g5_2_soc_u3_L02_basic','lesson_basic','SO5-2-u3-C6',2,'ox','auto','토지 조사 사업은 농민의 땅을 지켜 주려고 한 일이었어요.',ARRAY['SO5-2-u3-X10']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C6","difficulty":2,"kind":"ox","stem":"토지 조사 사업은 농민의 땅을 지켜 주려고 한 일이었어요.","answer":"X","reason_options":[{"t":"땅 주인을 확인한다고 내세웠지만 실제로는 많은 농민이 땅을 잃었기 때문에","correct":true},{"t":"농민 모두가 땅 문서를 새로 받았기 때문에","mis":"SO5-2-u3-X10"}],"mis":"SO5-2-u3-X10","explanation":["내세운 까닭이 있어요.","실제로 벌어진 일을 봐요.","농민이 땅을 잃었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_basic#10','soc',5,2,'u3','L02','g5_2_soc_u3_L02_basic','lesson_basic','SO5-2-u3-C7',3,'error','auto','나라 밖 독립운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X12','SO5-2-u3-X09','SO5-2-u3-X13']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C7","difficulty":3,"kind":"error","stem":"나라 밖 독립운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「나라 밖으로 간 사람들은 다 무서워서 도망간 거야.」","correct":true,"mis_target":"SO5-2-u3-X12"},{"t":"소율 — 「감시가 심해 나라 안에서 활동하기 어려웠어.」","mis":"SO5-2-u3-X09"},{"t":"은호 — 「나라 밖에 학교와 단체를 세워 힘을 길렀어.」","mis":"SO5-2-u3-X13"}],"explanation":["나라 안은 감시가 심했어요.","나라 밖에서 힘을 길렀어요.","도윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_challenge#1','soc',5,2,'u3','L02','g5_2_soc_u3_L02_challenge','lesson_challenge','SO5-2-u3-C7',2,'match','auto','나라 밖 독립운동 카드와 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C7","difficulty":2,"kind":"match","stem":"나라 밖 독립운동 카드와 이름을 알맞게 이으세요.","pairs":[{"l":"가 만주 · 독립군","r":"신흥 무관 학교"},{"l":"나 미국 · 실력","r":"흥사단"}],"mis":"SO5-2-u3-X13","explanation":["만주는 독립군 학교예요.","미국은 실력을 키운 단체예요.","둘 다 나라 밖이에요."],"asset":{"type":"passage","lines":["가 — 만주에 세워 독립군을 기른 학교","나 — 미국에서 만들어 우리 민족의 실력을 키운 단체"],"title":"나라 밖 독립운동 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_challenge#2','soc',5,2,'u3','L02','g5_2_soc_u3_L02_challenge','lesson_challenge','SO5-2-u3-C5',2,'mc','auto','조선 총독부의 우두머리로 군인 출신을 앉힌 것으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u3-X09','SO5-2-u3-X08']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C5","difficulty":2,"kind":"mc","stem":"조선 총독부의 우두머리로 군인 출신을 앉힌 것으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"우리 민족을 힘으로 누르며 강압적으로 다스리려 했다","correct":true},{"t":"우리 민족의 뜻을 잘 들어 주려 했다","mis":"SO5-2-u3-X09"},{"t":"대한 제국을 다시 세워 주려 했다","mis":"SO5-2-u3-X08"},{"t":"학교를 더 자유롭게 만들려 했다","mis":"SO5-2-u3-X09"}],"explanation":["군인 출신이에요.","힘으로 다스렸어요.","강압적인 통치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_challenge#3','soc',5,2,'u3','L02','g5_2_soc_u3_L02_challenge','lesson_challenge','SO5-2-u3-C6',3,'mc','auto','토지 조사 사업 탐구 메모 ①과 ③을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X10','SO5-2-u3-X11']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C6","difficulty":3,"kind":"mc","stem":"토지 조사 사업 탐구 메모 ①과 ③을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"겉으로 내세운 까닭과 달리 농민들이 땅을 빼앗기는 일이 벌어졌다","correct":true},{"t":"일제는 내세운 까닭대로 농민을 도왔다","mis":"SO5-2-u3-X10"},{"t":"마을이 함께 쓰던 땅은 더 늘어났다","mis":"SO5-2-u3-X11"},{"t":"땅 조사는 농민과 아무 관계가 없었다","mis":"SO5-2-u3-X10"}],"explanation":["①은 내세운 까닭이에요.","③은 실제로 벌어진 일이에요.","둘이 달라요."],"asset":{"type":"passage","lines":["① 일제는 땅 주인을 확인한다며 전국의 땅을 조사했다.","② 정해진 기간 안에 땅을 신고해야 했다.","③ 신고하지 못한 땅이나 마을이 함께 쓰던 땅은 빼앗기기도 했다.","④ 시간이 갈수록 남의 땅을 빌려 농사짓는 농민이 늘었다."],"title":"토지 조사 사업 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_challenge#4','soc',5,2,'u3','L02','g5_2_soc_u3_L02_challenge','lesson_challenge','SO5-2-u3-C5',3,'mc','auto','칼을 찬 교사와 일본어 국어 교과서가 학생들에게 준 영향으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X09','SO5-2-u3-X01']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C5","difficulty":3,"kind":"mc","stem":"칼을 찬 교사와 일본어 국어 교과서가 학생들에게 준 영향으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학생들이 두려움 속에서 우리말과 우리 것을 제대로 배우지 못했다","correct":true},{"t":"학생들이 더 자유롭게 생각을 말했다","mis":"SO5-2-u3-X09"},{"t":"우리말 실력이 크게 늘었다","mis":"SO5-2-u3-X09"},{"t":"학생들이 일제에 맞설 마음을 모두 잃었다","mis":"SO5-2-u3-X01"}],"explanation":["공포 분위기였어요.","일본어를 배웠어요.","우리 것을 배우기 어려웠어요."],"asset":{"type":"passage","lines":["교단의 선생님이 제복을 입고 허리에 칼을 찼다.","국어 교과서에는 우리말이 아니라 일본어가 적혀 있다.","학생들은 고개를 숙인 채 조용히 받아 적었다."],"title":"나라를 빼앗긴 뒤의 어느 교실"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_challenge#5','soc',5,2,'u3','L02','g5_2_soc_u3_L02_challenge','lesson_challenge','SO5-2-u3-C7',3,'ox','auto','감시와 탄압이 심해지자 독립운동가들은 나라 밖에서 학교와 단체를 세워 독립운동을 이어 갔어요.',ARRAY['SO5-2-u3-X12']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C7","difficulty":3,"kind":"ox","stem":"감시와 탄압이 심해지자 독립운동가들은 나라 밖에서 학교와 단체를 세워 독립운동을 이어 갔어요.","answer":"O","reason_options":[{"t":"나라 안 활동이 어려워져 나라 밖에서 힘을 기르려 했기 때문에","correct":true},{"t":"나라 밖에서는 독립운동을 그만두었기 때문에","mis":"SO5-2-u3-X12"}],"mis":"SO5-2-u3-X12","explanation":["나라 안은 어려웠어요.","나라 밖으로 옮겼어요.","독립운동을 이어 갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_challenge#6','soc',5,2,'u3','L02','g5_2_soc_u3_L02_challenge','lesson_challenge','SO5-2-u3-C6',3,'error','auto','토지 조사 사업 뒤 농민의 모습을 그래프로 살펴본 친구들이 말했어요. 잘못 읽은 친구는 누구인가요?',ARRAY['SO5-2-u3-X11','SO5-2-u3-X10']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C6","difficulty":3,"kind":"error","stem":"토지 조사 사업 뒤 농민의 모습을 그래프로 살펴본 친구들이 말했어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"하준 — 「시간이 갈수록 자기 땅에서 농사짓는 농민이 늘었어.」","correct":true,"mis_target":"SO5-2-u3-X11"},{"t":"예린 — 「남의 땅을 빌려 짓는 농민이 늘었어.」","mis":"SO5-2-u3-X11"},{"t":"시우 — 「불리한 조건으로 계약한 농민도 많았어.」","mis":"SO5-2-u3-X10"}],"explanation":["빌려 짓는 농민이 늘었어요.","자기 땅 농민은 줄었어요.","하준이 거꾸로 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_challenge#7','soc',5,2,'u3','L02','g5_2_soc_u3_L02_challenge','lesson_challenge','SO5-2-u3-C7',3,'mc','auto','남겨진 어느 가족의 기록으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X12','SO5-2-u3-X47']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C7","difficulty":3,"kind":"mc","stem":"남겨진 어느 가족의 기록으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이름이 덜 알려진 사람들도 큰 고통을 견디며 독립운동을 도왔다","correct":true},{"t":"나라 밖 생활은 넉넉하고 편했다","mis":"SO5-2-u3-X12"},{"t":"독립군은 돈 걱정 없이 싸웠다","mis":"SO5-2-u3-X12"},{"t":"기록은 역사를 아는 데 쓸모가 없다","mis":"SO5-2-u3-X47"}],"explanation":["재산을 팔고 떠났어요.","굶는 날이 많았어요.","그래도 독립군을 도왔어요."],"asset":{"type":"passage","lines":["한 집안의 형제들이 집과 땅을 모두 팔았다.","가족을 이끌고 추운 겨울 강을 건너 만주로 갔다.","그곳에 학교를 세워 독립군을 길렀다.","하루 한 끼도 어려웠지만 옷을 지어 번 돈마저 독립군에게 보냈다."],"title":"남겨진 어느 가족의 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_challenge#8','soc',5,2,'u3','L02','g5_2_soc_u3_L02_challenge','lesson_challenge','SO5-2-u3-C5',4,'mc','auto','「헌병 경찰 → 나라 밖 독립운동」을 까닭과 일로 바르게 이은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46','SO5-2-u3-X09','SO5-2-u3-X10']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C5","difficulty":4,"kind":"mc","stem":"「헌병 경찰 → 나라 밖 독립운동」을 까닭과 일로 바르게 이은 것은 어느 것인가요?","options":[{"t":"헌병이 감시하고 탄압해서 → 나라 안 독립운동이 어려워졌고 → 독립운동가들은 나라 밖에 학교와 단체를 세웠다","correct":true},{"t":"나라 밖에 학교를 세워서 → 헌병이 생겼다","mis":"SO5-2-u3-X46"},{"t":"헌병이 독립운동을 도와서 → 독립군이 생겼다","mis":"SO5-2-u3-X09"},{"t":"토지 조사 사업으로 땅을 얻어서 → 만주로 갔다","mis":"SO5-2-u3-X10"}],"explanation":["헌병이 감시했어요.","나라 안이 어려워졌어요.","나라 밖에서 힘을 길렀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_challenge#9','soc',5,2,'u3','L02','g5_2_soc_u3_L02_challenge','lesson_challenge','SO5-2-u3-C6',4,'mc','auto','일제가 강압적으로 다스린 모습을 셋 모은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X13','SO5-2-u3-X08','SO5-2-u3-X09']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C6","difficulty":4,"kind":"mc","stem":"일제가 강압적으로 다스린 모습을 셋 모은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"헌병 경찰 · 칼을 찬 교사 · 토지 조사 사업","correct":true},{"t":"헌병 경찰 · 신흥 무관 학교 · 흥사단","mis":"SO5-2-u3-X13"},{"t":"의병 · 헤이그 특사 · 토지 조사 사업","mis":"SO5-2-u3-X08"},{"t":"우리말 교과서 · 칼을 찬 교사 · 흥사단","mis":"SO5-2-u3-X09"}],"explanation":["일제가 한 일을 골라요.","독립운동은 빼요.","셋 다 일제의 통치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L02_challenge#10','soc',5,2,'u3','L02','g5_2_soc_u3_L02_challenge','lesson_challenge','SO5-2-u3-C7',4,'essay','teacher','남겨진 어느 가족의 기록을 읽고, 이 가족이 만주로 간 까닭과 그곳에서 한 일을 쓰고, 이런 기록이 남아 있어 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u3-C7","difficulty":4,"kind":"essay","stem":"남겨진 어느 가족의 기록을 읽고, 이 가족이 만주로 간 까닭과 그곳에서 한 일을 쓰고, 이런 기록이 남아 있어 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 나라 안에서는 헌병의 감시와 탄압으로 독립운동이 어려워 재산을 모두 팔고 만주로 갔다. 그곳에서 학교를 세워 독립군을 길렀고 어렵게 번 돈도 독립군에게 보냈다. 이런 기록이 있어 이름이 덜 알려진 사람들의 고통과 노력까지 알 수 있다.","scoring_points":["만주로 간 까닭을 썼는가","그곳에서 한 일을 썼는가","기록이 남아 좋은 점을 썼는가"]},"explanation":["나라 안이 어려웠어요.","독립군을 길렀어요.","기록으로 노력을 알아요."],"asset":{"type":"passage","lines":["한 집안의 형제들이 집과 땅을 모두 팔았다.","가족을 이끌고 추운 겨울 강을 건너 만주로 갔다.","그곳에 학교를 세워 독립군을 길렀다.","하루 한 끼도 어려웠지만 옷을 지어 번 돈마저 독립군에게 보냈다."],"title":"남겨진 어느 가족의 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_basic#1','soc',5,2,'u3','L03','g5_2_soc_u3_L03_basic','lesson_basic','SO5-2-u3-C8',1,'mc','auto','독립 선언서 발표와 함께 시작되어 전국으로 퍼진 만세 시위는 어느 것인가요?',ARRAY['SO5-2-u3-X15','SO5-2-u3-X46']::text[],false,'{"seq":1,"concept":"SO5-2-u3-C8","difficulty":1,"kind":"mc","stem":"독립 선언서 발표와 함께 시작되어 전국으로 퍼진 만세 시위는 어느 것인가요?","options":[{"t":"3·1 운동","correct":true},{"t":"의병 운동","mis":"SO5-2-u3-X15"},{"t":"헤이그 특사","mis":"SO5-2-u3-X15"},{"t":"6·25 전쟁","mis":"SO5-2-u3-X46"}],"explanation":["독립 선언서를 읽었어요.","만세를 외쳤어요.","3·1 운동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_basic#2','soc',5,2,'u3','L03','g5_2_soc_u3_L03_basic','lesson_basic','SO5-2-u3-C9',1,'sa','auto','독립운동을 이끌 힘을 모으려고 중국 상하이에 세운 정부는 무엇인가요? (대한민국 ○○ ○○)','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u3-C9","difficulty":1,"kind":"sa","stem":"독립운동을 이끌 힘을 모으려고 중국 상하이에 세운 정부는 무엇인가요? (대한민국 ○○ ○○)","answer":["대한민국 임시 정부","대한민국임시정부","임시 정부","임시정부"],"explanation":["상하이에 세웠어요.","힘을 하나로 모았어요.","대한민국 임시 정부예요."],"mis":"SO5-2-u3-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_basic#3','soc',5,2,'u3','L03','g5_2_soc_u3_L03_basic','lesson_basic','SO5-2-u3-C10',1,'mc','auto','임시 정부의 활동이 힘들어지자 일제의 주요 인물을 처단하려고 만든 단체는 어느 것인가요?',ARRAY['SO5-2-u3-X18','SO5-2-u3-X08']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C10","difficulty":1,"kind":"mc","stem":"임시 정부의 활동이 힘들어지자 일제의 주요 인물을 처단하려고 만든 단체는 어느 것인가요?","options":[{"t":"한인 애국단","correct":true},{"t":"흥사단","mis":"SO5-2-u3-X18"},{"t":"신흥 무관 학교","mis":"SO5-2-u3-X18"},{"t":"조선 총독부","mis":"SO5-2-u3-X08"}],"explanation":["임시 정부가 만들었어요.","주요 인물을 처단했어요.","한인 애국단이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_basic#4','soc',5,2,'u3','L03','g5_2_soc_u3_L03_basic','lesson_basic','SO5-2-u3-C8',1,'ox','auto','3·1 운동 때 학생과 시민은 탑골 공원에서 독립 선언서를 읽고 만세를 외쳤어요.',ARRAY['SO5-2-u3-X15']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C8","difficulty":1,"kind":"ox","stem":"3·1 운동 때 학생과 시민은 탑골 공원에서 독립 선언서를 읽고 만세를 외쳤어요.","answer":"O","reason_options":[{"t":"여러 사람 앞에서 독립의 뜻을 널리 알리려 했기 때문에","correct":true},{"t":"탑골 공원에서 의병 훈련을 했기 때문에","mis":"SO5-2-u3-X15"}],"mis":"SO5-2-u3-X15","explanation":["탑골 공원에 모였어요.","선언서를 읽었어요.","만세를 외쳤어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_basic#5','soc',5,2,'u3','L03','g5_2_soc_u3_L03_basic','lesson_basic','SO5-2-u3-C8',2,'mc','auto','어느 만세 시위 기록으로 보아 3·1 운동에 함께한 사람들로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X15','SO5-2-u3-X14']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C8","difficulty":2,"kind":"mc","stem":"어느 만세 시위 기록으로 보아 3·1 운동에 함께한 사람들로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"민족 대표·학생·시민·농민·상인","correct":true},{"t":"훈련받은 군인들만","mis":"SO5-2-u3-X15"},{"t":"서울의 어른 몇 사람만","mis":"SO5-2-u3-X14"},{"t":"일본 경찰과 헌병","mis":"SO5-2-u3-X14"}],"explanation":["학생과 시민이 있어요.","농민과 상인도 있어요.","여러 사람이 함께했어요."],"asset":{"type":"passage","lines":["① 민족 대표들이 독립 선언서를 발표했다.","② 같은 시각 학생과 시민이 탑골 공원에서 선언서를 읽고 만세를 외쳤다.","③ 장날이면 농민들이 장터에 모여 만세를 불렀다.","④ 상인은 가게 문을 닫고 함께했다.","⑤ 일제는 총칼로 시위를 거칠게 눌렀다."],"title":"어느 만세 시위 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_basic#6','soc',5,2,'u3','L03','g5_2_soc_u3_L03_basic','lesson_basic','SO5-2-u3-C8',2,'mc','auto','3·1 운동이 퍼진 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X14']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C8","difficulty":2,"kind":"mc","stem":"3·1 운동이 퍼진 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"전국 곳곳으로 퍼져 석 달 넘게 이어졌다","correct":true},{"t":"서울에서 하루 만에 끝났다","mis":"SO5-2-u3-X14"},{"t":"나라 밖에서만 일어났다","mis":"SO5-2-u3-X14"},{"t":"일제가 시위를 반겨 주었다","mis":"SO5-2-u3-X14"}],"explanation":["장터까지 퍼졌어요.","전국으로 번졌어요.","석 달 넘게 이어졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_basic#7','soc',5,2,'u3','L03','g5_2_soc_u3_L03_basic','lesson_basic','SO5-2-u3-C9',2,'mc','auto','3·1 운동 뒤 대한민국 임시 정부를 세운 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X16','SO5-2-u3-X17']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C9","difficulty":2,"kind":"mc","stem":"3·1 운동 뒤 대한민국 임시 정부를 세운 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"독립운동을 이끌 힘을 하나로 모아야 함을 깨달았기 때문에","correct":true},{"t":"일제의 허락을 받았기 때문에","mis":"SO5-2-u3-X16"},{"t":"독립운동을 그만두려고","mis":"SO5-2-u3-X16"},{"t":"토지 조사 사업을 하려고","mis":"SO5-2-u3-X17"}],"explanation":["3·1 운동을 겪었어요.","힘을 모아야 했어요.","임시 정부를 세웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_basic#8','soc',5,2,'u3','L03','g5_2_soc_u3_L03_basic','lesson_basic','SO5-2-u3-C9',2,'mc','auto','상하이의 어느 정부가 한 일에 해당하지 않는 것은 어느 것인가요?',ARRAY['SO5-2-u3-X17']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C9","difficulty":2,"kind":"mc","stem":"상하이의 어느 정부가 한 일에 해당하지 않는 것은 어느 것인가요?","options":[{"t":"땅 주인을 확인한다며 전국의 땅을 조사했다","correct":true},{"t":"비밀 연락망으로 독립운동을 이끌었다","mis":"SO5-2-u3-X17"},{"t":"신문을 만들어 활동을 알렸다","mis":"SO5-2-u3-X17"},{"t":"외교 활동으로 독립의 뜻을 알렸다","mis":"SO5-2-u3-X17"}],"explanation":["㉮·㉯·㉰는 임시 정부가 했어요.","땅 조사는 일제가 했어요.","토지 조사 사업은 해당하지 않아요."],"asset":{"type":"passage","lines":["㉮ 비밀 연락망으로 나라 안 독립운동을 이끌고 돈을 모았다.","㉯ 신문을 만들어 활동을 알렸다.","㉰ 여러 나라에 독립의 뜻을 알리는 외교 활동을 했다."],"title":"상하이의 어느 정부가 한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_basic#9','soc',5,2,'u3','L03','g5_2_soc_u3_L03_basic','lesson_basic','SO5-2-u3-C10',2,'ox','auto','한인 애국단은 미국에서 만들어 우리 민족의 실력을 키운 단체예요.',ARRAY['SO5-2-u3-X18']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C10","difficulty":2,"kind":"ox","stem":"한인 애국단은 미국에서 만들어 우리 민족의 실력을 키운 단체예요.","answer":"X","reason_options":[{"t":"임시 정부의 활동이 힘들 때 만들어 일제의 주요 인물을 처단한 단체이기 때문에","correct":true},{"t":"흥사단과 한인 애국단은 같은 단체이기 때문에","mis":"SO5-2-u3-X18"}],"mis":"SO5-2-u3-X18","explanation":["미국 단체는 흥사단이에요.","한인 애국단은 임시 정부가 만들었어요.","설명이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_basic#10','soc',5,2,'u3','L03','g5_2_soc_u3_L03_basic','lesson_basic','SO5-2-u3-C8',3,'error','auto','3·1 운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X14','SO5-2-u3-X09']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C8","difficulty":3,"kind":"error","stem":"3·1 운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤아 — 「3·1 운동은 서울에서 어른들만 하루 만세를 부르고 끝났어.」","correct":true,"mis_target":"SO5-2-u3-X14"},{"t":"건우 — 「어린 학생도 고향에 내려가 장날 만세를 이끌었어.」","mis":"SO5-2-u3-X14"},{"t":"채원 — 「일제는 시위를 거칠게 눌렀어.」","mis":"SO5-2-u3-X09"}],"explanation":["전국으로 퍼졌어요.","학생·농민·상인도 함께했어요.","윤아의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_challenge#1','soc',5,2,'u3','L03','g5_2_soc_u3_L03_challenge','lesson_challenge','SO5-2-u3-C9',2,'match','auto','임시 정부가 한 일과 그 일로 이루려 한 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C9","difficulty":2,"kind":"match","stem":"임시 정부가 한 일과 그 일로 이루려 한 것을 알맞게 이으세요.","pairs":[{"l":"비밀 연락망","r":"나라 안 독립운동 이끌기"},{"l":"신문 만들기","r":"활동을 널리 알리기"},{"l":"외교 활동","r":"세계에 독립 의지 알리기"}],"mis":"SO5-2-u3-X17","explanation":["연락망으로 이끌었어요.","신문으로 알렸어요.","외교로 세계에 알렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_challenge#2','soc',5,2,'u3','L03','g5_2_soc_u3_L03_challenge','lesson_challenge','SO5-2-u3-C9',2,'mc','auto','대화를 읽고, 임시 정부를 상하이에 세운 까닭으로 알맞은 것끼리 짝지은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X16','SO5-2-u3-X17']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C9","difficulty":2,"kind":"mc","stem":"대화를 읽고, 임시 정부를 상하이에 세운 까닭으로 알맞은 것끼리 짝지은 것은 어느 것인가요?","options":[{"t":"일제의 탄압을 피하기 쉽고 외교 활동에 유리했다","correct":true},{"t":"우리 땅에서 가장 가까운 섬이었다","mis":"SO5-2-u3-X16"},{"t":"일제가 정부를 세우라고 허락했다","mis":"SO5-2-u3-X16"},{"t":"땅을 조사하기 좋은 곳이었다","mis":"SO5-2-u3-X17"}],"explanation":["탄압을 피하기 쉬웠어요.","외교에 좋았어요.","두 까닭이 맞아요."],"asset":{"type":"speech","turns":[{"who":"지민","text":"상하이는 일제의 탄압을 피하기 쉬웠대."},{"who":"하람","text":"여러 나라 사람이 모여 외교 활동을 하기에도 좋았대."},{"who":"선생님","text":"그럼 정부를 세운 까닭부터 다시 생각해 볼까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_challenge#3','soc',5,2,'u3','L03','g5_2_soc_u3_L03_challenge','lesson_challenge','SO5-2-u3-C8',3,'mc','auto','어느 만세 시위 기록 ③에서 농민들이 장날을 골라 만세를 부른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X14','SO5-2-u3-X15']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C8","difficulty":3,"kind":"mc","stem":"어느 만세 시위 기록 ③에서 농민들이 장날을 골라 만세를 부른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"장날에는 많은 사람이 한곳에 모여 소식을 퍼뜨리기 좋았기 때문에","correct":true},{"t":"장날에는 헌병이 하나도 없었기 때문에","mis":"SO5-2-u3-X14"},{"t":"장날에는 일제가 만세를 허락했기 때문에","mis":"SO5-2-u3-X14"},{"t":"장터에서 의병 훈련을 했기 때문에","mis":"SO5-2-u3-X15"}],"explanation":["장날엔 사람이 모여요.","소식이 퍼지기 좋아요.","그래서 장날을 골랐어요."],"asset":{"type":"passage","lines":["① 민족 대표들이 독립 선언서를 발표했다.","② 같은 시각 학생과 시민이 탑골 공원에서 선언서를 읽고 만세를 외쳤다.","③ 장날이면 농민들이 장터에 모여 만세를 불렀다.","④ 상인은 가게 문을 닫고 함께했다.","⑤ 일제는 총칼로 시위를 거칠게 눌렀다."],"title":"어느 만세 시위 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_challenge#4','soc',5,2,'u3','L03','g5_2_soc_u3_L03_challenge','lesson_challenge','SO5-2-u3-C8',3,'mc','auto','3·1 운동이 그 뒤 독립운동에 준 영향으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X01','SO5-2-u3-X46']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C8","difficulty":3,"kind":"mc","stem":"3·1 운동이 그 뒤 독립운동에 준 영향으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"힘을 하나로 모을 필요를 깨달아 대한민국 임시 정부를 세웠다","correct":true},{"t":"독립운동이 모두 멈추었다","mis":"SO5-2-u3-X01"},{"t":"대한 제국 군대가 다시 생겼다","mis":"SO5-2-u3-X46"},{"t":"토지 조사 사업이 시작되었다","mis":"SO5-2-u3-X46"}],"explanation":["온 민족이 함께했어요.","힘을 모아야 했어요.","임시 정부가 생겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_challenge#5','soc',5,2,'u3','L03','g5_2_soc_u3_L03_challenge','lesson_challenge','SO5-2-u3-C9',3,'ox','auto','대한민국 임시 정부는 3·1 운동 뒤 여러 곳의 임시 정부를 하나로 합쳐 세웠어요.',ARRAY['SO5-2-u3-X16']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C9","difficulty":3,"kind":"ox","stem":"대한민국 임시 정부는 3·1 운동 뒤 여러 곳의 임시 정부를 하나로 합쳐 세웠어요.","answer":"O","reason_options":[{"t":"독립운동을 이끌 힘을 하나로 모으려 했기 때문에","correct":true},{"t":"서로 다른 정부끼리 싸우려 했기 때문에","mis":"SO5-2-u3-X16"}],"mis":"SO5-2-u3-X16","explanation":["여러 곳에 있었어요.","하나로 합쳤어요.","힘을 모으려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_challenge#6','soc',5,2,'u3','L03','g5_2_soc_u3_L03_challenge','lesson_challenge','SO5-2-u3-C10',3,'error','auto','임시 정부와 단체를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X18','SO5-2-u3-X17']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C10","difficulty":3,"kind":"error","stem":"임시 정부와 단체를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"주원 — 「한인 애국단은 만주에서 독립군을 기르던 학교야.」","correct":true,"mis_target":"SO5-2-u3-X18"},{"t":"나윤 — 「임시 정부는 활동이 힘들어지자 한인 애국단을 만들었어.」","mis":"SO5-2-u3-X18"},{"t":"세훈 — 「임시 정부는 신문으로 활동을 알렸어.」","mis":"SO5-2-u3-X17"}],"explanation":["만주 학교는 신흥 무관 학교예요.","한인 애국단은 처단 활동을 했어요.","주원의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_challenge#7','soc',5,2,'u3','L03','g5_2_soc_u3_L03_challenge','lesson_challenge','SO5-2-u3-C8',3,'mc','auto','3·1 운동 때 일제가 시위를 거칠게 누른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X14','SO5-2-u3-X19']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C8","difficulty":3,"kind":"mc","stem":"3·1 운동 때 일제가 시위를 거칠게 누른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"온 민족이 독립을 외치자 다스리는 힘이 흔들릴까 두려웠기 때문에","correct":true},{"t":"시위하는 사람들이 일제를 도왔기 때문에","mis":"SO5-2-u3-X14"},{"t":"만세 시위가 서울에서만 조용히 끝났기 때문에","mis":"SO5-2-u3-X14"},{"t":"일제가 독립을 허락하려 했기 때문에","mis":"SO5-2-u3-X19"}],"explanation":["온 나라가 외쳤어요.","통치가 흔들렸어요.","거칠게 눌렀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_challenge#8','soc',5,2,'u3','L03','g5_2_soc_u3_L03_challenge','lesson_challenge','SO5-2-u3-C9',4,'mc','auto','「3·1 운동 → 대한민국 임시 정부 → 한인 애국단」을 바르게 이은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46','SO5-2-u3-X17','SO5-2-u3-X01']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C9","difficulty":4,"kind":"mc","stem":"「3·1 운동 → 대한민국 임시 정부 → 한인 애국단」을 바르게 이은 것은 어느 것인가요?","options":[{"t":"만세로 독립 의지를 보여 주고 → 힘을 모아 정부를 세웠으며 → 활동이 힘들어지자 단체를 만들어 다시 힘을 불어넣었다","correct":true},{"t":"단체를 먼저 만들고 → 만세를 불렀으며 → 정부를 없앴다","mis":"SO5-2-u3-X46"},{"t":"정부가 만세를 막고 → 단체가 정부를 무너뜨렸다","mis":"SO5-2-u3-X17"},{"t":"만세를 부른 뒤 → 독립운동을 그만두었다","mis":"SO5-2-u3-X01"}],"explanation":["먼저 3·1 운동이에요.","다음 임시 정부예요.","그 뒤 한인 애국단이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_challenge#9','soc',5,2,'u3','L03','g5_2_soc_u3_L03_challenge','lesson_challenge','SO5-2-u3-C10',4,'mc','auto','임시 정부가 힘들 때 한인 애국단을 만든 것으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X01','SO5-2-u3-X18','SO5-2-u3-X17']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C10","difficulty":4,"kind":"mc","stem":"임시 정부가 힘들 때 한인 애국단을 만든 것으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어려운 처지에서도 방법을 바꾸어 가며 독립운동을 이어 가려 했다","correct":true},{"t":"임시 정부는 독립을 포기했다","mis":"SO5-2-u3-X01"},{"t":"한인 애국단은 일제를 돕는 단체였다","mis":"SO5-2-u3-X18"},{"t":"한인 애국단은 땅을 조사하는 단체였다","mis":"SO5-2-u3-X17"}],"explanation":["활동이 힘들어졌어요.","새 방법을 찾았어요.","독립운동을 이어 갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L03_challenge#10','soc',5,2,'u3','L03','g5_2_soc_u3_L03_challenge','lesson_challenge','SO5-2-u3-C8',4,'essay','teacher','내가 3·1 운동 무렵 서울에서 만세를 본 학생이라고 생각하고, 고향 장날에 만세를 이끌지 고민하는 일기를 쓰세요. 두려운 까닭과 그래도 나선 사람들이 있었던 까닭을 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u3-C8","difficulty":4,"kind":"essay","stem":"내가 3·1 운동 무렵 서울에서 만세를 본 학생이라고 생각하고, 고향 장날에 만세를 이끌지 고민하는 일기를 쓰세요. 두려운 까닭과 그래도 나선 사람들이 있었던 까닭을 함께 쓰세요.","answer_guide":{"answer":"예: 오늘 서울에서 학생과 시민이 독립 선언서를 읽고 만세를 외치는 것을 보았다. 고향에도 헌병이 지켜보고 있어 붙잡혀 갈까 봐 두렵다. 그래도 장날에는 온 마을 사람이 모이니, 함께 독립의 뜻을 외치면 우리 민족이 나라를 되찾고 싶어 한다는 것을 온 세상이 알게 될 것이다.","scoring_points":["3·1 운동 모습을 사실에 맞게 썼는가","두려운 까닭을 썼는가","그래도 나선 까닭을 썼는가"]},"explanation":["본 것을 써요.","두려움도 써요.","나선 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_basic#1','soc',5,2,'u3','L04','g5_2_soc_u3_L04_basic','lesson_basic','SO5-2-u3-C12',1,'sa','auto','토산품을 쓰고 아껴 써서 경제적으로 독립하자는 운동은 무엇인가요? (물산 ○○ 운동)','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C12","difficulty":1,"kind":"sa","stem":"토산품을 쓰고 아껴 써서 경제적으로 독립하자는 운동은 무엇인가요? (물산 ○○ 운동)","answer":["물산 장려 운동","물산장려운동","물산 장려"],"explanation":["우리 물건을 썼어요.","아껴 썼어요.","물산 장려 운동이에요."],"mis":"SO5-2-u3-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_basic#2','soc',5,2,'u3','L04','g5_2_soc_u3_L04_basic','lesson_basic','SO5-2-u3-C13',1,'mc','auto','광주에서 시작해 학생들이 차별에 맞서 일으켜 전국으로 퍼진 운동은 어느 것인가요?',ARRAY['SO5-2-u3-X23','SO5-2-u3-X21','SO5-2-u3-X25']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C13","difficulty":1,"kind":"mc","stem":"광주에서 시작해 학생들이 차별에 맞서 일으켜 전국으로 퍼진 운동은 어느 것인가요?","options":[{"t":"광주 학생 항일 운동","correct":true},{"t":"6·10 만세 운동","mis":"SO5-2-u3-X23"},{"t":"물산 장려 운동","mis":"SO5-2-u3-X21"},{"t":"의병 운동","mis":"SO5-2-u3-X25"}],"explanation":["광주에서 시작했어요.","학생들이 나섰어요.","광주 학생 항일 운동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_basic#3','soc',5,2,'u3','L04','g5_2_soc_u3_L04_basic','lesson_basic','SO5-2-u3-C14',1,'mc','auto','독립군 연합 부대가 일본군과 싸워 이긴 만주의 지역은 어느 것인가요?',ARRAY['SO5-2-u3-X25']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C14","difficulty":1,"kind":"mc","stem":"독립군 연합 부대가 일본군과 싸워 이긴 만주의 지역은 어느 것인가요?","options":[{"t":"청산리","correct":true},{"t":"탑골 공원","mis":"SO5-2-u3-X25"},{"t":"헤이그","mis":"SO5-2-u3-X25"},{"t":"상하이","mis":"SO5-2-u3-X25"}],"explanation":["만주에 있어요.","연합 부대가 싸웠어요.","청산리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_basic#4','soc',5,2,'u3','L04','g5_2_soc_u3_L04_basic','lesson_basic','SO5-2-u3-C12',1,'ox','auto','조선어 학회는 우리말을 연구하고 우리말 사전을 만들려고 애썼어요.',ARRAY['SO5-2-u3-X21']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C12","difficulty":1,"kind":"ox","stem":"조선어 학회는 우리말을 연구하고 우리말 사전을 만들려고 애썼어요.","answer":"O","reason_options":[{"t":"말과 글을 지켜 민족의 힘을 기르려 했기 때문에","correct":true},{"t":"일본어 사전을 만들려 했기 때문에","mis":"SO5-2-u3-X21"}],"mis":"SO5-2-u3-X21","explanation":["우리말을 연구했어요.","사전을 만들려 했어요.","말과 글을 지켰어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_basic#5','soc',5,2,'u3','L04','g5_2_soc_u3_L04_basic','lesson_basic','SO5-2-u3-C11',2,'mc','auto','3·1 운동 뒤 일제가 다스리는 방법을 바꾼 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X19','SO5-2-u3-X17']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C11","difficulty":2,"kind":"mc","stem":"3·1 운동 뒤 일제가 다스리는 방법을 바꾼 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"친일 세력을 늘려 우리 민족을 서로 나누려 했다","correct":true},{"t":"독립을 허락하고 물러났다","mis":"SO5-2-u3-X19"},{"t":"우리 민족의 생활을 넉넉하게 해 주었다","mis":"SO5-2-u3-X19"},{"t":"임시 정부를 함께 세웠다","mis":"SO5-2-u3-X17"}],"explanation":["강압만으로는 어려웠어요.","방법을 바꾸었어요.","민족을 나누려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_basic#6','soc',5,2,'u3','L04','g5_2_soc_u3_L04_basic','lesson_basic','SO5-2-u3-C11',2,'mc','auto','쌀가마가 쌓인 항구 자료에서 농민의 밥상에 쌀이 아니라 잡곡죽이 오른 까닭은 어느 것인가요?',ARRAY['SO5-2-u3-X20','SO5-2-u3-X19']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C11","difficulty":2,"kind":"mc","stem":"쌀가마가 쌓인 항구 자료에서 농민의 밥상에 쌀이 아니라 잡곡죽이 오른 까닭은 어느 것인가요?","options":[{"t":"많이 거둔 쌀이 일본으로 실려 갔기 때문에","correct":true},{"t":"그해에는 쌀농사를 짓지 않았기 때문에","mis":"SO5-2-u3-X20"},{"t":"농민들이 쌀을 싫어했기 때문에","mis":"SO5-2-u3-X20"},{"t":"쌀값이 아주 싸졌기 때문에","mis":"SO5-2-u3-X19"}],"explanation":["쌀이 많이 쌓였어요.","배에 실려 갔어요.","농민은 먹지 못했어요."],"asset":{"type":"passage","lines":["바닷가 항구에 쌀가마가 산처럼 쌓여 있다.","쌀가마는 차례로 배에 실려 바다 건너 일본으로 떠난다.","이 쌀을 기른 농민들의 밥상에는 잡곡죽이 올라왔다."],"title":"쌀가마가 쌓인 항구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_basic#7','soc',5,2,'u3','L04','g5_2_soc_u3_L04_basic','lesson_basic','SO5-2-u3-C12',2,'mc','auto','나라 안에서 힘을 기른 운동 카드 나에 해당하는 것은 어느 것인가요?',ARRAY['SO5-2-u3-X21','SO5-2-u3-X25']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C12","difficulty":2,"kind":"mc","stem":"나라 안에서 힘을 기른 운동 카드 나에 해당하는 것은 어느 것인가요?","options":[{"t":"농촌 계몽 운동","correct":true},{"t":"물산 장려 운동","mis":"SO5-2-u3-X21"},{"t":"조선어 학회의 사전 만들기","mis":"SO5-2-u3-X21"},{"t":"청산리 전투","mis":"SO5-2-u3-X25"}],"explanation":["학생들이 갔어요.","농촌에서 한글을 가르쳤어요.","농촌 계몽 운동이에요."],"asset":{"type":"passage","lines":["가 — 「우리가 만든 것 우리가 쓰자!」 토산품을 쓰고 아껴 쓰자.","나 — 방학이면 학생들이 농촌에 가서 한글을 가르쳤다.","다 — 우리말을 연구하고 우리말 사전을 만들려고 원고를 모았다."],"title":"나라 안에서 힘을 기른 운동 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_basic#8','soc',5,2,'u3','L04','g5_2_soc_u3_L04_basic','lesson_basic','SO5-2-u3-C13',2,'mc','auto','6·10 만세 운동에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X23','SO5-2-u3-X25','SO5-2-u3-X21']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C13","difficulty":2,"kind":"mc","stem":"6·10 만세 운동에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"마지막 황제의 장례식 날 학생들이 서울에서 만세를 외쳤다","correct":true},{"t":"광주에서 학생끼리 다툰 일로 시작되었다","mis":"SO5-2-u3-X23"},{"t":"만주에서 독립군이 일본군을 물리쳤다","mis":"SO5-2-u3-X25"},{"t":"토산품을 쓰자고 외쳤다","mis":"SO5-2-u3-X21"}],"explanation":["장례식 날이에요.","학생들이 앞장섰어요.","서울에서 외쳤어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_basic#9','soc',5,2,'u3','L04','g5_2_soc_u3_L04_basic','lesson_basic','SO5-2-u3-C11',2,'ox','auto','3·1 운동 뒤 일제가 부드럽게 다스려서 우리 민족의 생활이 나아졌어요.',ARRAY['SO5-2-u3-X19']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C11","difficulty":2,"kind":"ox","stem":"3·1 운동 뒤 일제가 부드럽게 다스려서 우리 민족의 생활이 나아졌어요.","answer":"X","reason_options":[{"t":"방법만 바꾸어 민족을 나누고 쌀을 더 가져가 생활은 더 어려워졌기 때문에","correct":true},{"t":"일제가 쌀을 모두 돌려주었기 때문에","mis":"SO5-2-u3-X19"}],"mis":"SO5-2-u3-X19","explanation":["방법만 바꿨어요.","쌀을 더 가져갔어요.","생활은 더 어려워졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_basic#10','soc',5,2,'u3','L04','g5_2_soc_u3_L04_basic','lesson_basic','SO5-2-u3-C12',3,'error','auto','나라 안에서 힘을 기른 운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X22','SO5-2-u3-X21']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C12","difficulty":3,"kind":"error","stem":"나라 안에서 힘을 기른 운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「총을 들고 싸운 것만 독립운동이고 물건 쓰기는 상관없어.」","correct":true,"mis_target":"SO5-2-u3-X22"},{"t":"태민 — 「우리 물건을 써서 경제적으로 독립하려 했어.」","mis":"SO5-2-u3-X21"},{"t":"수아 — 「한글을 가르쳐 민족의 힘을 길렀어.」","mis":"SO5-2-u3-X21"}],"explanation":["물건으로도 맞섰어요.","글과 말로도 맞섰어요.","하윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_challenge#1','soc',5,2,'u3','L04','g5_2_soc_u3_L04_challenge','lesson_challenge','SO5-2-u3-C12',2,'match','auto','나라 안에서 힘을 기른 운동 카드와 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C12","difficulty":2,"kind":"match","stem":"나라 안에서 힘을 기른 운동 카드와 이름을 알맞게 이으세요.","pairs":[{"l":"가 토산품","r":"물산 장려 운동"},{"l":"나 농촌 한글","r":"농촌 계몽 운동"},{"l":"다 우리말 사전","r":"조선어 학회"}],"mis":"SO5-2-u3-X21","explanation":["토산품은 물산 장려예요.","한글 가르치기는 농촌 계몽이에요.","사전은 조선어 학회예요."],"asset":{"type":"passage","lines":["가 — 「우리가 만든 것 우리가 쓰자!」 토산품을 쓰고 아껴 쓰자.","나 — 방학이면 학생들이 농촌에 가서 한글을 가르쳤다.","다 — 우리말을 연구하고 우리말 사전을 만들려고 원고를 모았다."],"title":"나라 안에서 힘을 기른 운동 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_challenge#2','soc',5,2,'u3','L04','g5_2_soc_u3_L04_challenge','lesson_challenge','SO5-2-u3-C14',2,'mc','auto','만주 독립군의 기록 ㉮·㉯에 해당하는 전투를 차례로 짝지은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X25','SO5-2-u3-X42']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C14","difficulty":2,"kind":"mc","stem":"만주 독립군의 기록 ㉮·㉯에 해당하는 전투를 차례로 짝지은 것은 어느 것인가요?","options":[{"t":"㉮ 봉오동 · ㉯ 청산리","correct":true},{"t":"㉮ 청산리 · ㉯ 탑골 공원","mis":"SO5-2-u3-X25"},{"t":"㉮ 인천 · ㉯ 흥남","mis":"SO5-2-u3-X42"},{"t":"㉮ 헤이그 · ㉯ 상하이","mis":"SO5-2-u3-X25"}],"explanation":["먼저 여러 부대가 물리쳤어요.","이어 연합 부대가 이겼어요.","봉오동, 청산리예요."],"asset":{"type":"passage","lines":["㉮ 여러 독립군 부대가 골짜기로 일본군을 끌어들여 물리쳤다.","㉯ 독립군 연합 부대가 숲과 골짜기에서 여러 날 싸워 이겼다.","㉰ 먹을 것이 끊기고 추위에 떨면서도 싸움을 이어 갔다."],"title":"만주 독립군의 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_challenge#3','soc',5,2,'u3','L04','g5_2_soc_u3_L04_challenge','lesson_challenge','SO5-2-u3-C13',3,'mc','auto','어느 학생 운동 기록에서 시위가 전국으로 퍼진 까닭을 「쌓인 까닭」과 「불을 붙인 일」로 바르게 나눈 것은 어느 것인가요?',ARRAY['SO5-2-u3-X24']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C13","difficulty":3,"kind":"mc","stem":"어느 학생 운동 기록에서 시위가 전국으로 퍼진 까닭을 「쌓인 까닭」과 「불을 붙인 일」로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"쌓인 까닭 ① · 불을 붙인 일 ③","correct":true},{"t":"쌓인 까닭 ④ · 불을 붙인 일 ①","mis":"SO5-2-u3-X24"},{"t":"쌓인 까닭 ② · 불을 붙인 일 ④","mis":"SO5-2-u3-X24"},{"t":"쌓인 까닭 ③ · 불을 붙인 일 ①","mis":"SO5-2-u3-X24"}],"explanation":["①은 오래 쌓인 차별이에요.","③이 화를 터뜨렸어요.","그래서 전국으로 퍼졌어요."],"asset":{"type":"passage","lines":["① 학교에서 우리말과 역사를 제대로 배우지 못하고 차별을 받았다.","② 기차 통학길에 한국 학생과 일본 학생이 다투었다.","③ 경찰은 한국 학생만 붙잡아 갔다.","④ 화가 난 학생들의 시위가 전국의 학교로 퍼졌다."],"title":"어느 학생 운동 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_challenge#4','soc',5,2,'u3','L04','g5_2_soc_u3_L04_challenge','lesson_challenge','SO5-2-u3-C11',3,'mc','auto','3·1 운동 뒤 일제가 친일 세력을 늘린 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X19','SO5-2-u3-X20']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C11","difficulty":3,"kind":"mc","stem":"3·1 운동 뒤 일제가 친일 세력을 늘린 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리 민족을 서로 나누어 저항할 힘을 꺾으려고","correct":true},{"t":"우리 민족이 하나로 뭉치게 도우려고","mis":"SO5-2-u3-X19"},{"t":"독립을 빨리 이루게 하려고","mis":"SO5-2-u3-X19"},{"t":"쌀을 농민에게 돌려주려고","mis":"SO5-2-u3-X20"}],"explanation":["3·1 운동에 놀랐어요.","민족을 나누려 했어요.","저항을 꺾으려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_challenge#5','soc',5,2,'u3','L04','g5_2_soc_u3_L04_challenge','lesson_challenge','SO5-2-u3-C14',3,'ox','auto','봉오동·청산리에서의 싸움은 나라 안에서 물건을 아껴 쓰자는 운동이었어요.',ARRAY['SO5-2-u3-X25']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C14","difficulty":3,"kind":"ox","stem":"봉오동·청산리에서의 싸움은 나라 안에서 물건을 아껴 쓰자는 운동이었어요.","answer":"X","reason_options":[{"t":"나라 밖 만주에서 독립군이 무기를 들고 일본군과 싸운 일이기 때문에","correct":true},{"t":"봉오동과 청산리는 서울의 공원 이름이기 때문에","mis":"SO5-2-u3-X25"}],"mis":"SO5-2-u3-X25","explanation":["만주에서 일어났어요.","독립군이 싸웠어요.","무장 독립 투쟁이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_challenge#6','soc',5,2,'u3','L04','g5_2_soc_u3_L04_challenge','lesson_challenge','SO5-2-u3-C13',3,'error','auto','학생 운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X24','SO5-2-u3-X23']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C13","difficulty":3,"kind":"error","stem":"학생 운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「광주 학생 항일 운동은 학생 몇 명이 다툰 걸로 끝난 일이야.」","correct":true,"mis_target":"SO5-2-u3-X24"},{"t":"라희 — 「한국 학생만 붙잡히자 차별에 맞선 시위가 전국으로 퍼졌어.」","mis":"SO5-2-u3-X23"},{"t":"유찬 — 「6·10 만세 운동은 황제의 장례식 날 일어났어.」","mis":"SO5-2-u3-X23"}],"explanation":["차별이 쌓여 있었어요.","전국으로 퍼졌어요.","지호의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_challenge#7','soc',5,2,'u3','L04','g5_2_soc_u3_L04_challenge','lesson_challenge','SO5-2-u3-C12',3,'mc','auto','물산 장려 운동이 독립에 도움이 된다고 본 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X22']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C12","difficulty":3,"kind":"mc","stem":"물산 장려 운동이 독립에 도움이 된다고 본 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리 물건을 쓰면 우리 회사와 경제가 살아나 민족의 힘이 길러지기 때문에","correct":true},{"t":"일본 물건이 더 싸고 좋기 때문에","mis":"SO5-2-u3-X22"},{"t":"물건을 쓰지 않으면 일제가 떠나기 때문에","mis":"SO5-2-u3-X22"},{"t":"독립군에게 총을 대신 주기 때문에","mis":"SO5-2-u3-X22"}],"explanation":["우리 물건을 썼어요.","경제가 살아나요.","민족의 힘이 길러져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_challenge#8','soc',5,2,'u3','L04','g5_2_soc_u3_L04_challenge','lesson_challenge','SO5-2-u3-C14',4,'mc','auto','나라 안에서 힘을 기른 운동과 나라 밖 독립군의 싸움을 함께 볼 때 가장 알맞은 생각은 어느 것인가요?',ARRAY['SO5-2-u3-X26','SO5-2-u3-X01']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C14","difficulty":4,"kind":"mc","stem":"나라 안에서 힘을 기른 운동과 나라 밖 독립군의 싸움을 함께 볼 때 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"맞서 싸우는 힘과 민족이 무너지지 않게 지키는 힘이 함께 독립을 향했다","correct":true},{"t":"나라 밖 싸움만 독립에 필요했다","mis":"SO5-2-u3-X26"},{"t":"나라 안 운동만 독립에 필요했다","mis":"SO5-2-u3-X26"},{"t":"둘 다 독립과 관계가 없었다","mis":"SO5-2-u3-X01"}],"explanation":["밖에서는 싸웠어요.","안에서는 힘을 길렀어요.","둘이 함께 필요했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_challenge#9','soc',5,2,'u3','L04','g5_2_soc_u3_L04_challenge','lesson_challenge','SO5-2-u3-C13',4,'mc','auto','오늘날 11월 3일을 학생 독립운동 기념일로 정해 기억하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X47','SO5-2-u3-X46','SO5-2-u3-X23']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C13","difficulty":4,"kind":"mc","stem":"오늘날 11월 3일을 학생 독립운동 기념일로 정해 기억하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학생들이 차별에 맞서 일어나 전국으로 퍼진 독립운동을 기억하려고","correct":true},{"t":"학생들이 쉬는 날을 늘리려고","mis":"SO5-2-u3-X47"},{"t":"6·25 전쟁이 시작된 날이라서","mis":"SO5-2-u3-X46"},{"t":"토산품을 쓰기 시작한 날이라서","mis":"SO5-2-u3-X23"}],"explanation":["광주의 학생들이 일어났어요.","전국으로 퍼졌어요.","그 뜻을 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L04_challenge#10','soc',5,2,'u3','L04','g5_2_soc_u3_L04_challenge','lesson_challenge','SO5-2-u3-C11',4,'essay','teacher','쌀가마가 쌓인 항구 자료를 보고 3·1 운동 뒤 일제의 통치가 우리 민족의 생활에 준 영향을 쓰고, 이에 맞서 나라 안에서 한 운동을 하나 들어 그 뜻을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u3-C11","difficulty":4,"kind":"essay","stem":"쌀가마가 쌓인 항구 자료를 보고 3·1 운동 뒤 일제의 통치가 우리 민족의 생활에 준 영향을 쓰고, 이에 맞서 나라 안에서 한 운동을 하나 들어 그 뜻을 쓰세요.","answer_guide":{"answer":"예: 일제는 쌀을 더 많이 생산하게 해 일본으로 실어 가서 농민들은 쌀을 기르고도 잡곡죽을 먹을 만큼 생활이 어려워졌다. 이에 맞서 사람들은 물산 장려 운동을 벌여 우리 땅에서 나는 물건을 쓰고 아껴 써서 경제적으로 독립하려 했다.","scoring_points":["쌀이 실려 간 사실을 썼는가","생활이 어려워진 영향을 썼는가","나라 안 운동 하나와 뜻을 썼는가"]},"explanation":["쌀이 실려 갔어요.","생활이 어려워졌어요.","운동으로 맞섰어요."],"asset":{"type":"passage","lines":["바닷가 항구에 쌀가마가 산처럼 쌓여 있다.","쌀가마는 차례로 배에 실려 바다 건너 일본으로 떠난다.","이 쌀을 기른 농민들의 밥상에는 잡곡죽이 올라왔다."],"title":"쌀가마가 쌓인 항구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_basic#1','soc',5,2,'u3','L05','g5_2_soc_u3_L05_basic','lesson_basic','SO5-2-u3-C15',1,'mc','auto','일제가 놓은 철도가 주로 쓰인 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X27']::text[],false,'{"seq":1,"concept":"SO5-2-u3-C15","difficulty":1,"kind":"mc","stem":"일제가 놓은 철도가 주로 쓰인 일로 알맞은 것은 어느 것인가요?","options":[{"t":"군대를 옮기고 빼앗은 자원을 일본으로 실어 나르는 일","correct":true},{"t":"우리 민족의 여행을 돕는 일","mis":"SO5-2-u3-X27"},{"t":"독립군을 실어 나르는 일","mis":"SO5-2-u3-X27"},{"t":"농민에게 쌀을 나누어 주는 일","mis":"SO5-2-u3-X27"}],"explanation":["철도로 빨라졌어요.","그러나 쓰임을 봐요.","군대와 자원을 옮겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_basic#2','soc',5,2,'u3','L05','g5_2_soc_u3_L05_basic','lesson_basic','SO5-2-u3-C18',1,'sa','auto','대한민국 임시 정부가 만들어 일본과의 전쟁에 나선 군대는 무엇인가요? (한국○○○)','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u3-C18","difficulty":1,"kind":"sa","stem":"대한민국 임시 정부가 만들어 일본과의 전쟁에 나선 군대는 무엇인가요? (한국○○○)","answer":["한국광복군","한국 광복군","광복군"],"explanation":["임시 정부가 만들었어요.","일본과 싸우려 했어요.","한국광복군이에요."],"mis":"SO5-2-u3-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_basic#3','soc',5,2,'u3','L05','g5_2_soc_u3_L05_basic','lesson_basic','SO5-2-u3-C17',1,'mc','auto','일제가 우리 민족에게 성과 이름을 어떻게 바꾸게 했나요?',ARRAY['SO5-2-u3-X30']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C17","difficulty":1,"kind":"mc","stem":"일제가 우리 민족에게 성과 이름을 어떻게 바꾸게 했나요?","options":[{"t":"일본식 성과 이름으로","correct":true},{"t":"중국식 성과 이름으로","mis":"SO5-2-u3-X30"},{"t":"원래 성과 이름 그대로","mis":"SO5-2-u3-X30"},{"t":"서양식 이름으로","mis":"SO5-2-u3-X30"}],"explanation":["민족정신을 없애려 했어요.","이름까지 바꾸게 했어요.","일본식이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_basic#4','soc',5,2,'u3','L05','g5_2_soc_u3_L05_basic','lesson_basic','SO5-2-u3-C16',1,'ox','auto','일제 통치 시기에 일본에서 만든 인공 조미료가 우리나라에 처음 들어왔어요.',ARRAY['SO5-2-u3-X29']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C16","difficulty":1,"kind":"ox","stem":"일제 통치 시기에 일본에서 만든 인공 조미료가 우리나라에 처음 들어왔어요.","answer":"O","reason_options":[{"t":"이때 들어와 국물 맛을 쉽게 내는 데 쓰이기 시작했기 때문에","correct":true},{"t":"인공 조미료는 조선 시대부터 집집마다 만들었기 때문에","mis":"SO5-2-u3-X29"}],"mis":"SO5-2-u3-X29","explanation":["일본에서 만들었어요.","이때 들어왔어요.","국물 맛을 쉽게 냈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_basic#5','soc',5,2,'u3','L05','g5_2_soc_u3_L05_basic','lesson_basic','SO5-2-u3-C15',2,'mc','auto','임피역 탐구 메모로 보아 일제가 이 역을 지은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X27','SO5-2-u3-X20']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C15","difficulty":2,"kind":"mc","stem":"임피역 탐구 메모로 보아 일제가 이 역을 지은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"평야에서 거둔 쌀을 모아 일본으로 실어 가려고","correct":true},{"t":"마을 사람들이 여행을 다니기 편하게 하려고","mis":"SO5-2-u3-X27"},{"t":"독립군을 숨겨 주려고","mis":"SO5-2-u3-X27"},{"t":"쌀을 농민에게 나누어 주려고","mis":"SO5-2-u3-X20"}],"explanation":["평야의 쌀이 모였어요.","군산항으로 옮겼어요.","일본으로 실어 갔어요."],"asset":{"type":"passage","lines":["일제는 바닷가 군산까지 철도를 놓고 그 길에 작은 기차역을 지었다.","남쪽 넓은 평야에서 거둔 쌀이 이 역에 모였다.","쌀은 기차로 군산항까지 옮겨져 배에 실려 일본으로 갔다.","역 주변의 길은 일본인의 농장과 이어져 있었다."],"title":"임피역 탐구 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_basic#6','soc',5,2,'u3','L05','g5_2_soc_u3_L05_basic','lesson_basic','SO5-2-u3-C15',2,'mc','auto','같은 도시 안 세 동네에서 주로 일본인과 일부 부유한 사람이 모여 산 곳은 어느 것인가요?',ARRAY['SO5-2-u3-X28']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C15","difficulty":2,"kind":"mc","stem":"같은 도시 안 세 동네에서 주로 일본인과 일부 부유한 사람이 모여 산 곳은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"SO5-2-u3-X28"},{"t":"㉰","mis":"SO5-2-u3-X28"},{"t":"세 곳 모두 똑같았다","mis":"SO5-2-u3-X28"}],"explanation":["은행과 백화점이 있어요.","전등이 환해요.","㉮예요."],"asset":{"type":"passage","lines":["㉮ 은행·백화점·높은 건물이 늘어선 거리, 밤에도 전등이 환하다.","㉯ 전기가 잘 들어오지 않고 동네 사람이 함께 우물을 쓴다.","㉰ 도시 변두리 땅을 파고 나무토막과 흙, 짚으로 지은 집이 모여 있다."],"title":"같은 도시 안 세 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_basic#7','soc',5,2,'u3','L05','g5_2_soc_u3_L05_basic','lesson_basic','SO5-2-u3-C17',2,'mc','auto','일제가 신사에 억지로 절을 하게 한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X30']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C17","difficulty":2,"kind":"mc","stem":"일제가 신사에 억지로 절을 하게 한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"일본 왕에게 충성하게 하고 우리 민족정신을 없애려고","correct":true},{"t":"우리 전통 문화를 지켜 주려고","mis":"SO5-2-u3-X30"},{"t":"학생들이 공부를 잘하게 하려고","mis":"SO5-2-u3-X30"},{"t":"마을을 아름답게 꾸미려고","mis":"SO5-2-u3-X30"}],"explanation":["신사는 일본의 사당이에요.","충성하게 했어요.","민족정신을 없애려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_basic#8','soc',5,2,'u3','L05','g5_2_soc_u3_L05_basic','lesson_basic','SO5-2-u3-C18',2,'mc','auto','탄압 속에서도 민족 문화를 지키려 한 노력으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X33','SO5-2-u3-X31']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C18","difficulty":2,"kind":"mc","stem":"탄압 속에서도 민족 문화를 지키려 한 노력으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 역사를 연구해 일제의 역사 왜곡에 맞섰다","correct":true},{"t":"일본식 이름을 앞장서 퍼뜨렸다","mis":"SO5-2-u3-X33"},{"t":"신사에 절하기를 권했다","mis":"SO5-2-u3-X33"},{"t":"놋그릇을 모아 일제에 바쳤다","mis":"SO5-2-u3-X31"}],"explanation":["역사를 연구했어요.","왜곡에 맞섰어요.","글과 역사로 지켰어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_basic#9','soc',5,2,'u3','L05','g5_2_soc_u3_L05_basic','lesson_basic','SO5-2-u3-C17',2,'ox','auto','일제는 전쟁에 필요하다며 놋그릇과 숟가락 같은 생활 물건까지 거두어 갔어요.',ARRAY['SO5-2-u3-X31']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C17","difficulty":2,"kind":"ox","stem":"일제는 전쟁에 필요하다며 놋그릇과 숟가락 같은 생활 물건까지 거두어 갔어요.","answer":"O","reason_options":[{"t":"쇠붙이를 녹여 전쟁 무기를 만들려 했기 때문에","correct":true},{"t":"사람들이 쓰지 않는 물건을 치워 주었기 때문에","mis":"SO5-2-u3-X31"}],"mis":"SO5-2-u3-X31","explanation":["생활 물건이에요.","쇠붙이를 모았어요.","무기를 만들려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_basic#10','soc',5,2,'u3','L05','g5_2_soc_u3_L05_basic','lesson_basic','SO5-2-u3-C18',3,'error','auto','한국광복군을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X32']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C18","difficulty":3,"kind":"error","stem":"한국광복군을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「한국광복군이 나라 안으로 들어와 일본군을 다 몰아냈어.」","correct":true,"mis_target":"SO5-2-u3-X32"},{"t":"재윤 — 「임시 정부가 만든 군대야.」","mis":"SO5-2-u3-X32"},{"t":"가은 — 「미군과 함께 나라 안으로 들어갈 작전을 세웠어.」","mis":"SO5-2-u3-X32"}],"explanation":["작전을 준비했어요.","그 전에 일제가 항복했어요.","민서의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_challenge#1','soc',5,2,'u3','L05','g5_2_soc_u3_L05_challenge','lesson_challenge','SO5-2-u3-C15',2,'match','auto','같은 도시 안 세 동네와 그곳의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C15","difficulty":2,"kind":"match","stem":"같은 도시 안 세 동네와 그곳의 모습을 알맞게 이으세요.","pairs":[{"l":"㉮","r":"근대 문물이 넘치는 거리"},{"l":"㉯","r":"전기 부족·함께 쓰는 우물"},{"l":"㉰","r":"변두리 토막집"}],"mis":"SO5-2-u3-X28","explanation":["㉮는 은행과 백화점이에요.","㉯는 우물을 써요.","㉰는 토막집이에요."],"asset":{"type":"passage","lines":["㉮ 은행·백화점·높은 건물이 늘어선 거리, 밤에도 전등이 환하다.","㉯ 전기가 잘 들어오지 않고 동네 사람이 함께 우물을 쓴다.","㉰ 도시 변두리 땅을 파고 나무토막과 흙, 짚으로 지은 집이 모여 있다."],"title":"같은 도시 안 세 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_challenge#2','soc',5,2,'u3','L05','g5_2_soc_u3_L05_challenge','lesson_challenge','SO5-2-u3-C17',2,'mc','auto','옛 학교 사진을 다룬 신문 기사로 알 수 있는 그때 학교의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X30']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C17","difficulty":2,"kind":"mc","stem":"옛 학교 사진을 다룬 신문 기사로 알 수 있는 그때 학교의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"침략 전쟁을 좋게 꾸민 수업과 군사 훈련을 받았다","correct":true},{"t":"우리말과 역사를 마음껏 배웠다","mis":"SO5-2-u3-X30"},{"t":"여학생들이 원하는 옷을 골라 입었다","mis":"SO5-2-u3-X30"},{"t":"학생들이 평화를 위한 토론만 했다","mis":"SO5-2-u3-X30"}],"explanation":["일본식 바지를 입었어요.","전쟁을 좋게 가르쳤어요.","군사 훈련을 받았어요."],"asset":{"type":"passage","lines":["교육청이 옛 학교 사진을 온라인 전시관에 공개했다.","여학생들은 치마 대신 통이 넓은 일본식 바지를 입고 수업을 받았다.","교사는 침략 전쟁이 평화를 위한 것이라고 가르쳤다.","학생들은 나무칼을 들고 군사 훈련을 받았다."],"title":"옛 학교 사진을 다룬 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_challenge#3','soc',5,2,'u3','L05','g5_2_soc_u3_L05_challenge','lesson_challenge','SO5-2-u3-C15',3,'mc','auto','철도가 놓이며 「사람과 물자가 빨라진 것」과 「일제가 철도를 쓴 까닭」을 함께 볼 때 가장 알맞은 생각은 어느 것인가요?',ARRAY['SO5-2-u3-X27','SO5-2-u3-X20']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C15","difficulty":3,"kind":"mc","stem":"철도가 놓이며 「사람과 물자가 빨라진 것」과 「일제가 철도를 쓴 까닭」을 함께 볼 때 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"편리한 근대 문물도 식민 통치 아래에서는 빼앗아 가는 데 주로 쓰였다","correct":true},{"t":"철도는 우리 민족을 위해 놓은 선물이었다","mis":"SO5-2-u3-X27"},{"t":"철도는 아무 쓸모가 없었다","mis":"SO5-2-u3-X27"},{"t":"철도 덕분에 쌀이 농민에게 돌아왔다","mis":"SO5-2-u3-X20"}],"explanation":["빨라진 건 맞아요.","누구를 위해 썼는지 봐요.","빼앗는 데 쓰였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_challenge#4','soc',5,2,'u3','L05','g5_2_soc_u3_L05_challenge','lesson_challenge','SO5-2-u3-C16',3,'mc','auto','음식 속으로 — 조미료와 냉면 자료로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X29']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C16","difficulty":3,"kind":"mc","stem":"음식 속으로 — 조미료와 냉면 자료로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"편리한 음식 문화가 생겼지만 모든 한국인이 그것을 누리지는 못했다","correct":true},{"t":"모든 한국인이 날마다 냉면을 배달해 먹었다","mis":"SO5-2-u3-X29"},{"t":"조미료 때문에 국물 요리가 사라졌다","mis":"SO5-2-u3-X29"},{"t":"집집마다 다른 맛이 더 다양해졌다","mis":"SO5-2-u3-X29"}],"explanation":["맛을 쉽게 냈어요.","배달도 생겼어요.","누리지 못한 사람이 많았어요."],"asset":{"type":"passage","lines":["일본에서 만든 가루 조미료가 신문 광고에 실렸다.","비싼 고기 없이도 국물 맛을 쉽고 똑같이 낼 수 있었다.","여름이면 냉면집 전화가 바빴고 자전거로 냉면을 배달했다.","그러나 전화로 냉면을 시켜 먹는 한국인은 많지 않았다."],"title":"음식 속으로 — 조미료와 냉면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_challenge#5','soc',5,2,'u3','L05','g5_2_soc_u3_L05_challenge','lesson_challenge','SO5-2-u3-C15',3,'ox','auto','도시가 커지면서 그 도시에 사는 모든 사람이 전기와 수도를 똑같이 누렸어요.',ARRAY['SO5-2-u3-X28']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C15","difficulty":3,"kind":"ox","stem":"도시가 커지면서 그 도시에 사는 모든 사람이 전기와 수도를 똑같이 누렸어요.","answer":"X","reason_options":[{"t":"일본인이 산 곳과 한국인이 산 곳의 모습이 크게 달랐기 때문에","correct":true},{"t":"그때는 도시에 전기가 하나도 없었기 때문에","mis":"SO5-2-u3-X28"}],"mis":"SO5-2-u3-X28","explanation":["㉮는 환했어요.","㉯·㉰는 어려웠어요.","똑같지 않았어요."],"asset":{"type":"passage","lines":["㉮ 은행·백화점·높은 건물이 늘어선 거리, 밤에도 전등이 환하다.","㉯ 전기가 잘 들어오지 않고 동네 사람이 함께 우물을 쓴다.","㉰ 도시 변두리 땅을 파고 나무토막과 흙, 짚으로 지은 집이 모여 있다."],"title":"같은 도시 안 세 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_challenge#6','soc',5,2,'u3','L05','g5_2_soc_u3_L05_challenge','lesson_challenge','SO5-2-u3-C17',3,'error','auto','일제가 침략 전쟁을 일으킨 뒤 메모를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X31','SO5-2-u3-X30']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C17","difficulty":3,"kind":"error","stem":"일제가 침략 전쟁을 일으킨 뒤 메모를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「사람들은 원해서 전쟁터와 공장으로 갔고 물건만 거두어 갔어.」","correct":true,"mis_target":"SO5-2-u3-X31"},{"t":"아린 — 「①~③은 민족정신을 없애려는 일이야.」","mis":"SO5-2-u3-X30"},{"t":"동하 — 「④·⑤는 사람과 물자를 억지로 동원한 일이야.」","mis":"SO5-2-u3-X31"}],"explanation":["사람도 억지로 끌고 갔어요.","물자도 빼앗았어요.","서준의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["① 동네마다 세운 신사에 억지로 절을 하게 했다.","② 성과 이름을 일본식으로 바꾸게 했다.","③ 학교에서 우리말과 우리 역사를 배우지 못하게 했다.","④ 놋그릇과 숟가락까지 거두어 갔다.","⑤ 많은 사람을 전쟁터와 공장 등으로 끌고 갔다."],"title":"일제가 침략 전쟁을 일으킨 뒤 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_challenge#7','soc',5,2,'u3','L05','g5_2_soc_u3_L05_challenge','lesson_challenge','SO5-2-u3-C17',3,'mc','auto','일제가 침략 전쟁을 일으킨 뒤 메모 ①~③을 한꺼번에 펼친 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X30','SO5-2-u3-X33']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C17","difficulty":3,"kind":"mc","stem":"일제가 침략 전쟁을 일으킨 뒤 메모 ①~③을 한꺼번에 펼친 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리 민족이 일본 왕에게 충성하고 침략 전쟁에 협조하게 하려고","correct":true},{"t":"우리 민족의 전통을 지켜 주려고","mis":"SO5-2-u3-X30"},{"t":"우리말 사전을 만들게 도우려고","mis":"SO5-2-u3-X33"},{"t":"학생들이 쉬는 시간을 늘리려고","mis":"SO5-2-u3-X30"}],"explanation":["절·이름·말을 바꾸게 했어요.","민족정신을 없애려 했어요.","전쟁에 협조하게 하려 했어요."],"asset":{"type":"passage","lines":["① 동네마다 세운 신사에 억지로 절을 하게 했다.","② 성과 이름을 일본식으로 바꾸게 했다.","③ 학교에서 우리말과 우리 역사를 배우지 못하게 했다.","④ 놋그릇과 숟가락까지 거두어 갔다.","⑤ 많은 사람을 전쟁터와 공장 등으로 끌고 갔다."],"title":"일제가 침략 전쟁을 일으킨 뒤 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_challenge#8','soc',5,2,'u3','L05','g5_2_soc_u3_L05_challenge','lesson_challenge','SO5-2-u3-C18',4,'mc','auto','어느 군대 이야기를 읽고 가장 알맞게 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u3-X32','SO5-2-u3-X01']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C18","difficulty":4,"kind":"mc","stem":"어느 군대 이야기를 읽고 가장 알맞게 정리한 것은 어느 것인가요?","options":[{"t":"임시 정부가 만든 한국광복군은 나라 안으로 들어갈 작전을 준비했지만 일제가 먼저 항복해 펼치지 못했다","correct":true},{"t":"한국광복군은 의병이 다시 모인 군대로 일본군을 모두 몰아냈다","mis":"SO5-2-u3-X32"},{"t":"한국광복군은 일제가 만든 군대였다","mis":"SO5-2-u3-X32"},{"t":"한국광복군은 싸울 생각 없이 훈련만 했다","mis":"SO5-2-u3-X01"}],"explanation":["임시 정부가 만들었어요.","작전을 준비했어요.","일제가 먼저 항복했어요."],"asset":{"type":"passage","lines":["대한민국 임시 정부가 군대를 만들어 일본과의 전쟁에 나섰다.","미군과 함께 나라 안으로 들어갈 작전을 세우고 훈련했다.","그러나 작전을 펼치기 전에 일제가 항복했다."],"title":"어느 군대 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_challenge#9','soc',5,2,'u3','L05','g5_2_soc_u3_L05_challenge','lesson_challenge','SO5-2-u3-C18',4,'mc','auto','역사를 연구하고 저항하는 글을 쓴 일이 독립운동이 될 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X33']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C18","difficulty":4,"kind":"mc","stem":"역사를 연구하고 저항하는 글을 쓴 일이 독립운동이 될 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"민족정신을 없애려는 일제에 맞서 우리 역사와 민족의식을 지켰기 때문에","correct":true},{"t":"총을 들지 않았으니 저항이 아니다","mis":"SO5-2-u3-X33"},{"t":"일제의 역사 왜곡을 도왔기 때문에","mis":"SO5-2-u3-X33"},{"t":"글은 아무도 읽지 않았기 때문에","mis":"SO5-2-u3-X33"}],"explanation":["일제는 정신을 없애려 했어요.","역사와 글로 지켰어요.","그것도 저항이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L05_challenge#10','soc',5,2,'u3','L05','g5_2_soc_u3_L05_challenge','lesson_challenge','SO5-2-u3-C15',4,'essay','teacher','같은 도시 안 세 동네를 보고, 일제 통치 시기 도시의 「두 얼굴」을 쓰고 그렇게 된 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u3-C15","difficulty":4,"kind":"essay","stem":"같은 도시 안 세 동네를 보고, 일제 통치 시기 도시의 「두 얼굴」을 쓰고 그렇게 된 까닭을 쓰세요.","answer_guide":{"answer":"예: 철도역과 항구를 중심으로 도시가 커져 ㉮처럼 은행·백화점·높은 건물이 들어서고 밤에도 전등이 환한 거리가 생겼다. 그러나 ㉯처럼 한국인이 많이 산 곳은 전기가 잘 들어오지 않고 우물을 함께 썼으며, ㉰처럼 가난한 사람은 변두리 토막집에 살았다. 도시가 일제와 일본인에게 필요한 대로 발달했기 때문이다.","scoring_points":["발달한 모습을 썼는가","누리지 못한 모습을 썼는가","까닭(일제와 일본인 중심)을 썼는가"]},"explanation":["환한 거리가 있어요.","어두운 동네도 있어요.","누구를 위한 발달인지 써요."],"asset":{"type":"passage","lines":["㉮ 은행·백화점·높은 건물이 늘어선 거리, 밤에도 전등이 환하다.","㉯ 전기가 잘 들어오지 않고 동네 사람이 함께 우물을 쓴다.","㉰ 도시 변두리 땅을 파고 나무토막과 흙, 짚으로 지은 집이 모여 있다."],"title":"같은 도시 안 세 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_basic#1','soc',5,2,'u3','L06','g5_2_soc_u3_L06_basic','lesson_basic','SO5-2-u3-C19',1,'mc','auto','일제에 빼앗겼던 나라를 다시 찾은 일을 무엇이라고 하나요?',ARRAY['SO5-2-u3-X02','SO5-2-u3-X40']::text[],false,'{"seq":1,"concept":"SO5-2-u3-C19","difficulty":1,"kind":"mc","stem":"일제에 빼앗겼던 나라를 다시 찾은 일을 무엇이라고 하나요?","options":[{"t":"광복","correct":true},{"t":"개항","mis":"SO5-2-u3-X02"},{"t":"늑약","mis":"SO5-2-u3-X02"},{"t":"정전","mis":"SO5-2-u3-X40"}],"explanation":["빼앗겼던 나라예요.","다시 찾았어요.","광복이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_basic#2','soc',5,2,'u3','L06','g5_2_soc_u3_L06_basic','lesson_basic','SO5-2-u3-C20',1,'sa','auto','대한민국 정부가 세워지기 전, 남한에서 치른 우리 역사의 첫 민주 선거는 무엇인가요? (○·○○ 총선거)','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u3-C20","difficulty":1,"kind":"sa","stem":"대한민국 정부가 세워지기 전, 남한에서 치른 우리 역사의 첫 민주 선거는 무엇인가요? (○·○○ 총선거)","answer":["5·10 총선거","5·10총선거","5·10"],"explanation":["남한에서 치렀어요.","국회의원을 뽑았어요.","5·10 총선거예요."],"mis":"SO5-2-u3-X38"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_basic#3','soc',5,2,'u3','L06','g5_2_soc_u3_L06_basic','lesson_basic','SO5-2-u3-C19',1,'mc','auto','광복 뒤 학교에서 달라진 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X35']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C19","difficulty":1,"kind":"mc","stem":"광복 뒤 학교에서 달라진 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"선생님이 우리말로 수업했다","correct":true},{"t":"일본어로만 수업했다","mis":"SO5-2-u3-X35"},{"t":"우리 역사를 배우지 못하게 했다","mis":"SO5-2-u3-X35"},{"t":"교사가 칼을 차고 수업했다","mis":"SO5-2-u3-X35"}],"explanation":["나라를 되찾았어요.","우리말을 쓸 수 있어요.","우리말로 수업했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_basic#4','soc',5,2,'u3','L06','g5_2_soc_u3_L06_basic','lesson_basic','SO5-2-u3-C20',1,'ox','auto','대한민국 정부는 헌법을 만들고 대통령을 뽑은 뒤에 세워졌어요.',ARRAY['SO5-2-u3-X36']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C20","difficulty":1,"kind":"ox","stem":"대한민국 정부는 헌법을 만들고 대통령을 뽑은 뒤에 세워졌어요.","answer":"O","reason_options":[{"t":"총선거 → 헌법 → 대통령 → 정부 수립의 차례로 세워졌기 때문에","correct":true},{"t":"정부를 먼저 세우고 나중에 선거를 했기 때문에","mis":"SO5-2-u3-X36"}],"mis":"SO5-2-u3-X36","explanation":["먼저 총선거예요.","헌법과 대통령이에요.","그다음 정부 수립이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_basic#5','soc',5,2,'u3','L06','g5_2_soc_u3_L06_basic','lesson_basic','SO5-2-u3-C19',2,'mc','auto','어느 여름날의 거리 자료로 보아 사람들이 거리에 모여 만세를 부른 까닭은 어느 것인가요?',ARRAY['SO5-2-u3-X46']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C19","difficulty":2,"kind":"mc","stem":"어느 여름날의 거리 자료로 보아 사람들이 거리에 모여 만세를 부른 까닭은 어느 것인가요?","options":[{"t":"빼앗겼던 나라를 되찾았기 때문에","correct":true},{"t":"6·25 전쟁이 시작되었기 때문에","mis":"SO5-2-u3-X46"},{"t":"을사늑약이 맺어졌기 때문에","mis":"SO5-2-u3-X46"},{"t":"토지 조사 사업이 끝났기 때문에","mis":"SO5-2-u3-X46"}],"explanation":["태극기를 흔들었어요.","독립운동가가 풀려났어요.","광복을 맞았어요."],"asset":{"type":"passage","lines":["8월 어느 날, 전차가 지나가지 못할 만큼 거리가 사람으로 가득 찼다.","사람들은 태극기를 흔들며 목청껏 만세를 불렀다.","감옥에 갇혀 있던 독립운동가들이 풀려났다.","나라 밖에 살던 동포들이 배를 타고 돌아왔다."],"title":"어느 여름날의 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_basic#6','soc',5,2,'u3','L06','g5_2_soc_u3_L06_basic','lesson_basic','SO5-2-u3-C19',2,'mc','auto','광복 다음 날의 교실 자료에서 달라진 생활로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X35']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C19","difficulty":2,"kind":"mc","stem":"광복 다음 날의 교실 자료에서 달라진 생활로 알맞은 것은 어느 것인가요?","options":[{"t":"일본식 이름 대신 원래 우리 이름을 쓸 수 있게 되었다","correct":true},{"t":"일본식 이름을 새로 지어야 했다","mis":"SO5-2-u3-X35"},{"t":"이름을 아무도 부르지 않았다","mis":"SO5-2-u3-X35"},{"t":"출석을 일본어로만 불렀다","mis":"SO5-2-u3-X35"}],"explanation":["원래 이름을 썼어요.","소리 내어 말했어요.","우리 이름을 되찾았어요."],"asset":{"type":"passage","lines":["광복 다음 날, 일본인 담임 선생님이 칠판에 자기의 원래 이름을 썼다.","선생님은 집에서 부르는 우리 이름을 하나씩 말해 보라고 했다.","출석부 차례대로 아이들이 처음으로 자기 이름을 소리 내어 말했다."],"title":"광복 다음 날의 교실"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_basic#7','soc',5,2,'u3','L06','g5_2_soc_u3_L06_basic','lesson_basic','SO5-2-u3-C20',2,'mc','auto','광복 뒤 한반도 메모로 보아 38도선 남쪽과 북쪽에 들어온 군대를 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X37']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C20","difficulty":2,"kind":"mc","stem":"광복 뒤 한반도 메모로 보아 38도선 남쪽과 북쪽에 들어온 군대를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"남쪽 미군 · 북쪽 소련군","correct":true},{"t":"남쪽 소련군 · 북쪽 미군","mis":"SO5-2-u3-X37"},{"t":"남쪽 중국군 · 북쪽 미군","mis":"SO5-2-u3-X37"},{"t":"남쪽 일본군 · 북쪽 소련군","mis":"SO5-2-u3-X37"}],"explanation":["남쪽은 미군이에요.","북쪽은 소련군이에요.","38도선이 기준이에요."],"asset":{"type":"passage","lines":["광복 뒤 북위 38도선 남쪽에는 미군이 들어왔다.","38도선 북쪽에는 소련군이 들어왔다.","사람들은 하나의 정부를 세우려 했지만 의견이 엇갈렸다."],"title":"광복 뒤 한반도 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_basic#8','soc',5,2,'u3','L06','g5_2_soc_u3_L06_basic','lesson_basic','SO5-2-u3-C19',2,'mc','auto','광복을 맞을 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X34','SO5-2-u3-X46']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C19","difficulty":2,"kind":"mc","stem":"광복을 맞을 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라 안팎의 끊임없는 독립운동과 연합국의 승리가 함께했기 때문에","correct":true},{"t":"일제가 스스로 착해졌기 때문에","mis":"SO5-2-u3-X34"},{"t":"연합국이 이겨서 아무 노력 없이 저절로 되었기 때문에","mis":"SO5-2-u3-X34"},{"t":"6·25 전쟁에서 이겼기 때문에","mis":"SO5-2-u3-X46"}],"explanation":["독립운동이 이어졌어요.","연합국이 이겼어요.","두 힘이 함께했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_basic#9','soc',5,2,'u3','L06','g5_2_soc_u3_L06_basic','lesson_basic','SO5-2-u3-C20',2,'ox','auto','5·10 총선거는 남한과 북한 모두에서 함께 치렀어요.',ARRAY['SO5-2-u3-X38']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C20","difficulty":2,"kind":"ox","stem":"5·10 총선거는 남한과 북한 모두에서 함께 치렀어요.","answer":"X","reason_options":[{"t":"국제 연합의 결정으로 선거가 가능한 남한에서만 치렀기 때문에","correct":true},{"t":"북한에서만 치렀기 때문에","mis":"SO5-2-u3-X38"}],"mis":"SO5-2-u3-X38","explanation":["통일 정부가 어려웠어요.","선거가 가능한 곳에서 했어요.","남한에서만 치렀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_basic#10','soc',5,2,'u3','L06','g5_2_soc_u3_L06_basic','lesson_basic','SO5-2-u3-C20',3,'error','auto','정부가 세워지기까지 카드를 두고 친구들이 차례를 말했어요. 바르게 말하지 않은 친구는 누구인가요?',ARRAY['SO5-2-u3-X36']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C20","difficulty":3,"kind":"error","stem":"정부가 세워지기까지 카드를 두고 친구들이 차례를 말했어요. 바르게 말하지 않은 친구는 누구인가요?","options":[{"t":"하온 — 「다 → 나 → 라 → 가 순서야.」","correct":true,"mis_target":"SO5-2-u3-X36"},{"t":"시아 — 「나가 맨 처음이야.」","mis":"SO5-2-u3-X36"},{"t":"준서 — 「다가 맨 마지막이야.」","mis":"SO5-2-u3-X36"}],"explanation":["총선거가 처음이에요.","정부 수립이 마지막이에요.","하온의 차례가 틀렸어요."],"asset":{"type":"passage","lines":["가 — 헌법에 따라 첫 번째 대통령을 뽑았다.","나 — 남한에서 총선거를 치러 국회의원을 뽑았다.","다 — 대한민국 정부가 세워졌다.","라 — 국회의원들이 헌법을 만들어 널리 알렸다."],"title":"정부가 세워지기까지 카드(차례가 섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_challenge#1','soc',5,2,'u3','L06','g5_2_soc_u3_L06_challenge','lesson_challenge','SO5-2-u3-C19',2,'match','auto','광복 이전과 이후의 생활을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C19","difficulty":2,"kind":"match","stem":"광복 이전과 이후의 생활을 알맞게 이으세요.","pairs":[{"l":"일본식 성과 이름","r":"원래 성과 이름"},{"l":"일본어 수업","r":"우리말 수업"},{"l":"없어진 한글 신문","r":"다시 나온 한글 신문"}],"mis":"SO5-2-u3-X35","explanation":["이름을 되찾았어요.","우리말로 배웠어요.","한글 신문이 다시 나왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_challenge#2','soc',5,2,'u3','L06','g5_2_soc_u3_L06_challenge','lesson_challenge','SO5-2-u3-C20',2,'mc','auto','정부가 세워지기까지 카드를 차례대로 바르게 놓은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X36']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C20","difficulty":2,"kind":"mc","stem":"정부가 세워지기까지 카드를 차례대로 바르게 놓은 것은 어느 것인가요?","options":[{"t":"나 → 라 → 가 → 다","correct":true},{"t":"다 → 나 → 라 → 가","mis":"SO5-2-u3-X36"},{"t":"가 → 나 → 다 → 라","mis":"SO5-2-u3-X36"},{"t":"나 → 가 → 라 → 다","mis":"SO5-2-u3-X36"}],"explanation":["총선거가 먼저예요.","헌법 다음 대통령이에요.","정부 수립이 마지막이에요."],"asset":{"type":"passage","lines":["가 — 헌법에 따라 첫 번째 대통령을 뽑았다.","나 — 남한에서 총선거를 치러 국회의원을 뽑았다.","다 — 대한민국 정부가 세워졌다.","라 — 국회의원들이 헌법을 만들어 널리 알렸다."],"title":"정부가 세워지기까지 카드(차례가 섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_challenge#3','soc',5,2,'u3','L06','g5_2_soc_u3_L06_challenge','lesson_challenge','SO5-2-u3-C20',3,'mc','auto','5·10 총선거 포스터와 사진으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X38']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C20","difficulty":3,"kind":"mc","stem":"5·10 총선거 포스터와 사진으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"일정한 나이가 된 국민이면 남녀 구분 없이 누구나 투표할 수 있었다","correct":true},{"t":"양반만 투표할 수 있었다","mis":"SO5-2-u3-X38"},{"t":"남자만 투표소에 갈 수 있었다","mis":"SO5-2-u3-X38"},{"t":"투표는 하고 싶은 사람만 몰래 했다","mis":"SO5-2-u3-X38"}],"explanation":["아기 업은 여성이 있어요.","남녀가 함께예요.","누구나 투표했어요."],"asset":{"type":"passage","lines":["포스터 — 「투표는 국민의 의무, 빠짐없이 투표하자」","사진 — 아기를 업은 여성과 나이 든 남성이 투표함에 표를 넣는다.","사진 — 남자와 여자가 함께 투표소 벽보를 들여다본다."],"title":"5·10 총선거 포스터와 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_challenge#4','soc',5,2,'u3','L06','g5_2_soc_u3_L06_challenge','lesson_challenge','SO5-2-u3-C20',3,'mc','auto','광복 뒤 하나의 통일 정부를 세우기 어려워진 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X37','SO5-2-u3-X46']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C20","difficulty":3,"kind":"mc","stem":"광복 뒤 하나의 통일 정부를 세우기 어려워진 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남과 북, 미국과 소련의 의견이 서로 달랐기 때문에","correct":true},{"t":"우리 민족이 통일을 원하지 않았기 때문에","mis":"SO5-2-u3-X37"},{"t":"일제가 다시 쳐들어왔기 때문에","mis":"SO5-2-u3-X46"},{"t":"처음부터 남북이 다른 나라였기 때문에","mis":"SO5-2-u3-X37"}],"explanation":["우리 민족은 통일 정부를 원했어요.","의견이 엇갈렸어요.","그래서 어려워졌어요."],"asset":{"type":"passage","lines":["광복 뒤 북위 38도선 남쪽에는 미군이 들어왔다.","38도선 북쪽에는 소련군이 들어왔다.","사람들은 하나의 정부를 세우려 했지만 의견이 엇갈렸다."],"title":"광복 뒤 한반도 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_challenge#5','soc',5,2,'u3','L06','g5_2_soc_u3_L06_challenge','lesson_challenge','SO5-2-u3-C19',3,'ox','auto','광복 다음 날의 교실 자료처럼 광복은 학교와 사람들의 생활까지 바꾸었어요.',ARRAY['SO5-2-u3-X35']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C19","difficulty":3,"kind":"ox","stem":"광복 다음 날의 교실 자료처럼 광복은 학교와 사람들의 생활까지 바꾸었어요.","answer":"O","reason_options":[{"t":"우리 이름과 우리말을 되찾아 생활 속에서 쓰게 되었기 때문에","correct":true},{"t":"광복 뒤에도 학교는 하나도 달라지지 않았기 때문에","mis":"SO5-2-u3-X35"}],"mis":"SO5-2-u3-X35","explanation":["이름을 되찾았어요.","우리말을 썼어요.","생활이 달라졌어요."],"asset":{"type":"passage","lines":["광복 다음 날, 일본인 담임 선생님이 칠판에 자기의 원래 이름을 썼다.","선생님은 집에서 부르는 우리 이름을 하나씩 말해 보라고 했다.","출석부 차례대로 아이들이 처음으로 자기 이름을 소리 내어 말했다."],"title":"광복 다음 날의 교실"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_challenge#6','soc',5,2,'u3','L06','g5_2_soc_u3_L06_challenge','lesson_challenge','SO5-2-u3-C19',3,'error','auto','광복을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X34','SO5-2-u3-X35']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C19","difficulty":3,"kind":"error","stem":"광복을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이안 — 「광복은 다른 나라가 이겨서 우리는 아무것도 안 했는데 저절로 왔어.」","correct":true,"mis_target":"SO5-2-u3-X34"},{"t":"보민 — 「임시 정부와 독립운동가들이 끝까지 노력했어.」","mis":"SO5-2-u3-X34"},{"t":"예준 — 「나라 밖 동포와 임시 정부 지도자들이 돌아왔어.」","mis":"SO5-2-u3-X35"}],"explanation":["독립운동이 이어졌어요.","연합국의 승리도 있었어요.","이안의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_challenge#7','soc',5,2,'u3','L06','g5_2_soc_u3_L06_challenge','lesson_challenge','SO5-2-u3-C20',3,'mc','auto','5·10 총선거로 뽑힌 국회의원들이 가장 먼저 한 큰일은 어느 것인가요?',ARRAY['SO5-2-u3-X39','SO5-2-u3-X08','SO5-2-u3-X46']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C20","difficulty":3,"kind":"mc","stem":"5·10 총선거로 뽑힌 국회의원들이 가장 먼저 한 큰일은 어느 것인가요?","options":[{"t":"나라의 기본이 되는 헌법을 만들어 널리 알렸다","correct":true},{"t":"6·25 전쟁을 일으켰다","mis":"SO5-2-u3-X39"},{"t":"조선 총독부를 다시 세웠다","mis":"SO5-2-u3-X08"},{"t":"토지 조사 사업을 벌였다","mis":"SO5-2-u3-X46"}],"explanation":["제헌 국회예요.","헌법을 만들었어요.","7월 17일에 알렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_challenge#8','soc',5,2,'u3','L06','g5_2_soc_u3_L06_challenge','lesson_challenge','SO5-2-u3-C20',4,'mc','auto','대한민국 정부 수립이 갖는 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X08','SO5-2-u3-X38']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C20","difficulty":4,"kind":"mc","stem":"대한민국 정부 수립이 갖는 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민이 선거로 뽑은 대표가 만든 헌법에 따라 우리 힘으로 세운 민주 정부다","correct":true},{"t":"일제가 세워 준 정부다","mis":"SO5-2-u3-X08"},{"t":"선거 없이 몇몇이 정한 정부다","mis":"SO5-2-u3-X38"},{"t":"남북이 함께 선거해 세운 통일 정부다","mis":"SO5-2-u3-X38"}],"explanation":["선거로 대표를 뽑았어요.","헌법을 만들었어요.","우리 힘으로 세운 민주 정부예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_challenge#9','soc',5,2,'u3','L06','g5_2_soc_u3_L06_challenge','lesson_challenge','SO5-2-u3-C19',4,'mc','auto','광복을 맞은 학생과 임시 정부 지도자의 마음을 짐작한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X34','SO5-2-u3-X35']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C19","difficulty":4,"kind":"mc","stem":"광복을 맞은 학생과 임시 정부 지도자의 마음을 짐작한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학생은 우리말로 공부하고 군사 훈련을 안 받아 기쁘고, 지도자는 바라던 독립을 이루어 가슴이 벅찼을 것이다","correct":true},{"t":"두 사람 모두 일제가 떠나 섭섭했을 것이다","mis":"SO5-2-u3-X34"},{"t":"학생은 일본식 이름을 계속 쓰게 되어 기뻤을 것이다","mis":"SO5-2-u3-X35"},{"t":"지도자는 나라 밖에 남고 싶었을 것이다","mis":"SO5-2-u3-X34"}],"explanation":["학생의 학교가 달라졌어요.","지도자는 독립을 이루었어요.","모두 기뻤을 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L06_challenge#10','soc',5,2,'u3','L06','g5_2_soc_u3_L06_challenge','lesson_challenge','SO5-2-u3-C19',4,'essay','teacher','어느 여름날의 거리와 광복 다음 날의 교실 자료를 보고, 8·15 광복으로 달라진 생활을 세 가지 쓰고 그 가운데 가장 뜻깊다고 생각하는 것과 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u3-C19","difficulty":4,"kind":"essay","stem":"어느 여름날의 거리와 광복 다음 날의 교실 자료를 보고, 8·15 광복으로 달라진 생활을 세 가지 쓰고 그 가운데 가장 뜻깊다고 생각하는 것과 까닭을 쓰세요.","answer_guide":{"answer":"예: 감옥에 갇혀 있던 독립운동가들이 풀려나고 나라 밖 동포들이 돌아왔다. 학교에서 우리말로 수업하고 우리 역사를 배웠다. 일본식 이름 대신 원래 이름을 쓰게 되었다. 나는 원래 이름을 되찾은 것이 가장 뜻깊다. 이름은 나를 나타내는데 그동안 빼앗겼다가 되찾았기 때문이다.","scoring_points":["달라진 생활 세 가지를 썼는가","가장 뜻깊은 것을 골랐는가","까닭을 썼는가"]},"explanation":["세 가지를 찾아요.","하나를 골라요.","까닭을 써요."],"asset":{"type":"passage","lines":["8월 어느 날, 전차가 지나가지 못할 만큼 거리가 사람으로 가득 찼다.","사람들은 태극기를 흔들며 목청껏 만세를 불렀다.","감옥에 갇혀 있던 독립운동가들이 풀려났다.","나라 밖에 살던 동포들이 배를 타고 돌아왔다."],"title":"어느 여름날의 거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_basic#1','soc',5,2,'u3','L07','g5_2_soc_u3_L07_basic','lesson_basic','SO5-2-u3-C21',1,'mc','auto','6·25 전쟁은 어떻게 시작되었나요?',ARRAY['SO5-2-u3-X39','SO5-2-u3-X46']::text[],false,'{"seq":1,"concept":"SO5-2-u3-C21","difficulty":1,"kind":"mc","stem":"6·25 전쟁은 어떻게 시작되었나요?","options":[{"t":"북한군이 기습적으로 38도선을 넘어 남한으로 쳐들어왔다","correct":true},{"t":"남한이 먼저 북한으로 쳐들어갔다","mis":"SO5-2-u3-X39"},{"t":"일본군이 다시 쳐들어왔다","mis":"SO5-2-u3-X46"},{"t":"중국군이 처음부터 쳐들어왔다","mis":"SO5-2-u3-X39"}],"explanation":["북한이 무력으로 통일하려 했어요.","기습했어요.","남침이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_basic#2','soc',5,2,'u3','L07','g5_2_soc_u3_L07_basic','lesson_basic','SO5-2-u3-C22',1,'sa','auto','6·25 전쟁 중 학교 건물이 무너지자 학생들이 공부한 곳은 무엇인가요? (○○ 학교)','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u3-C22","difficulty":1,"kind":"sa","stem":"6·25 전쟁 중 학교 건물이 무너지자 학생들이 공부한 곳은 무엇인가요? (○○ 학교)","answer":["천막 학교","천막학교","천막"],"explanation":["임시로 만들었어요.","천막을 쳤어요.","천막 학교예요."],"mis":"SO5-2-u3-X41"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_basic#3','soc',5,2,'u3','L07','g5_2_soc_u3_L07_basic','lesson_basic','SO5-2-u3-C21',1,'mc','auto','국군과 국제 연합군이 서울을 되찾은 작전은 어느 것인가요?',ARRAY['SO5-2-u3-X42','SO5-2-u3-X46']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C21","difficulty":1,"kind":"mc","stem":"국군과 국제 연합군이 서울을 되찾은 작전은 어느 것인가요?","options":[{"t":"인천 상륙 작전","correct":true},{"t":"흥남 철수 작전","mis":"SO5-2-u3-X42"},{"t":"청산리 전투","mis":"SO5-2-u3-X46"},{"t":"헤이그 특사","mis":"SO5-2-u3-X46"}],"explanation":["바다에서 올라왔어요.","서울을 되찾았어요.","인천 상륙 작전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_basic#4','soc',5,2,'u3','L07','g5_2_soc_u3_L07_basic','lesson_basic','SO5-2-u3-C21',1,'ox','auto','6·25 전쟁 때 국제 연합은 여러 나라가 참여한 국제 연합군과 물자를 보냈어요.',ARRAY['SO5-2-u3-X39']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C21","difficulty":1,"kind":"ox","stem":"6·25 전쟁 때 국제 연합은 여러 나라가 참여한 국제 연합군과 물자를 보냈어요.","answer":"O","reason_options":[{"t":"북한의 남침을 잘못된 침략이라고 보았기 때문에","correct":true},{"t":"국제 연합이 북한을 도왔기 때문에","mis":"SO5-2-u3-X39"}],"mis":"SO5-2-u3-X39","explanation":["여러 나라가 참여했어요.","물자도 보냈어요.","남침을 막으려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_basic#5','soc',5,2,'u3','L07','g5_2_soc_u3_L07_basic','lesson_basic','SO5-2-u3-C22',2,'mc','auto','임시 수도 부산의 피란민 생활 자료로 알 수 있는 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X41']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C22","difficulty":2,"kind":"mc","stem":"임시 수도 부산의 피란민 생활 자료로 알 수 있는 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"판잣집에 살며 물이 부족해 줄을 섰지만 천막 학교에서 공부를 이어 갔다","correct":true},{"t":"피란민들은 넓은 새집에서 넉넉하게 살았다","mis":"SO5-2-u3-X41"},{"t":"전쟁 중이라 아무도 공부하지 않았다","mis":"SO5-2-u3-X41"},{"t":"물이 넘쳐 아껴 쓸 필요가 없었다","mis":"SO5-2-u3-X41"}],"explanation":["판잣집이에요.","물이 부족했어요.","그래도 공부했어요."],"asset":{"type":"passage","lines":["피란민들이 산비탈에 판자와 상자로 집을 지었다.","수도꼭지 앞에는 물동이가 뱀 꼬리처럼 줄을 섰다.","학교 건물이 무너져 공터에 천막을 치고 수업을 했다.","여러 나이의 학생들이 한 천막에 모여 공부했다."],"title":"임시 수도 부산의 피란민 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_basic#6','soc',5,2,'u3','L07','g5_2_soc_u3_L07_basic','lesson_basic','SO5-2-u3-C21',2,'mc','auto','정전 협정에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X40','SO5-2-u3-X39','SO5-2-u3-X46']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C21","difficulty":2,"kind":"mc","stem":"정전 협정에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"전투를 잠시 멈추기로 약속하고 휴전선을 정했다","correct":true},{"t":"전쟁을 완전히 끝내고 남북이 하나가 되었다","mis":"SO5-2-u3-X40"},{"t":"전쟁을 처음 시작하자는 약속이다","mis":"SO5-2-u3-X39"},{"t":"일제가 항복한 약속이다","mis":"SO5-2-u3-X46"}],"explanation":["정전은 멈춤이에요.","휴전선이 생겼어요.","전쟁이 끝난 건 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_basic#7','soc',5,2,'u3','L07','g5_2_soc_u3_L07_basic','lesson_basic','SO5-2-u3-C22',2,'mc','auto','어느 배 이야기 신문 기사에 해당하는 일은 어느 것인가요?',ARRAY['SO5-2-u3-X42','SO5-2-u3-X46']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C22","difficulty":2,"kind":"mc","stem":"어느 배 이야기 신문 기사에 해당하는 일은 어느 것인가요?","options":[{"t":"흥남 철수","correct":true},{"t":"인천 상륙 작전","mis":"SO5-2-u3-X42"},{"t":"5·10 총선거","mis":"SO5-2-u3-X46"},{"t":"3·1 운동","mis":"SO5-2-u3-X46"}],"explanation":["흥남 부두예요.","피란민을 태웠어요.","흥남 철수예요."],"asset":{"type":"passage","lines":["중국군이 들어오자 국군과 국제 연합군이 다시 물러나야 했다.","흥남 부두에 고향을 떠나려는 피란민이 가득 모였다.","짐을 싣던 배는 실었던 짐을 버리고 피란민을 태웠다.","정해진 인원보다 훨씬 많은 사람이 추위와 배고픔을 견디며 남쪽으로 갔다."],"title":"어느 배 이야기 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_basic#8','soc',5,2,'u3','L07','g5_2_soc_u3_L07_basic','lesson_basic','SO5-2-u3-C21',2,'mc','auto','중국군이 전쟁에 들어온 뒤의 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X39','SO5-2-u3-X40']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C21","difficulty":2,"kind":"mc","stem":"중국군이 전쟁에 들어온 뒤의 일로 알맞은 것은 어느 것인가요?","options":[{"t":"국군과 국제 연합군이 다시 서울을 빼앗기고 물러났다","correct":true},{"t":"국군이 바로 압록강을 건너 통일했다","mis":"SO5-2-u3-X39"},{"t":"전쟁이 곧바로 끝났다","mis":"SO5-2-u3-X40"},{"t":"인천에 처음 상륙했다","mis":"SO5-2-u3-X39"}],"explanation":["중국군이 북한을 도왔어요.","다시 밀렸어요.","서울을 또 빼앗겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_basic#9','soc',5,2,'u3','L07','g5_2_soc_u3_L07_basic','lesson_basic','SO5-2-u3-C22',2,'ox','auto','음식 속으로 — 밀면 이야기를 보면 밀면에는 고향을 그리워하는 피란민의 마음이 담겨 있어요.',ARRAY['SO5-2-u3-X41']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C22","difficulty":2,"kind":"ox","stem":"음식 속으로 — 밀면 이야기를 보면 밀면에는 고향을 그리워하는 피란민의 마음이 담겨 있어요.","answer":"O","reason_options":[{"t":"고향의 냉면을 부산에서 구할 수 있는 재료로 다시 만들었기 때문에","correct":true},{"t":"밀면은 일제가 들여온 음식이기 때문에","mis":"SO5-2-u3-X41"}],"mis":"SO5-2-u3-X41","explanation":["북쪽 고향의 냉면이에요.","부산 재료로 만들었어요.","고향 그리움이 담겼어요."],"asset":{"type":"passage","lines":["북쪽 고향을 떠나 부산으로 온 피란민이 냉면 가게를 열었다.","고향에서 쓰던 재료는 비싸고 구하기 어려웠다.","그래서 부산에서 구할 수 있는 밀가루로 면을 뽑았다.","값싼 냉면으로 불리며 피란민들에게 사랑받았다."],"title":"음식 속으로 — 밀면 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_basic#10','soc',5,2,'u3','L07','g5_2_soc_u3_L07_basic','lesson_basic','SO5-2-u3-C21',3,'error','auto','6·25 전쟁을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X40','SO5-2-u3-X39']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C21","difficulty":3,"kind":"error","stem":"6·25 전쟁을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 「정전 협정을 맺어서 전쟁이 완전히 끝났고 남북이 자유롭게 오가.」","correct":true,"mis_target":"SO5-2-u3-X40"},{"t":"우진 — 「전쟁이 시작되고 사흘 만에 서울을 빼앗겼어.」","mis":"SO5-2-u3-X39"},{"t":"다은 — 「38도선 부근에서 싸우는 동안 회담도 이어졌어.」","mis":"SO5-2-u3-X40"}],"explanation":["정전은 잠시 멈춤이에요.","휴전선이 있어요.","로아의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_challenge#1','soc',5,2,'u3','L07','g5_2_soc_u3_L07_challenge','lesson_challenge','SO5-2-u3-C21',2,'match','auto','두 작전과 그 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C21","difficulty":2,"kind":"match","stem":"두 작전과 그 내용을 알맞게 이으세요.","pairs":[{"l":"인천 상륙 작전","r":"서울을 되찾고 북쪽으로 나아감"},{"l":"흥남 철수","r":"물러나며 피란민을 배에 태움"}],"mis":"SO5-2-u3-X42","explanation":["인천은 되찾은 작전이에요.","흥남은 물러난 작전이에요.","둘을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_challenge#2','soc',5,2,'u3','L07','g5_2_soc_u3_L07_challenge','lesson_challenge','SO5-2-u3-C21',2,'mc','auto','6·25 전쟁 장면 카드를 차례대로 바르게 놓은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X39']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C21","difficulty":2,"kind":"mc","stem":"6·25 전쟁 장면 카드를 차례대로 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉯ → ㉲ → ㉰ → ㉮ → ㉱","correct":true},{"t":"㉲ → ㉯ → ㉰ → ㉮ → ㉱","mis":"SO5-2-u3-X39"},{"t":"㉯ → ㉰ → ㉲ → ㉮ → ㉱","mis":"SO5-2-u3-X39"},{"t":"㉯ → ㉲ → ㉮ → ㉰ → ㉱","mis":"SO5-2-u3-X39"}],"explanation":["남침이 먼저예요.","밀렸다가 되찾았어요.","중국군 뒤에 정전이에요."],"asset":{"type":"passage","lines":["㉮ 중국군이 북한을 도우려고 들어와 다시 서울을 빼앗겼다.","㉯ 북한군이 기습적으로 38도선을 넘어 쳐들어왔다.","㉰ 인천 상륙 작전으로 서울을 되찾고 압록강 부근까지 나아갔다.","㉱ 정전 협정을 맺어 휴전선이 정해졌다.","㉲ 서울을 빼앗기고 낙동강 남쪽까지 밀려났다."],"title":"6·25 전쟁 장면 카드(차례가 섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_challenge#3','soc',5,2,'u3','L07','g5_2_soc_u3_L07_challenge','lesson_challenge','SO5-2-u3-C22',3,'mc','auto','전쟁 중에도 천막 학교를 세워 공부하려 한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X41']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C22","difficulty":3,"kind":"mc","stem":"전쟁 중에도 천막 학교를 세워 공부하려 한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어려운 때에도 배워야 전쟁이 끝난 뒤 나라와 자신의 삶을 다시 일으킬 수 있다고 여겼기 때문에","correct":true},{"t":"전쟁 중에는 할 일이 없었기 때문에","mis":"SO5-2-u3-X41"},{"t":"천막이 학교 건물보다 좋았기 때문에","mis":"SO5-2-u3-X41"},{"t":"공부하면 전쟁에 나가지 않아도 되었기 때문에","mis":"SO5-2-u3-X41"}],"explanation":["학교가 무너졌어요.","그래도 배우려 했어요.","앞날을 위해서예요."],"asset":{"type":"passage","lines":["피란민들이 산비탈에 판자와 상자로 집을 지었다.","수도꼭지 앞에는 물동이가 뱀 꼬리처럼 줄을 섰다.","학교 건물이 무너져 공터에 천막을 치고 수업을 했다.","여러 나이의 학생들이 한 천막에 모여 공부했다."],"title":"임시 수도 부산의 피란민 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_challenge#4','soc',5,2,'u3','L07','g5_2_soc_u3_L07_challenge','lesson_challenge','SO5-2-u3-C22',3,'mc','auto','어느 배 이야기 신문 기사의 배가 실었던 짐을 버리고 피란민을 태운 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-2-u3-X42']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C22","difficulty":3,"kind":"mc","stem":"어느 배 이야기 신문 기사의 배가 실었던 짐을 버리고 피란민을 태운 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"물건보다 사람의 목숨을 먼저 지키려 했다","correct":true},{"t":"짐이 너무 가벼워 필요 없었다","mis":"SO5-2-u3-X42"},{"t":"피란민이 짐을 사려고 했다","mis":"SO5-2-u3-X42"},{"t":"배는 처음부터 사람만 태우는 배였다","mis":"SO5-2-u3-X42"}],"explanation":["짐을 버렸어요.","사람을 태웠어요.","목숨을 먼저 지켰어요."],"asset":{"type":"passage","lines":["중국군이 들어오자 국군과 국제 연합군이 다시 물러나야 했다.","흥남 부두에 고향을 떠나려는 피란민이 가득 모였다.","짐을 싣던 배는 실었던 짐을 버리고 피란민을 태웠다.","정해진 인원보다 훨씬 많은 사람이 추위와 배고픔을 견디며 남쪽으로 갔다."],"title":"어느 배 이야기 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_challenge#5','soc',5,2,'u3','L07','g5_2_soc_u3_L07_challenge','lesson_challenge','SO5-2-u3-C21',3,'ox','auto','6·25 전쟁 때 국군과 국제 연합군은 중국군이 들어오기 전에 압록강 부근까지 나아갔어요.',ARRAY['SO5-2-u3-X39']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C21","difficulty":3,"kind":"ox","stem":"6·25 전쟁 때 국군과 국제 연합군은 중국군이 들어오기 전에 압록강 부근까지 나아갔어요.","answer":"O","reason_options":[{"t":"인천 상륙 작전으로 서울을 되찾은 뒤 북쪽으로 나아갔기 때문에","correct":true},{"t":"전쟁이 시작되자마자 압록강까지 갔기 때문에","mis":"SO5-2-u3-X39"}],"mis":"SO5-2-u3-X39","explanation":["먼저 서울을 되찾았어요.","북쪽으로 나아갔어요.","그 뒤 중국군이 왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_challenge#6','soc',5,2,'u3','L07','g5_2_soc_u3_L07_challenge','lesson_challenge','SO5-2-u3-C22',3,'error','auto','전쟁 중 사람들의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X41']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C22","difficulty":3,"kind":"error","stem":"전쟁 중 사람들의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「피란민들은 편한 새집에 살아서 먹을 것 걱정이 없었어.」","correct":true,"mis_target":"SO5-2-u3-X41"},{"t":"지성 — 「물이 부족해 수도꼭지 앞에 줄을 섰어.」","mis":"SO5-2-u3-X41"},{"t":"나은 — 「고향 음식을 부산 재료로 만든 밀면이 생겼어.」","mis":"SO5-2-u3-X41"}],"explanation":["판잣집이었어요.","물과 먹을 것이 부족했어요.","하율의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_challenge#7','soc',5,2,'u3','L07','g5_2_soc_u3_L07_challenge','lesson_challenge','SO5-2-u3-C21',3,'mc','auto','전쟁이 시작되고 사흘 만에 서울을 빼앗긴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X39','SO5-2-u3-X40']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C21","difficulty":3,"kind":"mc","stem":"전쟁이 시작되고 사흘 만에 서울을 빼앗긴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"북한의 기습적인 침략에 미처 대비하지 못했기 때문에","correct":true},{"t":"남한이 먼저 북쪽으로 군대를 보냈기 때문에","mis":"SO5-2-u3-X39"},{"t":"국제 연합군이 북한을 도왔기 때문에","mis":"SO5-2-u3-X39"},{"t":"정전 협정을 맺었기 때문에","mis":"SO5-2-u3-X40"}],"explanation":["갑자기 쳐들어왔어요.","대비가 부족했어요.","서울을 빼앗겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_challenge#8','soc',5,2,'u3','L07','g5_2_soc_u3_L07_challenge','lesson_challenge','SO5-2-u3-C22',4,'mc','auto','음식 속으로 — 밀면 이야기처럼 오늘날 흔한 음식에서 전쟁의 흔적을 찾는 공부의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X47','SO5-2-u3-X46']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C22","difficulty":4,"kind":"mc","stem":"음식 속으로 — 밀면 이야기처럼 오늘날 흔한 음식에서 전쟁의 흔적을 찾는 공부의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"가까운 생활 속에 역사가 남아 있어 그때 사람들의 삶을 짐작할 수 있다","correct":true},{"t":"음식은 역사와 아무 관계가 없다","mis":"SO5-2-u3-X47"},{"t":"밀면은 조선 시대 왕의 음식이었다","mis":"SO5-2-u3-X46"},{"t":"음식 이름만 외우면 역사를 다 안다","mis":"SO5-2-u3-X47"}],"explanation":["밀면은 피란민이 만들었어요.","오늘도 먹어요.","생활 속에 역사가 있어요."],"asset":{"type":"passage","lines":["북쪽 고향을 떠나 부산으로 온 피란민이 냉면 가게를 열었다.","고향에서 쓰던 재료는 비싸고 구하기 어려웠다.","그래서 부산에서 구할 수 있는 밀가루로 면을 뽑았다.","값싼 냉면으로 불리며 피란민들에게 사랑받았다."],"title":"음식 속으로 — 밀면 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_challenge#9','soc',5,2,'u3','L07','g5_2_soc_u3_L07_challenge','lesson_challenge','SO5-2-u3-C21',4,'mc','auto','정전 협정 뒤 휴전선이 생긴 것이 오늘날까지 미친 영향으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X40','SO5-2-u3-X43']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C21","difficulty":4,"kind":"mc","stem":"정전 협정 뒤 휴전선이 생긴 것이 오늘날까지 미친 영향으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"남북이 자유롭게 오가지 못하는 분단 상황이 이어지고 있다","correct":true},{"t":"남북이 자유롭게 오가며 함께 산다","mis":"SO5-2-u3-X40"},{"t":"휴전선은 곧바로 없어졌다","mis":"SO5-2-u3-X40"},{"t":"전쟁은 그날 완전히 끝나 아무 영향도 없다","mis":"SO5-2-u3-X43"}],"explanation":["전투만 멈췄어요.","휴전선이 남았어요.","분단이 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L07_challenge#10','soc',5,2,'u3','L07','g5_2_soc_u3_L07_challenge','lesson_challenge','SO5-2-u3-C22',4,'essay','teacher','임시 수도 부산의 피란민 생활과 어느 배 이야기 신문 기사를 보고, 전쟁 중 사람들이 겪은 어려움 두 가지와 그 속에서도 이어 간 노력 한 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u3-C22","difficulty":4,"kind":"essay","stem":"임시 수도 부산의 피란민 생활과 어느 배 이야기 신문 기사를 보고, 전쟁 중 사람들이 겪은 어려움 두 가지와 그 속에서도 이어 간 노력 한 가지를 쓰세요.","answer_guide":{"answer":"예: 피란민들은 산비탈에 판자와 상자로 지은 집에 살았고, 물이 부족해 수도꼭지 앞에 길게 줄을 섰다. 흥남에서는 추위와 배고픔을 견디며 비좁은 배에 타고 고향을 떠났다. 그래도 학생들은 무너진 학교 대신 천막 학교에서 공부를 이어 갔다.","scoring_points":["어려움 두 가지를 썼는가","이어 간 노력을 썼는가","자료를 근거로 썼는가"]},"explanation":["집과 물이 부족했어요.","피란길이 힘들었어요.","배움을 이어 갔어요."],"asset":{"type":"passage","lines":["피란민들이 산비탈에 판자와 상자로 집을 지었다.","수도꼭지 앞에는 물동이가 뱀 꼬리처럼 줄을 섰다.","학교 건물이 무너져 공터에 천막을 치고 수업을 했다.","여러 나이의 학생들이 한 천막에 모여 공부했다."],"title":"임시 수도 부산의 피란민 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_basic#1','soc',5,2,'u3','L08','g5_2_soc_u3_L08_basic','lesson_basic','SO5-2-u3-C23',1,'sa','auto','전쟁으로 가족과 헤어져 서로 만나지 못하는 사람들을 무엇이라고 하나요? (○○가족)','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C23","difficulty":1,"kind":"sa","stem":"전쟁으로 가족과 헤어져 서로 만나지 못하는 사람들을 무엇이라고 하나요? (○○가족)","answer":["이산가족","이산 가족"],"explanation":["가족이 흩어졌어요.","만나지 못해요.","이산가족이에요."],"mis":"SO5-2-u3-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_basic#2','soc',5,2,'u3','L08','g5_2_soc_u3_L08_basic','lesson_basic','SO5-2-u3-C23',1,'mc','auto','6·25 전쟁으로 부모를 잃은 아이들을 무엇이라고 하나요?',ARRAY['SO5-2-u3-X44']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C23","difficulty":1,"kind":"mc","stem":"6·25 전쟁으로 부모를 잃은 아이들을 무엇이라고 하나요?","options":[{"t":"전쟁고아","correct":true},{"t":"이산가족","mis":"SO5-2-u3-X44"},{"t":"피란민","mis":"SO5-2-u3-X44"},{"t":"의병","mis":"SO5-2-u3-X44"}],"explanation":["부모를 잃었어요.","전쟁 때문이에요.","전쟁고아예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_basic#3','soc',5,2,'u3','L08','g5_2_soc_u3_L08_basic','lesson_basic','SO5-2-u3-C23',1,'mc','auto','6·25 전쟁으로 훼손된 국가유산으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X43']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C23","difficulty":1,"kind":"mc","stem":"6·25 전쟁으로 훼손된 국가유산으로 알맞은 것은 어느 것인가요?","options":[{"t":"수원 화성","correct":true},{"t":"천막 학교","mis":"SO5-2-u3-X43"},{"t":"휴전선","mis":"SO5-2-u3-X43"},{"t":"밀면","mis":"SO5-2-u3-X43"}],"explanation":["국가유산이에요.","전쟁으로 망가졌어요.","수원 화성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_basic#4','soc',5,2,'u3','L08','g5_2_soc_u3_L08_basic','lesson_basic','SO5-2-u3-C23',1,'ox','auto','6·25 전쟁 뒤 남한과 북한은 서로를 적으로 여기는 감정이 깊어졌어요.',ARRAY['SO5-2-u3-X43']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C23","difficulty":1,"kind":"ox","stem":"6·25 전쟁 뒤 남한과 북한은 서로를 적으로 여기는 감정이 깊어졌어요.","answer":"O","reason_options":[{"t":"같은 민족끼리 싸운 전쟁의 상처가 깊었기 때문에","correct":true},{"t":"전쟁 뒤 남북이 바로 하나가 되었기 때문에","mis":"SO5-2-u3-X43"}],"mis":"SO5-2-u3-X43","explanation":["큰 전쟁을 겪었어요.","상처가 깊어요.","서로를 적으로 여겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_basic#5','soc',5,2,'u3','L08','g5_2_soc_u3_L08_basic','lesson_basic','SO5-2-u3-C23',2,'mc','auto','6·25 전쟁이 남긴 피해 메모로 보아 전쟁의 피해를 입은 사람으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X43']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C23","difficulty":2,"kind":"mc","stem":"6·25 전쟁이 남긴 피해 메모로 보아 전쟁의 피해를 입은 사람으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"군인과 민간인 모두","correct":true},{"t":"군인만","mis":"SO5-2-u3-X43"},{"t":"나라 밖 사람들만","mis":"SO5-2-u3-X43"},{"t":"피해를 입은 사람은 없다","mis":"SO5-2-u3-X43"}],"explanation":["㉮를 보세요.","민간인도 있어요.","모두가 피해를 입었어요."],"asset":{"type":"passage","lines":["㉮ 군인뿐 아니라 많은 민간인이 목숨을 잃거나 다쳤다.","㉯ 집·공장·도로·철도·다리가 무너졌다.","㉰ 수원 화성 같은 국가유산이 크게 훼손되었다.","㉱ 생활필수품과 먹을 것이 오랫동안 모자랐다."],"title":"6·25 전쟁이 남긴 피해 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_basic#6','soc',5,2,'u3','L08','g5_2_soc_u3_L08_basic','lesson_basic','SO5-2-u3-C23',2,'mc','auto','헤어진 아내에게 쓴 어느 편지로 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X43','SO5-2-u3-X44']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C23","difficulty":2,"kind":"mc","stem":"헤어진 아내에게 쓴 어느 편지로 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"피란길에 헤어진 가족을 휴전선 때문에 오랫동안 만나지 못했다","correct":true},{"t":"편지를 쓴 사람은 곧 가족을 만나러 갔다","mis":"SO5-2-u3-X43"},{"t":"가족은 모두 함께 남쪽으로 내려왔다","mis":"SO5-2-u3-X44"},{"t":"편지를 쓴 사람은 전쟁고아다","mis":"SO5-2-u3-X44"}],"explanation":["피란길에 헤어졌어요.","휴전선이 생겼어요.","만나지 못했어요."],"asset":{"type":"passage","lines":["피란길에 둘째만 데리고 남쪽으로 내려왔다.","아내와 다른 아이들은 북쪽에 남겨졌다.","휴전선이 생긴 뒤 다시는 북쪽에 갈 수 없었다.","해마다 여름이 오면 가족 생각에 눈물로 밤을 보낸다."],"title":"헤어진 아내에게 쓴 어느 편지(내용을 쉬운 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_basic#7','soc',5,2,'u3','L08','g5_2_soc_u3_L08_basic','lesson_basic','SO5-2-u3-C23',2,'mc','auto','전쟁 뒤 생활필수품과 먹을 것이 오래 부족했던 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X43','SO5-2-u3-X40']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C23","difficulty":2,"kind":"mc","stem":"전쟁 뒤 생활필수품과 먹을 것이 오래 부족했던 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"공장·도로·철도 같은 시설이 크게 무너졌기 때문에","correct":true},{"t":"사람들이 물건을 쓰지 않았기 때문에","mis":"SO5-2-u3-X43"},{"t":"정전 협정으로 시장이 닫혔기 때문에","mis":"SO5-2-u3-X40"},{"t":"모두 피란을 끝내고 쉬었기 때문에","mis":"SO5-2-u3-X43"}],"explanation":["시설이 무너졌어요.","만들고 나르기 어려웠어요.","오래 부족했어요."],"asset":{"type":"passage","lines":["㉮ 군인뿐 아니라 많은 민간인이 목숨을 잃거나 다쳤다.","㉯ 집·공장·도로·철도·다리가 무너졌다.","㉰ 수원 화성 같은 국가유산이 크게 훼손되었다.","㉱ 생활필수품과 먹을 것이 오랫동안 모자랐다."],"title":"6·25 전쟁이 남긴 피해 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_basic#8','soc',5,2,'u3','L08','g5_2_soc_u3_L08_basic','lesson_basic','SO5-2-u3-C23',2,'mc','auto','이산가족 찾기 방송 자료로 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X43','SO5-2-u3-X44']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C23","difficulty":2,"kind":"mc","stem":"이산가족 찾기 방송 자료로 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"전쟁으로 헤어진 가족을 찾는 아픔이 오랜 세월 뒤까지 이어졌다","correct":true},{"t":"전쟁이 끝나자마자 모든 가족이 다시 만났다","mis":"SO5-2-u3-X43"},{"t":"방송은 하루 만에 끝났다","mis":"SO5-2-u3-X43"},{"t":"이산가족은 전쟁과 관계없다","mis":"SO5-2-u3-X44"}],"explanation":["오랜 세월이 지났어요.","가족을 찾았어요.","아픔이 이어졌어요."],"asset":{"type":"passage","lines":["오랜 세월이 지난 어느 여름, 방송국이 가족 찾기 생방송을 열었다.","사람들이 헤어진 가족의 이름과 특징을 적은 종이를 들고 모였다.","몇 달 동안 이어진 방송으로 만 명이 넘는 가족이 다시 만났다."],"title":"이산가족 찾기 방송"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_basic#9','soc',5,2,'u3','L08','g5_2_soc_u3_L08_basic','lesson_basic','SO5-2-u3-C23',2,'ox','auto','6·25 전쟁의 아픔은 오늘날에는 모두 끝나 아무 영향도 남지 않았어요.',ARRAY['SO5-2-u3-X43']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C23","difficulty":2,"kind":"ox","stem":"6·25 전쟁의 아픔은 오늘날에는 모두 끝나 아무 영향도 남지 않았어요.","answer":"X","reason_options":[{"t":"분단이 이어져 끝내 가족을 만나지 못한 이산가족도 많기 때문에","correct":true},{"t":"휴전선이 없어져 남북이 자유롭게 오가기 때문에","mis":"SO5-2-u3-X43"}],"mis":"SO5-2-u3-X43","explanation":["분단이 이어져요.","이산가족이 있어요.","영향이 오늘까지 남았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_basic#10','soc',5,2,'u3','L08','g5_2_soc_u3_L08_basic','lesson_basic','SO5-2-u3-C23',3,'error','auto','6·25 전쟁 이후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X44','SO5-2-u3-X43']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C23","difficulty":3,"kind":"error","stem":"6·25 전쟁 이후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「이산가족은 전쟁으로 부모를 잃고 혼자 남은 아이들이야.」","correct":true,"mis_target":"SO5-2-u3-X44"},{"t":"승우 — 「부모를 잃은 아이들은 전쟁고아라고 해.」","mis":"SO5-2-u3-X44"},{"t":"지유 — 「휴전선 때문에 북쪽 고향에 못 가는 사람이 많아.」","mis":"SO5-2-u3-X43"}],"explanation":["부모 잃은 아이는 전쟁고아예요.","이산가족은 헤어진 가족이에요.","태린의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_challenge#1','soc',5,2,'u3','L08','g5_2_soc_u3_L08_challenge','lesson_challenge','SO5-2-u3-C23',2,'match','auto','6·25 전쟁이 남긴 피해 메모와 피해의 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C23","difficulty":2,"kind":"match","stem":"6·25 전쟁이 남긴 피해 메모와 피해의 갈래를 알맞게 이으세요.","pairs":[{"l":"㉮","r":"사람의 피해"},{"l":"㉯","r":"시설의 피해"},{"l":"㉰","r":"국가유산의 피해"},{"l":"㉱","r":"생활의 어려움"}],"mis":"SO5-2-u3-X43","explanation":["㉮는 사람이에요.","㉯·㉰는 시설과 유산이에요.","㉱는 생활이에요."],"asset":{"type":"passage","lines":["㉮ 군인뿐 아니라 많은 민간인이 목숨을 잃거나 다쳤다.","㉯ 집·공장·도로·철도·다리가 무너졌다.","㉰ 수원 화성 같은 국가유산이 크게 훼손되었다.","㉱ 생활필수품과 먹을 것이 오랫동안 모자랐다."],"title":"6·25 전쟁이 남긴 피해 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_challenge#2','soc',5,2,'u3','L08','g5_2_soc_u3_L08_challenge','lesson_challenge','SO5-2-u3-C23',2,'mc','auto','이산가족의 아픔이 오늘날까지 이어지는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X43','SO5-2-u3-X40','SO5-2-u3-X44']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C23","difficulty":2,"kind":"mc","stem":"이산가족의 아픔이 오늘날까지 이어지는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"휴전선이 생긴 뒤 남북을 자유롭게 오갈 수 없기 때문에","correct":true},{"t":"이산가족이 가족을 찾고 싶지 않기 때문에","mis":"SO5-2-u3-X43"},{"t":"전쟁이 완전히 끝났기 때문에","mis":"SO5-2-u3-X40"},{"t":"전쟁고아만 아픔을 겪기 때문에","mis":"SO5-2-u3-X44"}],"explanation":["휴전선이 있어요.","오갈 수 없어요.","아픔이 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_challenge#3','soc',5,2,'u3','L08','g5_2_soc_u3_L08_challenge','lesson_challenge','SO5-2-u3-C23',3,'mc','auto','헤어진 아내에게 쓴 어느 편지에서 「해마다 여름」이 특히 슬픈 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X47','SO5-2-u3-X46','SO5-2-u3-X43']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C23","difficulty":3,"kind":"mc","stem":"헤어진 아내에게 쓴 어느 편지에서 「해마다 여름」이 특히 슬픈 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"전쟁이 시작되어 가족과 헤어지게 된 때가 떠오르기 때문에","correct":true},{"t":"여름이 너무 더워서","mis":"SO5-2-u3-X47"},{"t":"여름에 광복을 맞았기 때문에","mis":"SO5-2-u3-X46"},{"t":"여름마다 새 가족을 만나기 때문에","mis":"SO5-2-u3-X43"}],"explanation":["6·25 전쟁은 여름에 시작됐어요.","그때 헤어졌어요.","그래서 슬퍼요."],"asset":{"type":"passage","lines":["피란길에 둘째만 데리고 남쪽으로 내려왔다.","아내와 다른 아이들은 북쪽에 남겨졌다.","휴전선이 생긴 뒤 다시는 북쪽에 갈 수 없었다.","해마다 여름이 오면 가족 생각에 눈물로 밤을 보낸다."],"title":"헤어진 아내에게 쓴 어느 편지(내용을 쉬운 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_challenge#4','soc',5,2,'u3','L08','g5_2_soc_u3_L08_challenge','lesson_challenge','SO5-2-u3-C23',3,'mc','auto','6·25 전쟁이 남긴 피해 메모 ㉯와 ㉱를 이어 「~해서 → 그래서」로 말한 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46','SO5-2-u3-X43']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C23","difficulty":3,"kind":"mc","stem":"6·25 전쟁이 남긴 피해 메모 ㉯와 ㉱를 이어 「~해서 → 그래서」로 말한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"시설이 무너져서 → 물건을 만들고 나르기 어려워 생활필수품이 오래 부족했다","correct":true},{"t":"물건이 부족해서 → 다리가 무너졌다","mis":"SO5-2-u3-X46"},{"t":"다리가 무너져서 → 국가유산이 늘었다","mis":"SO5-2-u3-X43"},{"t":"먹을 것이 넘쳐서 → 공장을 부쉈다","mis":"SO5-2-u3-X43"}],"explanation":["㉯가 먼저예요.","그래서 ㉱가 생겨요.","까닭과 결과를 이어요."],"asset":{"type":"passage","lines":["㉮ 군인뿐 아니라 많은 민간인이 목숨을 잃거나 다쳤다.","㉯ 집·공장·도로·철도·다리가 무너졌다.","㉰ 수원 화성 같은 국가유산이 크게 훼손되었다.","㉱ 생활필수품과 먹을 것이 오랫동안 모자랐다."],"title":"6·25 전쟁이 남긴 피해 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_challenge#5','soc',5,2,'u3','L08','g5_2_soc_u3_L08_challenge','lesson_challenge','SO5-2-u3-C23',3,'ox','auto','이산가족 찾기 방송으로 다시 만난 가족이 있었지만 끝내 가족을 만나지 못한 사람도 많아요.',ARRAY['SO5-2-u3-X43']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C23","difficulty":3,"kind":"ox","stem":"이산가족 찾기 방송으로 다시 만난 가족이 있었지만 끝내 가족을 만나지 못한 사람도 많아요.","answer":"O","reason_options":[{"t":"남북으로 갈린 가족은 휴전선 때문에 오갈 수 없었기 때문에","correct":true},{"t":"방송에 나간 사람은 모두 가족을 만났기 때문에","mis":"SO5-2-u3-X43"}],"mis":"SO5-2-u3-X43","explanation":["만난 가족이 있어요.","못 만난 사람도 있어요.","분단 때문이에요."],"asset":{"type":"passage","lines":["오랜 세월이 지난 어느 여름, 방송국이 가족 찾기 생방송을 열었다.","사람들이 헤어진 가족의 이름과 특징을 적은 종이를 들고 모였다.","몇 달 동안 이어진 방송으로 만 명이 넘는 가족이 다시 만났다."],"title":"이산가족 찾기 방송"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_challenge#6','soc',5,2,'u3','L08','g5_2_soc_u3_L08_challenge','lesson_challenge','SO5-2-u3-C23',3,'error','auto','전쟁의 피해를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X43']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C23","difficulty":3,"kind":"error","stem":"전쟁의 피해를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「전쟁 피해는 싸운 군인만 입었고 마을 사람들은 괜찮았어.」","correct":true,"mis_target":"SO5-2-u3-X43"},{"t":"세아 — 「민간인도 많이 목숨을 잃거나 다쳤어.」","mis":"SO5-2-u3-X43"},{"t":"도하 — 「수원 화성 같은 국가유산도 훼손됐어.」","mis":"SO5-2-u3-X43"}],"explanation":["민간인도 피해를 입었어요.","유산도 망가졌어요.","현우의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_challenge#7','soc',5,2,'u3','L08','g5_2_soc_u3_L08_challenge','lesson_challenge','SO5-2-u3-C23',3,'mc','auto','전쟁고아가 많이 생긴 것이 전쟁 뒤 사회에 준 어려움으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X44','SO5-2-u3-X41']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C23","difficulty":3,"kind":"mc","stem":"전쟁고아가 많이 생긴 것이 전쟁 뒤 사회에 준 어려움으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"부모 없이 자라는 아이들을 돌보고 먹이는 일이 큰 과제가 되었다","correct":true},{"t":"아이들이 모두 가족을 곧 되찾았다","mis":"SO5-2-u3-X44"},{"t":"학교가 더 필요 없어졌다","mis":"SO5-2-u3-X41"},{"t":"전쟁고아는 이산가족과 같은 말이다","mis":"SO5-2-u3-X44"}],"explanation":["부모를 잃었어요.","돌봐 줄 사람이 필요했어요.","사회의 큰 과제였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_challenge#8','soc',5,2,'u3','L08','g5_2_soc_u3_L08_challenge','lesson_challenge','SO5-2-u3-C23',4,'mc','auto','6·25 전쟁을 공부한 뒤 가질 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X43','SO5-2-u3-X47']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C23","difficulty":4,"kind":"mc","stem":"6·25 전쟁을 공부한 뒤 가질 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"전쟁의 아픔이 오늘까지 이어짐을 알고 평화를 소중히 여기며 상처를 치유하려고 관심을 갖는다","correct":true},{"t":"지난 일이니 잊어도 된다","mis":"SO5-2-u3-X43"},{"t":"전쟁 날짜만 외우면 된다","mis":"SO5-2-u3-X47"},{"t":"다른 사람의 아픔은 나와 관계없다","mis":"SO5-2-u3-X43"}],"explanation":["아픔이 이어져요.","평화가 소중해요.","관심을 가져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_challenge#9','soc',5,2,'u3','L08','g5_2_soc_u3_L08_challenge','lesson_challenge','SO5-2-u3-C23',4,'mc','auto','「6·25 전쟁 → 정전 협정 → 오늘날」을 이어 가장 알맞게 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u3-X40','SO5-2-u3-X43']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C23","difficulty":4,"kind":"mc","stem":"「6·25 전쟁 → 정전 협정 → 오늘날」을 이어 가장 알맞게 정리한 것은 어느 것인가요?","options":[{"t":"큰 피해를 남긴 전쟁은 정전으로 멈추었지만 휴전선과 분단이 남아 이산가족의 아픔이 이어진다","correct":true},{"t":"전쟁은 정전으로 완전히 끝나 오늘날 아무 흔적이 없다","mis":"SO5-2-u3-X40"},{"t":"전쟁 뒤 남북은 곧바로 하나가 되었다","mis":"SO5-2-u3-X43"},{"t":"정전 뒤 전쟁이 다시 시작되어 오늘까지 싸운다","mis":"SO5-2-u3-X40"}],"explanation":["큰 피해가 있었어요.","정전으로 멈췄어요.","분단이 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L08_challenge#10','soc',5,2,'u3','L08','g5_2_soc_u3_L08_challenge','lesson_challenge','SO5-2-u3-C23',4,'essay','teacher','헤어진 아내에게 쓴 어느 편지와 이산가족 찾기 방송 자료를 보고, 6·25 전쟁이 사람들의 삶에 남긴 영향을 쓰고, 이 아픔을 덜기 위해 오늘날 우리가 할 수 있는 일을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u3-C23","difficulty":4,"kind":"essay","stem":"헤어진 아내에게 쓴 어느 편지와 이산가족 찾기 방송 자료를 보고, 6·25 전쟁이 사람들의 삶에 남긴 영향을 쓰고, 이 아픔을 덜기 위해 오늘날 우리가 할 수 있는 일을 쓰세요.","answer_guide":{"answer":"예: 6·25 전쟁으로 피란길에 가족이 헤어졌고, 휴전선이 생겨 남북을 오갈 수 없어 오랜 세월 가족을 만나지 못한 이산가족이 많다. 방송으로 다시 만난 가족도 있지만 끝내 만나지 못한 사람도 많다. 우리는 이산가족의 아픔에 관심을 갖고 평화를 소중히 여기며, 다시 전쟁이 일어나지 않도록 서로 이해하려고 노력할 수 있다.","scoring_points":["헤어짐과 분단의 영향을 썼는가","자료를 근거로 썼는가","오늘날 할 수 있는 일을 썼는가"]},"explanation":["가족이 헤어졌어요.","분단이 이어져요.","할 수 있는 일을 써요."],"asset":{"type":"passage","lines":["피란길에 둘째만 데리고 남쪽으로 내려왔다.","아내와 다른 아이들은 북쪽에 남겨졌다.","휴전선이 생긴 뒤 다시는 북쪽에 갈 수 없었다.","해마다 여름이 오면 가족 생각에 눈물로 밤을 보낸다."],"title":"헤어진 아내에게 쓴 어느 편지(내용을 쉬운 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_basic#1','soc',5,2,'u3','L09','g5_2_soc_u3_L09_basic','lesson_basic','SO5-2-u3-C24',1,'mc','auto','3·1 운동을 기념하는 날은 어느 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":1,"concept":"SO5-2-u3-C24","difficulty":1,"kind":"mc","stem":"3·1 운동을 기념하는 날은 어느 것인가요?","options":[{"t":"삼일절","correct":true},{"t":"광복절","mis":"SO5-2-u3-X45"},{"t":"제헌절","mis":"SO5-2-u3-X45"},{"t":"개천절","mis":"SO5-2-u3-X45"}],"explanation":["3월 1일이에요.","만세를 외친 날이에요.","삼일절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_basic#2','soc',5,2,'u3','L09','g5_2_soc_u3_L09_basic','lesson_basic','SO5-2-u3-C24',1,'mc','auto','나라를 되찾은 날을 기념하는 날은 어느 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C24","difficulty":1,"kind":"mc","stem":"나라를 되찾은 날을 기념하는 날은 어느 것인가요?","options":[{"t":"광복절","correct":true},{"t":"삼일절","mis":"SO5-2-u3-X45"},{"t":"한글날","mis":"SO5-2-u3-X45"},{"t":"제헌절","mis":"SO5-2-u3-X45"}],"explanation":["8월 15일이에요.","나라를 되찾았어요.","광복절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_basic#3','soc',5,2,'u3','L09','g5_2_soc_u3_L09_basic','lesson_basic','SO5-2-u3-C24',1,'sa','auto','국회의원들이 헌법을 만들어 널리 알린 날을 기념하는 날은 무엇인가요? (○○절)','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u3-C24","difficulty":1,"kind":"sa","stem":"국회의원들이 헌법을 만들어 널리 알린 날을 기념하는 날은 무엇인가요? (○○절)","answer":["제헌절"],"explanation":["헌법을 만들었어요.","7월 17일이에요.","제헌절이에요."],"mis":"SO5-2-u3-X45"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_basic#4','soc',5,2,'u3','L09','g5_2_soc_u3_L09_basic','lesson_basic','SO5-2-u3-C24',1,'ox','auto','기념일을 알리는 옷에는 기념일의 뜻에 맞는 그림과 문구를 넣어야 해요.',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C24","difficulty":1,"kind":"ox","stem":"기념일을 알리는 옷에는 기념일의 뜻에 맞는 그림과 문구를 넣어야 해요.","answer":"O","reason_options":[{"t":"보는 사람이 기념일의 뜻을 바르게 알 수 있어야 하기 때문에","correct":true},{"t":"아무 그림이나 예쁘면 되기 때문에","mis":"SO5-2-u3-X45"}],"mis":"SO5-2-u3-X45","explanation":["옷으로 알려요.","뜻이 드러나야 해요.","알맞은 그림과 문구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_basic#5','soc',5,2,'u3','L09','g5_2_soc_u3_L09_basic','lesson_basic','SO5-2-u3-C24',2,'mc','auto','우리 반 달력에 표시한 기념일 라에 해당하는 기념일은 어느 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C24","difficulty":2,"kind":"mc","stem":"우리 반 달력에 표시한 기념일 라에 해당하는 기념일은 어느 것인가요?","options":[{"t":"학생 독립운동 기념일","correct":true},{"t":"삼일절","mis":"SO5-2-u3-X45"},{"t":"광복절","mis":"SO5-2-u3-X45"},{"t":"제헌절","mis":"SO5-2-u3-X45"}],"explanation":["11월 3일이에요.","광주의 학생들을 기억해요.","학생 독립운동 기념일이에요."],"asset":{"type":"passage","lines":["가 — 3월 1일","나 — 8월 15일","다 — 7월 17일","라 — 11월 3일"],"title":"우리 반 달력에 표시한 기념일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_basic#6','soc',5,2,'u3','L09','g5_2_soc_u3_L09_basic','lesson_basic','SO5-2-u3-C24',2,'mc','auto','기념일 옷 계획표의 ㉠에 들어갈 문구로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C24","difficulty":2,"kind":"mc","stem":"기념일 옷 계획표의 ㉠에 들어갈 문구로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「대한 독립 만세!」","correct":true},{"t":"「전쟁을 멈추자!」","mis":"SO5-2-u3-X45"},{"t":"「우리 물건 우리가 쓰자!」","mis":"SO5-2-u3-X45"},{"t":"「투표는 국민의 의무!」","mis":"SO5-2-u3-X45"}],"explanation":["삼일절을 골랐어요.","핵심어는 독립·만세예요.","「대한 독립 만세!」예요."],"asset":{"type":"passage","lines":["내가 고른 기념일 — 삼일절","기념하는 것 — 온 민족이 독립을 외친 3·1 운동","그날 하는 일 — 집집마다 태극기를 단다.","핵심어 — 독립, 만세, 태극기","옷에 넣을 그림 — 태극기를 든 사람들","옷에 넣을 문구 — ㉠"],"title":"기념일 옷 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_basic#7','soc',5,2,'u3','L09','g5_2_soc_u3_L09_basic','lesson_basic','SO5-2-u3-C24',2,'mc','auto','기념일 옷 만들기 순서에서 가장 먼저 할 일은 어느 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C24","difficulty":2,"kind":"mc","stem":"기념일 옷 만들기 순서에서 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"㉯ 알리고 싶은 기념일을 하나 고른다","correct":true},{"t":"㉮ 핵심어를 뽑아 그림과 문구를 구상한다","mis":"SO5-2-u3-X45"},{"t":"㉰ 옷을 완성해 소개한다","mis":"SO5-2-u3-X45"},{"t":"㉱ 기념일을 조사해 정리한다","mis":"SO5-2-u3-X45"}],"explanation":["먼저 골라요.","그다음 조사해요.","㉯가 처음이에요."],"asset":{"type":"passage","lines":["㉮ 핵심어를 뽑아 그림과 문구를 구상한다.","㉯ 알리고 싶은 기념일을 하나 고른다.","㉰ 옷을 완성해 친구들에게 소개한다.","㉱ 기념하는 것·까닭·그날 하는 일을 조사해 정리한다."],"title":"기념일 옷 만들기 순서(섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_basic#8','soc',5,2,'u3','L09','g5_2_soc_u3_L09_basic','lesson_basic','SO5-2-u3-C24',2,'mc','auto','6·10 만세 운동 기념일을 알리는 옷에 넣을 그림으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C24","difficulty":2,"kind":"mc","stem":"6·10 만세 운동 기념일을 알리는 옷에 넣을 그림으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"장례 행렬 옆에서 태극기를 들고 만세를 외치는 학생들","correct":true},{"t":"천막 학교에서 공부하는 학생들","mis":"SO5-2-u3-X45"},{"t":"투표함에 표를 넣는 사람들","mis":"SO5-2-u3-X45"},{"t":"흥남 부두의 배","mis":"SO5-2-u3-X45"}],"explanation":["황제의 장례식 날이에요.","학생들이 외쳤어요.","그 장면이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_basic#9','soc',5,2,'u3','L09','g5_2_soc_u3_L09_basic','lesson_basic','SO5-2-u3-C24',2,'ox','auto','기념일 옷의 그림과 문구는 꾸밈이 자유로우니 역사적 사실과 달라도 괜찮아요.',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C24","difficulty":2,"kind":"ox","stem":"기념일 옷의 그림과 문구는 꾸밈이 자유로우니 역사적 사실과 달라도 괜찮아요.","answer":"X","reason_options":[{"t":"꾸밈은 자유로워도 기념일의 뜻과 사실은 맞아야 하기 때문에","correct":true},{"t":"역사적 사실은 옷과 관계없기 때문에","mis":"SO5-2-u3-X45"}],"mis":"SO5-2-u3-X45","explanation":["꾸밈은 자유예요.","사실은 지켜요.","틀린 내용은 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_basic#10','soc',5,2,'u3','L09','g5_2_soc_u3_L09_basic','lesson_basic','SO5-2-u3-C24',3,'error','auto','기념일 옷 계획을 두고 친구들이 말했어요. 알맞지 않은 계획은 누구의 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C24","difficulty":3,"kind":"error","stem":"기념일 옷 계획을 두고 친구들이 말했어요. 알맞지 않은 계획은 누구의 것인가요?","options":[{"t":"유나 — 「광복절 옷에 「6·25 전쟁이 시작된 날」이라고 쓸래.」","correct":true,"mis_target":"SO5-2-u3-X45"},{"t":"건호 — 「삼일절 옷에 태극기를 든 사람들을 그릴래.」","mis":"SO5-2-u3-X45"},{"t":"소은 — 「제헌절 옷에 헌법 책을 그릴래.」","mis":"SO5-2-u3-X45"}],"explanation":["광복절은 나라를 되찾은 날이에요.","6·25 전쟁과는 달라요.","유나의 계획이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_challenge#1','soc',5,2,'u3','L09','g5_2_soc_u3_L09_challenge','lesson_challenge','SO5-2-u3-C24',2,'match','auto','우리 반 달력에 표시한 기념일과 기념하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C24","difficulty":2,"kind":"match","stem":"우리 반 달력에 표시한 기념일과 기념하는 일을 알맞게 이으세요.","pairs":[{"l":"가 3월 1일","r":"온 민족이 외친 독립 만세"},{"l":"나 8월 15일","r":"나라를 되찾음"},{"l":"다 7월 17일","r":"헌법을 알림"},{"l":"라 11월 3일","r":"차별에 맞선 학생들"}],"mis":"SO5-2-u3-X45","explanation":["3월 1일은 삼일절이에요.","8월 15일은 광복절이에요.","7월 17일은 제헌절, 11월 3일은 학생 독립운동 기념일이에요."],"asset":{"type":"passage","lines":["가 — 3월 1일","나 — 8월 15일","다 — 7월 17일","라 — 11월 3일"],"title":"우리 반 달력에 표시한 기념일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_challenge#2','soc',5,2,'u3','L09','g5_2_soc_u3_L09_challenge','lesson_challenge','SO5-2-u3-C24',2,'mc','auto','기념일 옷 만들기 순서를 바르게 놓은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C24","difficulty":2,"kind":"mc","stem":"기념일 옷 만들기 순서를 바르게 놓은 것은 어느 것인가요?","options":[{"t":"㉯ → ㉱ → ㉮ → ㉰","correct":true},{"t":"㉮ → ㉯ → ㉰ → ㉱","mis":"SO5-2-u3-X45"},{"t":"㉯ → ㉮ → ㉱ → ㉰","mis":"SO5-2-u3-X45"},{"t":"㉱ → ㉰ → ㉯ → ㉮","mis":"SO5-2-u3-X45"}],"explanation":["먼저 골라요.","조사하고 구상해요.","완성해서 소개해요."],"asset":{"type":"passage","lines":["㉮ 핵심어를 뽑아 그림과 문구를 구상한다.","㉯ 알리고 싶은 기념일을 하나 고른다.","㉰ 옷을 완성해 친구들에게 소개한다.","㉱ 기념하는 것·까닭·그날 하는 일을 조사해 정리한다."],"title":"기념일 옷 만들기 순서(섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_challenge#3','soc',5,2,'u3','L09','g5_2_soc_u3_L09_challenge','lesson_challenge','SO5-2-u3-C24',3,'mc','auto','8월 15일이 두 가지 뜻을 함께 지닌 기념일인 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46','SO5-2-u3-X45','SO5-2-u3-X40']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C24","difficulty":3,"kind":"mc","stem":"8월 15일이 두 가지 뜻을 함께 지닌 기념일인 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이날 광복을 맞았고, 몇 해 뒤 같은 날 대한민국 정부가 세워졌기 때문에","correct":true},{"t":"이날 3·1 운동과 6·25 전쟁이 함께 일어났기 때문에","mis":"SO5-2-u3-X46"},{"t":"이날 헌법과 한글이 함께 만들어졌기 때문에","mis":"SO5-2-u3-X45"},{"t":"이날 정전 협정을 맺었기 때문에","mis":"SO5-2-u3-X40"}],"explanation":["광복을 맞았어요.","정부도 세워졌어요.","두 뜻이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_challenge#4','soc',5,2,'u3','L09','g5_2_soc_u3_L09_challenge','lesson_challenge','SO5-2-u3-C24',3,'mc','auto','유엔군 참전의 날을 알리는 옷의 문구로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C24","difficulty":3,"kind":"mc","stem":"유엔군 참전의 날을 알리는 옷의 문구로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「함께 지켜 준 평화, 고맙습니다」","correct":true},{"t":"「우리말을 되찾았다!」","mis":"SO5-2-u3-X45"},{"t":"「대한 독립 만세!」","mis":"SO5-2-u3-X45"},{"t":"「우리가 만든 것 우리가 쓰자!」","mis":"SO5-2-u3-X45"}],"explanation":["여러 나라가 함께 싸웠어요.","평화를 지키려 했어요.","고마움을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_challenge#5','soc',5,2,'u3','L09','g5_2_soc_u3_L09_challenge','lesson_challenge','SO5-2-u3-C24',3,'ox','auto','학생 독립운동 기념일 옷에는 광주에서 차별에 맞서 일어난 학생들을 담을 수 있어요.',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C24","difficulty":3,"kind":"ox","stem":"학생 독립운동 기념일 옷에는 광주에서 차별에 맞서 일어난 학생들을 담을 수 있어요.","answer":"O","reason_options":[{"t":"그 기념일이 광주 학생 항일 운동을 기억하는 날이기 때문에","correct":true},{"t":"그 기념일은 6·25 전쟁을 기억하는 날이기 때문에","mis":"SO5-2-u3-X45"}],"mis":"SO5-2-u3-X45","explanation":["11월 3일이에요.","광주의 학생들이에요.","그 장면을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_challenge#6','soc',5,2,'u3','L09','g5_2_soc_u3_L09_challenge','lesson_challenge','SO5-2-u3-C24',3,'error','auto','기념일을 조사하는 방법을 두고 친구들이 말했어요. 알맞지 않은 방법은 누구의 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C24","difficulty":3,"kind":"error","stem":"기념일을 조사하는 방법을 두고 친구들이 말했어요. 알맞지 않은 방법은 누구의 것인가요?","options":[{"t":"재희 — 「누가 대충 올린 글 하나만 보고 그대로 옮겨 쓸래.」","correct":true,"mis_target":"SO5-2-u3-X45"},{"t":"민규 — 「믿을 만한 기관의 누리집에서 찾아볼래.」","mis":"SO5-2-u3-X45"},{"t":"혜린 — 「달력과 책을 함께 보고 견주어 볼래.」","mis":"SO5-2-u3-X45"}],"explanation":["믿을 만한 곳을 봐요.","여러 자료를 견줘요.","재희의 방법이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_challenge#7','soc',5,2,'u3','L09','g5_2_soc_u3_L09_challenge','lesson_challenge','SO5-2-u3-C24',3,'mc','auto','기념일 옷 계획표에서 「그날 하는 일」을 조사하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X47','SO5-2-u3-X45']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C24","difficulty":3,"kind":"mc","stem":"기념일 옷 계획표에서 「그날 하는 일」을 조사하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기념일의 뜻이 오늘날 생활에서 어떻게 이어지는지 알 수 있기 때문에","correct":true},{"t":"옷의 크기를 정하기 위해서","mis":"SO5-2-u3-X47"},{"t":"기념일 날짜를 바꾸기 위해서","mis":"SO5-2-u3-X45"},{"t":"그날 하는 일은 기념일과 관계없기 때문에","mis":"SO5-2-u3-X47"}],"explanation":["태극기를 달아요.","뜻이 오늘로 이어져요.","그래서 조사해요."],"asset":{"type":"passage","lines":["내가 고른 기념일 — 삼일절","기념하는 것 — 온 민족이 독립을 외친 3·1 운동","그날 하는 일 — 집집마다 태극기를 단다.","핵심어 — 독립, 만세, 태극기","옷에 넣을 그림 — 태극기를 든 사람들","옷에 넣을 문구 — ㉠"],"title":"기념일 옷 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_challenge#8','soc',5,2,'u3','L09','g5_2_soc_u3_L09_challenge','lesson_challenge','SO5-2-u3-C24',4,'mc','auto','대한민국 임시 정부 수립 기념일을 알리는 옷을 만들 때 가장 알맞은 계획은 어느 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C24","difficulty":4,"kind":"mc","stem":"대한민국 임시 정부 수립 기념일을 알리는 옷을 만들 때 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"그림 — 상하이의 작은 청사와 태극기 · 문구 — 「힘을 모아 나라를 되찾자」","correct":true},{"t":"그림 — 천막 학교 · 문구 — 「전쟁을 멈추자」","mis":"SO5-2-u3-X45"},{"t":"그림 — 투표함 · 문구 — 「첫 민주 선거」","mis":"SO5-2-u3-X45"},{"t":"그림 — 장터의 옷감 · 문구 — 「우리 물건을 쓰자」","mis":"SO5-2-u3-X45"}],"explanation":["임시 정부는 상하이에 있었어요.","힘을 모으려 세웠어요.","그 뜻을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_challenge#9','soc',5,2,'u3','L09','g5_2_soc_u3_L09_challenge','lesson_challenge','SO5-2-u3-C24',4,'mc','auto','이 단원의 기념일들을 옷으로 알리는 활동의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X47','SO5-2-u3-X43']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C24","difficulty":4,"kind":"mc","stem":"이 단원의 기념일들을 옷으로 알리는 활동의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기념일에 담긴 사람들의 노력과 아픔을 오늘의 우리가 기억하고 널리 알리는 것","correct":true},{"t":"기념일 날짜만 외우는 것","mis":"SO5-2-u3-X47"},{"t":"예쁜 옷을 많이 갖는 것","mis":"SO5-2-u3-X47"},{"t":"지난 일을 잊고 새로 시작하는 것","mis":"SO5-2-u3-X43"}],"explanation":["기념일에는 뜻이 있어요.","노력과 아픔이 담겼어요.","기억하고 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_L09_challenge#10','soc',5,2,'u3','L09','g5_2_soc_u3_L09_challenge','lesson_challenge','SO5-2-u3-C24',4,'essay','teacher','이 단원에서 공부한 기념일 하나를 골라 기념하는 것과 기념일이 된 까닭을 쓰고, 그 기념일을 알리는 옷에 넣을 그림과 문구를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-2-u3-C24","difficulty":4,"kind":"essay","stem":"이 단원에서 공부한 기념일 하나를 골라 기념하는 것과 기념일이 된 까닭을 쓰고, 그 기념일을 알리는 옷에 넣을 그림과 문구를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 학생 독립운동 기념일(11월 3일)을 골랐다. 광주에서 경찰이 한국 학생만 붙잡자 차별에 맞선 학생 시위가 전국으로 퍼진 일을 기억하려고 정한 날이다. 옷에는 교복을 입고 손을 맞잡은 학생들을 그리고, 「차별에 맞선 용기, 우리가 기억해요」라고 쓰겠다. 학생들이 앞장선 독립운동이라는 뜻이 잘 드러나기 때문이다.","scoring_points":["기념일과 기념하는 것을 바르게 썼는가","기념일이 된 까닭을 썼는가","뜻에 맞는 그림·문구와 까닭을 썼는가"]},"explanation":["기념일을 골라요.","까닭을 조사해요.","그림과 문구를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#1','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C2',1,'mc','auto','솔이네 기억 상자 ①에서 「억지로 맺은 조약」은 어느 것인가요?',ARRAY['SO5-2-u3-X04','SO5-2-u3-X40','SO5-2-u3-X46']::text[],false,'{"seq":1,"concept":"SO5-2-u3-C2","difficulty":1,"kind":"mc","stem":"솔이네 기억 상자 ①에서 「억지로 맺은 조약」은 어느 것인가요?","options":[{"t":"을사늑약","correct":true},{"t":"강화도 조약","mis":"SO5-2-u3-X04"},{"t":"정전 협정","mis":"SO5-2-u3-X40"},{"t":"5·10 총선거","mis":"SO5-2-u3-X46"}],"explanation":["억지로 맺었어요.","시장이 문을 닫았어요.","을사늑약이에요."],"asset":{"type":"passage","lines":["① 상자 맨 아래에 증조할아버지가 젊을 때 쓴 일기가 있었다.","「억지로 조약을 맺었다는 소식에 시장 가게들이 문을 닫았다.」","「옆집 형은 해산된 군인들과 함께 산으로 들어갔다.」"],"title":"솔이네 할머니의 기억 상자 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#2','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C5',1,'mc','auto','솔이네 기억 상자 ②에서 칼을 찬 선생님의 모습은 무엇을 보여 주나요?',ARRAY['SO5-2-u3-X09','SO5-2-u3-X06']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C5","difficulty":1,"kind":"mc","stem":"솔이네 기억 상자 ②에서 칼을 찬 선생님의 모습은 무엇을 보여 주나요?","options":[{"t":"일제가 공포 분위기로 강압적으로 다스린 모습","correct":true},{"t":"선생님이 학생을 지키려 한 모습","mis":"SO5-2-u3-X09"},{"t":"우리 민족이 자유롭게 공부한 모습","mis":"SO5-2-u3-X09"},{"t":"의병이 학교를 지킨 모습","mis":"SO5-2-u3-X06"}],"explanation":["칼을 찼어요.","겁을 주었어요.","강압적인 통치예요."],"asset":{"type":"passage","lines":["② 빛바랜 교실 사진 속 선생님은 허리에 칼을 차고 있었다.","증조할아버지는 땅을 신고하지 못해 빼앗기고 남의 땅을 빌려 농사지었다.","증조할아버지의 동생은 집을 떠나 만주의 학교로 갔다."],"title":"솔이네 할머니의 기억 상자 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#3','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C8',1,'mc','auto','솔이네 기억 상자 ③의 태극기를 흔든 장날 만세는 어느 운동과 관계있나요?',ARRAY['SO5-2-u3-X46','SO5-2-u3-X21','SO5-2-u3-X15']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C8","difficulty":1,"kind":"mc","stem":"솔이네 기억 상자 ③의 태극기를 흔든 장날 만세는 어느 운동과 관계있나요?","options":[{"t":"3·1 운동","correct":true},{"t":"6·25 전쟁","mis":"SO5-2-u3-X46"},{"t":"물산 장려 운동","mis":"SO5-2-u3-X21"},{"t":"의병 운동","mis":"SO5-2-u3-X15"}],"explanation":["장터에서 외쳤어요.","온 마을이 함께했어요.","3·1 운동이에요."],"asset":{"type":"passage","lines":["③ 작은 태극기 한 장이 접혀 있었다.","장날 장터에서 온 마을 사람이 만세를 외칠 때 흔든 것이었다.","그 뒤 증조할아버지의 동생은 상하이에서 신문 만드는 일을 돕는다는 편지를 보냈다."],"title":"솔이네 할머니의 기억 상자 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#4','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C12',1,'mc','auto','솔이네 기억 상자 ④의 광고지와 관계있는 운동은 어느 것인가요?',ARRAY['SO5-2-u3-X21','SO5-2-u3-X23','SO5-2-u3-X22']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C12","difficulty":1,"kind":"mc","stem":"솔이네 기억 상자 ④의 광고지와 관계있는 운동은 어느 것인가요?","options":[{"t":"물산 장려 운동","correct":true},{"t":"농촌 계몽 운동","mis":"SO5-2-u3-X21"},{"t":"6·10 만세 운동","mis":"SO5-2-u3-X23"},{"t":"의병 운동","mis":"SO5-2-u3-X22"}],"explanation":["우리가 만든 것을 써요.","토산품이에요.","물산 장려 운동이에요."],"asset":{"type":"passage","lines":["④ 「우리가 만든 것 우리가 쓰자」라고 적힌 광고지가 있었다.","방학이면 할머니의 오빠는 농촌에 가서 아이들에게 한글을 가르쳤다.","광주의 학생들이 차별에 맞서 일어났다는 신문도 남아 있었다."],"title":"솔이네 할머니의 기억 상자 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#5','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C15',1,'mc','auto','솔이네 기억 상자 ⑤에서 마을 역의 쌀가마가 실려 간 곳으로 가장 알맞은 것은 어디인가요?',ARRAY['SO5-2-u3-X27']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C15","difficulty":1,"kind":"mc","stem":"솔이네 기억 상자 ⑤에서 마을 역의 쌀가마가 실려 간 곳으로 가장 알맞은 것은 어디인가요?","options":[{"t":"항구를 거쳐 일본으로","correct":true},{"t":"마을 농민들의 집으로","mis":"SO5-2-u3-X27"},{"t":"독립군이 있는 만주로","mis":"SO5-2-u3-X27"},{"t":"임시 정부가 있는 상하이로","mis":"SO5-2-u3-X27"}],"explanation":["기차로 실려 갔어요.","항구로 갔어요.","일본으로 갔어요."],"asset":{"type":"passage","lines":["⑤ 마을 역에 쌓인 쌀가마가 기차로 실려 갔다는 메모가 있었다.","어린 할머니는 학교에서 일본식 이름을 써야 했다.","집의 놋그릇과 숟가락까지 거두어 가 나무 숟가락을 썼다고 한다."],"title":"솔이네 할머니의 기억 상자 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#6','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C19',1,'mc','auto','솔이네 기억 상자 ⑥에서 할머니가 「처음으로 내 이름을 크게 말한」 날은 무엇의 다음 날인가요?',ARRAY['SO5-2-u3-X46']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C19","difficulty":1,"kind":"mc","stem":"솔이네 기억 상자 ⑥에서 할머니가 「처음으로 내 이름을 크게 말한」 날은 무엇의 다음 날인가요?","options":[{"t":"8·15 광복","correct":true},{"t":"3·1 운동","mis":"SO5-2-u3-X46"},{"t":"6·25 전쟁","mis":"SO5-2-u3-X46"},{"t":"을사늑약","mis":"SO5-2-u3-X46"}],"explanation":["나라를 되찾았어요.","이름을 되찾았어요.","광복이에요."],"asset":{"type":"passage","lines":["⑥ 「광복 다음 날, 처음으로 내 이름을 크게 말했다.」 할머니의 쪽지다.","할머니는 다시 나온 한글 신문을 읽으며 기뻐했다.","할아버지는 남한에서 처음 치른 총선거 날 투표소 앞에서 사진을 찍었다."],"title":"솔이네 할머니의 기억 상자 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#7','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C22',1,'mc','auto','솔이네 기억 상자 ⑦에서 할머니가 피란 가서 지낸 집은 어느 것인가요?',ARRAY['SO5-2-u3-X41']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C22","difficulty":1,"kind":"mc","stem":"솔이네 기억 상자 ⑦에서 할머니가 피란 가서 지낸 집은 어느 것인가요?","options":[{"t":"산비탈의 판잣집","correct":true},{"t":"은행 옆 높은 건물","mis":"SO5-2-u3-X41"},{"t":"넓은 새 기와집","mis":"SO5-2-u3-X41"},{"t":"상하이의 청사","mis":"SO5-2-u3-X41"}],"explanation":["피란을 갔어요.","산비탈이에요.","판잣집이에요."],"asset":{"type":"passage","lines":["⑦ 피란 가서 부산 산비탈에 지은 판잣집 사진이 있었다.","물동이를 들고 수도꼭지 앞에 줄을 서던 이야기가 적혀 있었다.","할머니는 천막 학교에서 공부했고, 밀가루로 만든 국수를 먹었다고 했다."],"title":"솔이네 할머니의 기억 상자 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#8','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C23',1,'mc','auto','솔이네 기억 상자 ⑧의 신청서를 낸 할머니처럼 전쟁으로 가족과 헤어진 사람들을 무엇이라 하나요?',ARRAY['SO5-2-u3-X44']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C23","difficulty":1,"kind":"mc","stem":"솔이네 기억 상자 ⑧의 신청서를 낸 할머니처럼 전쟁으로 가족과 헤어진 사람들을 무엇이라 하나요?","options":[{"t":"이산가족","correct":true},{"t":"전쟁고아","mis":"SO5-2-u3-X44"},{"t":"의병","mis":"SO5-2-u3-X44"},{"t":"피란 학교","mis":"SO5-2-u3-X44"}],"explanation":["동생과 헤어졌어요.","가족을 찾아요.","이산가족이에요."],"asset":{"type":"passage","lines":["⑧ 마지막으로 낡은 종이 한 장이 나왔다.","헤어진 동생의 이름과 생김새를 적은 가족 찾기 방송 신청서였다.","할머니는 휴전선 너머 고향에 끝내 가 보지 못했다고 말씀하셨다."],"title":"솔이네 할머니의 기억 상자 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#9','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C4',2,'mc','auto','솔이네 기억 상자 ①의 옆집 형처럼 의병 운동이 더 활발해진 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X07','SO5-2-u3-X05','SO5-2-u3-X06']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C4","difficulty":2,"kind":"mc","stem":"솔이네 기억 상자 ①의 옆집 형처럼 의병 운동이 더 활발해진 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"군대 해산으로 훈련받은 군인들이 의병에 들어갔기 때문에","correct":true},{"t":"일제가 의병을 도왔기 때문에","mis":"SO5-2-u3-X07"},{"t":"특사가 회의에서 이겼기 때문에","mis":"SO5-2-u3-X05"},{"t":"의병에는 군인만 있었기 때문에","mis":"SO5-2-u3-X06"}],"explanation":["군대가 해산됐어요.","군인이 합류했어요.","더 활발해졌어요."],"asset":{"type":"passage","lines":["① 상자 맨 아래에 증조할아버지가 젊을 때 쓴 일기가 있었다.","「억지로 조약을 맺었다는 소식에 시장 가게들이 문을 닫았다.」","「옆집 형은 해산된 군인들과 함께 산으로 들어갔다.」"],"title":"솔이네 할머니의 기억 상자 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#10','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C6',2,'mc','auto','솔이네 기억 상자 ②처럼 남의 땅을 빌려 농사지은 농민의 생활로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X11','SO5-2-u3-X10']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C6","difficulty":2,"kind":"mc","stem":"솔이네 기억 상자 ②처럼 남의 땅을 빌려 농사지은 농민의 생활로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"불리한 조건으로 땅을 빌려 살림이 어려웠다","correct":true},{"t":"땅이 많아져 넉넉해졌다","mis":"SO5-2-u3-X11"},{"t":"세금을 하나도 내지 않았다","mis":"SO5-2-u3-X10"},{"t":"나라에서 땅을 돌려받았다","mis":"SO5-2-u3-X10"}],"explanation":["땅을 빼앗겼어요.","빌려 지었어요.","살림이 어려웠어요."],"asset":{"type":"passage","lines":["② 빛바랜 교실 사진 속 선생님은 허리에 칼을 차고 있었다.","증조할아버지는 땅을 신고하지 못해 빼앗기고 남의 땅을 빌려 농사지었다.","증조할아버지의 동생은 집을 떠나 만주의 학교로 갔다."],"title":"솔이네 할머니의 기억 상자 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#11','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C9',2,'mc','auto','솔이네 기억 상자 ③의 편지로 보아 임시 정부가 한 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X17']::text[],false,'{"seq":11,"concept":"SO5-2-u3-C9","difficulty":2,"kind":"mc","stem":"솔이네 기억 상자 ③의 편지로 보아 임시 정부가 한 일로 알맞은 것은 어느 것인가요?","options":[{"t":"신문을 만들어 활동을 알렸다","correct":true},{"t":"땅을 조사해 빼앗았다","mis":"SO5-2-u3-X17"},{"t":"헌병으로 감시했다","mis":"SO5-2-u3-X17"},{"t":"일본식 이름을 쓰게 했다","mis":"SO5-2-u3-X17"}],"explanation":["상하이에서 일했어요.","신문을 만들었어요.","활동을 알렸어요."],"asset":{"type":"passage","lines":["③ 작은 태극기 한 장이 접혀 있었다.","장날 장터에서 온 마을 사람이 만세를 외칠 때 흔든 것이었다.","그 뒤 증조할아버지의 동생은 상하이에서 신문 만드는 일을 돕는다는 편지를 보냈다."],"title":"솔이네 할머니의 기억 상자 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#12','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C11',2,'mc','auto','3·1 운동 뒤 일제가 쌀을 더 많이 생산하게 한 결과로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X20','SO5-2-u3-X19']::text[],false,'{"seq":12,"concept":"SO5-2-u3-C11","difficulty":2,"kind":"mc","stem":"3·1 운동 뒤 일제가 쌀을 더 많이 생산하게 한 결과로 알맞은 것은 어느 것인가요?","options":[{"t":"더 많은 쌀이 일본으로 실려 가 농민의 생활이 더 어려워졌다","correct":true},{"t":"농민의 밥상에 쌀이 넉넉해졌다","mis":"SO5-2-u3-X20"},{"t":"쌀값이 내려 모두 부자가 되었다","mis":"SO5-2-u3-X19"},{"t":"일제가 쌀을 독립군에게 보냈다","mis":"SO5-2-u3-X20"}],"explanation":["쌀을 더 생산했어요.","일본으로 가져갔어요.","생활이 어려워졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#13','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C15',2,'mc','auto','솔이네 기억 상자 ⑤의 쌀가마가 기차로 실려 간 모습으로 알 수 있는 철도의 쓰임은 어느 것인가요?',ARRAY['SO5-2-u3-X27','SO5-2-u3-X46']::text[],false,'{"seq":13,"concept":"SO5-2-u3-C15","difficulty":2,"kind":"mc","stem":"솔이네 기억 상자 ⑤의 쌀가마가 기차로 실려 간 모습으로 알 수 있는 철도의 쓰임은 어느 것인가요?","options":[{"t":"우리나라에서 빼앗은 자원을 일본으로 실어 나르는 데 쓰였다","correct":true},{"t":"농민이 쌀을 팔러 여행하는 데 쓰였다","mis":"SO5-2-u3-X27"},{"t":"독립군을 실어 나르는 데 쓰였다","mis":"SO5-2-u3-X27"},{"t":"피란민을 옮기는 데만 쓰였다","mis":"SO5-2-u3-X46"}],"explanation":["쌀가마가 쌓였어요.","기차로 갔어요.","일본으로 실려 갔어요."],"asset":{"type":"passage","lines":["⑤ 마을 역에 쌓인 쌀가마가 기차로 실려 갔다는 메모가 있었다.","어린 할머니는 학교에서 일본식 이름을 써야 했다.","집의 놋그릇과 숟가락까지 거두어 가 나무 숟가락을 썼다고 한다."],"title":"솔이네 할머니의 기억 상자 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#14','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C20',2,'mc','auto','대한민국 정부가 세워진 차례를 바르게 놓은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X36']::text[],false,'{"seq":14,"concept":"SO5-2-u3-C20","difficulty":2,"kind":"mc","stem":"대한민국 정부가 세워진 차례를 바르게 놓은 것은 어느 것인가요?","options":[{"t":"5·10 총선거 → 헌법 공포 → 대통령 선출 → 정부 수립","correct":true},{"t":"정부 수립 → 5·10 총선거 → 헌법 공포 → 대통령 선출","mis":"SO5-2-u3-X36"},{"t":"대통령 선출 → 헌법 공포 → 5·10 총선거 → 정부 수립","mis":"SO5-2-u3-X36"},{"t":"헌법 공포 → 정부 수립 → 5·10 총선거 → 대통령 선출","mis":"SO5-2-u3-X36"}],"explanation":["선거가 먼저예요.","헌법과 대통령이에요.","정부 수립이 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#15','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C21',2,'mc','auto','6·25 전쟁에서 인천 상륙 작전 뒤의 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X39','SO5-2-u3-X40']::text[],false,'{"seq":15,"concept":"SO5-2-u3-C21","difficulty":2,"kind":"mc","stem":"6·25 전쟁에서 인천 상륙 작전 뒤의 일로 알맞은 것은 어느 것인가요?","options":[{"t":"서울을 되찾고 압록강 부근까지 나아갔다","correct":true},{"t":"낙동강 남쪽까지 밀려났다","mis":"SO5-2-u3-X39"},{"t":"정전 협정을 바로 맺었다","mis":"SO5-2-u3-X40"},{"t":"전쟁이 처음 시작되었다","mis":"SO5-2-u3-X39"}],"explanation":["인천에 올랐어요.","서울을 되찾았어요.","북쪽으로 나아갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#16','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C24',2,'mc','auto','솔이네 기억 상자 ③의 태극기와 가장 관계 깊은 기념일은 어느 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":16,"concept":"SO5-2-u3-C24","difficulty":2,"kind":"mc","stem":"솔이네 기억 상자 ③의 태극기와 가장 관계 깊은 기념일은 어느 것인가요?","options":[{"t":"삼일절","correct":true},{"t":"제헌절","mis":"SO5-2-u3-X45"},{"t":"광복절","mis":"SO5-2-u3-X45"},{"t":"유엔군 참전의 날","mis":"SO5-2-u3-X45"}],"explanation":["장날 만세예요.","3·1 운동이에요.","삼일절이에요."],"asset":{"type":"passage","lines":["③ 작은 태극기 한 장이 접혀 있었다.","장날 장터에서 온 마을 사람이 만세를 외칠 때 흔든 것이었다.","그 뒤 증조할아버지의 동생은 상하이에서 신문 만드는 일을 돕는다는 편지를 보냈다."],"title":"솔이네 할머니의 기억 상자 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#17','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C1',3,'mc','auto','솔이네 기억 상자 ①~④에 나온 사람들의 공통점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X01','SO5-2-u3-X22']::text[],false,'{"seq":17,"concept":"SO5-2-u3-C1","difficulty":3,"kind":"mc","stem":"솔이네 기억 상자 ①~④에 나온 사람들의 공통점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"저마다 다른 방법으로 일제에 맞서 나라를 되찾으려 했다","correct":true},{"t":"모두 일제를 도우며 살았다","mis":"SO5-2-u3-X01"},{"t":"모두 무기를 들고만 싸웠다","mis":"SO5-2-u3-X22"},{"t":"모두 아무것도 하지 못했다","mis":"SO5-2-u3-X01"}],"explanation":["의병·만세·신문이 있어요.","물건과 한글도 있어요.","여러 방법으로 맞섰어요."],"asset":{"type":"passage","lines":["④ 「우리가 만든 것 우리가 쓰자」라고 적힌 광고지가 있었다.","방학이면 할머니의 오빠는 농촌에 가서 아이들에게 한글을 가르쳤다.","광주의 학생들이 차별에 맞서 일어났다는 신문도 남아 있었다."],"title":"솔이네 할머니의 기억 상자 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#18','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C6',3,'mc','auto','솔이네 기억 상자 ②와 ⑤를 함께 볼 때 그때 농민의 생활을 가장 알맞게 짐작한 것은 어느 것인가요?',ARRAY['SO5-2-u3-X19','SO5-2-u3-X20']::text[],false,'{"seq":18,"concept":"SO5-2-u3-C6","difficulty":3,"kind":"mc","stem":"솔이네 기억 상자 ②와 ⑤를 함께 볼 때 그때 농민의 생활을 가장 알맞게 짐작한 것은 어느 것인가요?","options":[{"t":"땅을 잃어 빌려 농사짓고, 거둔 쌀마저 실려 가 생활이 점점 어려워졌다","correct":true},{"t":"땅도 늘고 쌀도 넉넉해 형편이 좋아졌다","mis":"SO5-2-u3-X19"},{"t":"농사를 짓지 않아도 쌀이 생겼다","mis":"SO5-2-u3-X20"},{"t":"쌀이 실려 간 것은 농민과 관계없다","mis":"SO5-2-u3-X20"}],"explanation":["②에서 땅을 잃었어요.","⑤에서 쌀이 실려 갔어요.","생활이 어려워졌어요."],"asset":{"type":"passage","lines":["⑤ 마을 역에 쌓인 쌀가마가 기차로 실려 갔다는 메모가 있었다.","어린 할머니는 학교에서 일본식 이름을 써야 했다.","집의 놋그릇과 숟가락까지 거두어 가 나무 숟가락을 썼다고 한다."],"title":"솔이네 할머니의 기억 상자 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#19','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C13',3,'mc','auto','3·1 운동·6·10 만세 운동·광주 학생 항일 운동의 공통점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X25','SO5-2-u3-X15','SO5-2-u3-X46']::text[],false,'{"seq":19,"concept":"SO5-2-u3-C13","difficulty":3,"kind":"mc","stem":"3·1 운동·6·10 만세 운동·광주 학생 항일 운동의 공통점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학생들이 앞장서거나 함께하며 독립의 뜻을 외쳤다","correct":true},{"t":"모두 만주에서 일어났다","mis":"SO5-2-u3-X25"},{"t":"모두 무기를 든 독립군의 싸움이다","mis":"SO5-2-u3-X15"},{"t":"모두 광복 뒤에 일어났다","mis":"SO5-2-u3-X46"}],"explanation":["3·1 운동에도 학생이 있었어요.","6·10과 광주는 학생이 앞장섰어요.","학생들이 외쳤어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#20','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C19',3,'mc','auto','솔이네 기억 상자 ⑤와 ⑥을 함께 볼 때 할머니의 생활에서 달라진 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X35']::text[],false,'{"seq":20,"concept":"SO5-2-u3-C19","difficulty":3,"kind":"mc","stem":"솔이네 기억 상자 ⑤와 ⑥을 함께 볼 때 할머니의 생활에서 달라진 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"일본식 이름을 써야 했다가 광복 뒤 원래 이름을 되찾았다","correct":true},{"t":"원래 이름을 쓰다가 광복 뒤 일본식 이름을 썼다","mis":"SO5-2-u3-X35"},{"t":"이름은 두 때 모두 같았다","mis":"SO5-2-u3-X35"},{"t":"광복 뒤 한글 신문이 사라졌다","mis":"SO5-2-u3-X35"}],"explanation":["⑤는 일본식 이름이에요.","⑥은 내 이름이에요.","이름을 되찾았어요."],"asset":{"type":"passage","lines":["⑥ 「광복 다음 날, 처음으로 내 이름을 크게 말했다.」 할머니의 쪽지다.","할머니는 다시 나온 한글 신문을 읽으며 기뻐했다.","할아버지는 남한에서 처음 치른 총선거 날 투표소 앞에서 사진을 찍었다."],"title":"솔이네 할머니의 기억 상자 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#21','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C23',3,'mc','auto','솔이네 기억 상자 ⑦과 ⑧을 함께 볼 때 6·25 전쟁이 할머니의 삶에 준 영향으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X43','SO5-2-u3-X44']::text[],false,'{"seq":21,"concept":"SO5-2-u3-C23","difficulty":3,"kind":"mc","stem":"솔이네 기억 상자 ⑦과 ⑧을 함께 볼 때 6·25 전쟁이 할머니의 삶에 준 영향으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"피란 생활을 겪고 동생과 헤어져 고향에 끝내 가지 못했다","correct":true},{"t":"전쟁 뒤 곧바로 고향에 돌아갔다","mis":"SO5-2-u3-X43"},{"t":"동생과 늘 함께 지냈다","mis":"SO5-2-u3-X44"},{"t":"전쟁은 할머니와 관계없었다","mis":"SO5-2-u3-X43"}],"explanation":["⑦은 피란 생활이에요.","⑧은 헤어진 동생이에요.","아픔이 오래 이어졌어요."],"asset":{"type":"passage","lines":["⑧ 마지막으로 낡은 종이 한 장이 나왔다.","헤어진 동생의 이름과 생김새를 적은 가족 찾기 방송 신청서였다.","할머니는 휴전선 너머 고향에 끝내 가 보지 못했다고 말씀하셨다."],"title":"솔이네 할머니의 기억 상자 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#22','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C1',3,'mc','auto','솔이네 기억 상자 ①~⑧이 보여 주는 큰 흐름을 바르게 놓은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46']::text[],false,'{"seq":22,"concept":"SO5-2-u3-C1","difficulty":3,"kind":"mc","stem":"솔이네 기억 상자 ①~⑧이 보여 주는 큰 흐름을 바르게 놓은 것은 어느 것인가요?","options":[{"t":"나라를 빼앗김 → 여러 방법의 저항 → 광복과 정부 수립 → 6·25 전쟁과 그 뒤의 아픔","correct":true},{"t":"6·25 전쟁 → 광복 → 나라를 빼앗김 → 저항","mis":"SO5-2-u3-X46"},{"t":"광복 → 나라를 빼앗김 → 정부 수립 → 저항","mis":"SO5-2-u3-X46"},{"t":"저항 → 6·25 전쟁 → 나라를 빼앗김 → 광복","mis":"SO5-2-u3-X46"}],"explanation":["①~②는 빼앗김이에요.","③~⑤는 저항과 고통이에요.","⑥~⑧은 광복과 전쟁이에요."],"asset":{"type":"passage","lines":["⑧ 마지막으로 낡은 종이 한 장이 나왔다.","헤어진 동생의 이름과 생김새를 적은 가족 찾기 방송 신청서였다.","할머니는 휴전선 너머 고향에 끝내 가 보지 못했다고 말씀하셨다."],"title":"솔이네 할머니의 기억 상자 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#23','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C1',4,'mc','auto','「식민 통치와 저항, 전쟁이 바꾼 사회와 생활」 단원을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u3-X01','SO5-2-u3-X46','SO5-2-u3-X47']::text[],false,'{"seq":23,"concept":"SO5-2-u3-C1","difficulty":4,"kind":"mc","stem":"「식민 통치와 저항, 전쟁이 바꾼 사회와 생활」 단원을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"식민 통치 속에서 우리 민족은 여러 방법으로 저항해 광복을 맞았고, 정부를 세운 뒤 6·25 전쟁을 겪으며 생활이 크게 달라졌다","correct":true},{"t":"일제가 다스리는 동안 우리 민족은 아무것도 하지 않았다","mis":"SO5-2-u3-X01"},{"t":"6·25 전쟁 뒤 3·1 운동으로 나라를 되찾았다","mis":"SO5-2-u3-X46"},{"t":"사건 이름과 날짜만 외우면 이 시대를 다 안다","mis":"SO5-2-u3-X47"}],"explanation":["저항이 이어졌어요.","광복과 정부 수립이 있었어요.","전쟁으로 생활이 바뀌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#24','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C4',4,'essay','teacher','솔이네 기억 상자 ①~③을 보고 나라를 빼앗기기 전후로 우리 민족이 맞선 방법을 세 가지 쓰고, 그 가운데 하나가 그 뒤 독립운동에 준 영향을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-2-u3-C4","difficulty":4,"kind":"essay","stem":"솔이네 기억 상자 ①~③을 보고 나라를 빼앗기기 전후로 우리 민족이 맞선 방법을 세 가지 쓰고, 그 가운데 하나가 그 뒤 독립운동에 준 영향을 쓰세요.","answer_guide":{"answer":"예: 늑약 소식에 상인들은 가게 문을 닫았고, 옆집 형은 해산된 군인들과 의병이 되어 싸웠다. 증조할아버지의 동생은 만주의 학교로 가서 독립군이 될 힘을 길렀고, 장날에는 온 마을이 3·1 운동 만세를 외쳤다. 3·1 운동으로 힘을 모아야 함을 깨달아 상하이에 대한민국 임시 정부를 세웠다.","scoring_points":["맞선 방법 세 가지를 썼는가","기억 상자를 근거로 들었는가","그 뒤에 준 영향을 썼는가"]},"explanation":["의병이 있어요.","만주 학교와 만세도 있어요.","임시 정부로 이어졌어요."],"asset":{"type":"passage","lines":["③ 작은 태극기 한 장이 접혀 있었다.","장날 장터에서 온 마을 사람이 만세를 외칠 때 흔든 것이었다.","그 뒤 증조할아버지의 동생은 상하이에서 신문 만드는 일을 돕는다는 편지를 보냈다."],"title":"솔이네 할머니의 기억 상자 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_a#25','soc',5,2,'u3','','g5_2_soc_u3_review_a','unit_review','SO5-2-u3-C22',4,'essay','teacher','솔이네 기억 상자 ⑦을 보고 6·25 전쟁 중 피란민의 생활을 세 가지 쓰고, 그 속에서도 이어진 노력 하나를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-2-u3-C22","difficulty":4,"kind":"essay","stem":"솔이네 기억 상자 ⑦을 보고 6·25 전쟁 중 피란민의 생활을 세 가지 쓰고, 그 속에서도 이어진 노력 하나를 쓰세요.","answer_guide":{"answer":"예: 피란민들은 부산 산비탈에 판자로 집을 지어 살았고, 물이 부족해 물동이를 들고 수도꼭지 앞에 줄을 섰으며, 고향 냉면 대신 밀가루로 만든 밀면을 먹었다. 그래도 할머니는 천막 학교에서 공부하며 배움을 이어 갔다.","scoring_points":["피란민 생활 세 가지를 썼는가","이어진 노력을 썼는가","기억 상자를 근거로 썼는가"]},"explanation":["판잣집이에요.","물이 부족했어요.","배움을 이어 갔어요."],"asset":{"type":"passage","lines":["⑦ 피란 가서 부산 산비탈에 지은 판잣집 사진이 있었다.","물동이를 들고 수도꼭지 앞에 줄을 서던 이야기가 적혀 있었다.","할머니는 천막 학교에서 공부했고, 밀가루로 만든 국수를 먹었다고 했다."],"title":"솔이네 할머니의 기억 상자 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#1','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C2',1,'sa','auto','을사늑약으로 대한 제국이 빼앗긴 권리는 무엇인가요? (○○권)','{}'::text[],false,'{"seq":1,"concept":"SO5-2-u3-C2","difficulty":1,"kind":"sa","stem":"을사늑약으로 대한 제국이 빼앗긴 권리는 무엇인가요? (○○권)","answer":["외교권"],"explanation":["다른 나라와의 약속이에요.","일본이 감독했어요.","외교권이에요."],"mis":"SO5-2-u3-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#2','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C6',1,'mc','auto','솔이네 기억 상자 ②에서 증조할아버지가 땅을 빼앗긴 일과 관계있는 것은 어느 것인가요?',ARRAY['SO5-2-u3-X21','SO5-2-u3-X15','SO5-2-u3-X46']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C6","difficulty":1,"kind":"mc","stem":"솔이네 기억 상자 ②에서 증조할아버지가 땅을 빼앗긴 일과 관계있는 것은 어느 것인가요?","options":[{"t":"토지 조사 사업","correct":true},{"t":"물산 장려 운동","mis":"SO5-2-u3-X21"},{"t":"3·1 운동","mis":"SO5-2-u3-X15"},{"t":"인천 상륙 작전","mis":"SO5-2-u3-X46"}],"explanation":["땅을 신고해야 했어요.","빼앗겼어요.","토지 조사 사업이에요."],"asset":{"type":"passage","lines":["② 빛바랜 교실 사진 속 선생님은 허리에 칼을 차고 있었다.","증조할아버지는 땅을 신고하지 못해 빼앗기고 남의 땅을 빌려 농사지었다.","증조할아버지의 동생은 집을 떠나 만주의 학교로 갔다."],"title":"솔이네 할머니의 기억 상자 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#3','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C9',1,'mc','auto','솔이네 기억 상자 ③에서 증조할아버지의 동생이 일을 도운 상하이의 정부는 어느 것인가요?',ARRAY['SO5-2-u3-X08','SO5-2-u3-X16','SO5-2-u3-X18']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C9","difficulty":1,"kind":"mc","stem":"솔이네 기억 상자 ③에서 증조할아버지의 동생이 일을 도운 상하이의 정부는 어느 것인가요?","options":[{"t":"대한민국 임시 정부","correct":true},{"t":"조선 총독부","mis":"SO5-2-u3-X08"},{"t":"대한 제국","mis":"SO5-2-u3-X16"},{"t":"한인 애국단","mis":"SO5-2-u3-X18"}],"explanation":["상하이에 있었어요.","신문을 만들었어요.","대한민국 임시 정부예요."],"asset":{"type":"passage","lines":["③ 작은 태극기 한 장이 접혀 있었다.","장날 장터에서 온 마을 사람이 만세를 외칠 때 흔든 것이었다.","그 뒤 증조할아버지의 동생은 상하이에서 신문 만드는 일을 돕는다는 편지를 보냈다."],"title":"솔이네 할머니의 기억 상자 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#4','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C12',1,'mc','auto','솔이네 기억 상자 ④에서 할머니의 오빠가 한 일과 관계있는 운동은 어느 것인가요?',ARRAY['SO5-2-u3-X21','SO5-2-u3-X10','SO5-2-u3-X46']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C12","difficulty":1,"kind":"mc","stem":"솔이네 기억 상자 ④에서 할머니의 오빠가 한 일과 관계있는 운동은 어느 것인가요?","options":[{"t":"농촌 계몽 운동","correct":true},{"t":"물산 장려 운동","mis":"SO5-2-u3-X21"},{"t":"토지 조사 사업","mis":"SO5-2-u3-X10"},{"t":"흥남 철수","mis":"SO5-2-u3-X46"}],"explanation":["방학에 농촌에 갔어요.","한글을 가르쳤어요.","농촌 계몽 운동이에요."],"asset":{"type":"passage","lines":["④ 「우리가 만든 것 우리가 쓰자」라고 적힌 광고지가 있었다.","방학이면 할머니의 오빠는 농촌에 가서 아이들에게 한글을 가르쳤다.","광주의 학생들이 차별에 맞서 일어났다는 신문도 남아 있었다."],"title":"솔이네 할머니의 기억 상자 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#5','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C17',1,'mc','auto','솔이네 기억 상자 ⑤에서 어린 할머니가 학교에서 일본식 이름을 써야 했던 까닭은 무엇인가요?',ARRAY['SO5-2-u3-X30','SO5-2-u3-X35']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C17","difficulty":1,"kind":"mc","stem":"솔이네 기억 상자 ⑤에서 어린 할머니가 학교에서 일본식 이름을 써야 했던 까닭은 무엇인가요?","options":[{"t":"일제가 우리 민족정신을 없애려고 바꾸게 했기 때문에","correct":true},{"t":"할머니가 그 이름을 좋아했기 때문에","mis":"SO5-2-u3-X30"},{"t":"우리 문화를 지키려고","mis":"SO5-2-u3-X30"},{"t":"광복을 축하하려고","mis":"SO5-2-u3-X35"}],"explanation":["이름을 바꾸게 했어요.","민족정신을 없애려 했어요.","억지로 쓰게 했어요."],"asset":{"type":"passage","lines":["⑤ 마을 역에 쌓인 쌀가마가 기차로 실려 갔다는 메모가 있었다.","어린 할머니는 학교에서 일본식 이름을 써야 했다.","집의 놋그릇과 숟가락까지 거두어 가 나무 숟가락을 썼다고 한다."],"title":"솔이네 할머니의 기억 상자 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#6','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C20',1,'mc','auto','솔이네 기억 상자 ⑥에서 할아버지가 투표한 선거는 어느 것인가요?',ARRAY['SO5-2-u3-X46']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C20","difficulty":1,"kind":"mc","stem":"솔이네 기억 상자 ⑥에서 할아버지가 투표한 선거는 어느 것인가요?","options":[{"t":"5·10 총선거","correct":true},{"t":"이산가족 찾기 방송","mis":"SO5-2-u3-X46"},{"t":"3·1 운동","mis":"SO5-2-u3-X46"},{"t":"정전 협정","mis":"SO5-2-u3-X46"}],"explanation":["남한에서 처음 치렀어요.","국회의원을 뽑았어요.","5·10 총선거예요."],"asset":{"type":"passage","lines":["⑥ 「광복 다음 날, 처음으로 내 이름을 크게 말했다.」 할머니의 쪽지다.","할머니는 다시 나온 한글 신문을 읽으며 기뻐했다.","할아버지는 남한에서 처음 치른 총선거 날 투표소 앞에서 사진을 찍었다."],"title":"솔이네 할머니의 기억 상자 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#7','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C21',1,'mc','auto','6·25 전쟁 때 정부가 옮겨 간 임시 수도는 어디인가요?',ARRAY['SO5-2-u3-X42','SO5-2-u3-X39']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C21","difficulty":1,"kind":"mc","stem":"6·25 전쟁 때 정부가 옮겨 간 임시 수도는 어디인가요?","options":[{"t":"부산","correct":true},{"t":"상하이","mis":"SO5-2-u3-X42"},{"t":"흥남","mis":"SO5-2-u3-X42"},{"t":"평양","mis":"SO5-2-u3-X39"}],"explanation":["남쪽 끝이에요.","피란민이 모였어요.","부산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#8','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C23',1,'mc','auto','할머니가 휴전선 너머 고향에 끝내 가 보지 못한 까닭은 무엇인가요?',ARRAY['SO5-2-u3-X43','SO5-2-u3-X40']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C23","difficulty":1,"kind":"mc","stem":"할머니가 휴전선 너머 고향에 끝내 가 보지 못한 까닭은 무엇인가요?","options":[{"t":"분단이 이어져 남북을 자유롭게 오갈 수 없기 때문에","correct":true},{"t":"고향이 너무 가까워서","mis":"SO5-2-u3-X43"},{"t":"가고 싶지 않아서","mis":"SO5-2-u3-X43"},{"t":"전쟁이 완전히 끝났기 때문에","mis":"SO5-2-u3-X40"}],"explanation":["휴전선이 있어요.","오갈 수 없어요.","분단 때문이에요."],"asset":{"type":"passage","lines":["⑧ 마지막으로 낡은 종이 한 장이 나왔다.","헤어진 동생의 이름과 생김새를 적은 가족 찾기 방송 신청서였다.","할머니는 휴전선 너머 고향에 끝내 가 보지 못했다고 말씀하셨다."],"title":"솔이네 할머니의 기억 상자 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#9','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C3',2,'mc','auto','을사늑약 뒤 황제가 헤이그에 특사를 보낸 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X04','SO5-2-u3-X05']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C3","difficulty":2,"kind":"mc","stem":"을사늑약 뒤 황제가 헤이그에 특사를 보낸 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"늑약이 무효임을 세계에 알리려고","correct":true},{"t":"늑약에 찬성한다고 알리려고","mis":"SO5-2-u3-X04"},{"t":"일본과 새 조약을 맺으려고","mis":"SO5-2-u3-X04"},{"t":"의병을 그만두게 하려고","mis":"SO5-2-u3-X05"}],"explanation":["황제는 반대했어요.","세계에 알리려 했어요.","무효임을 밝히려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#10','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C7',2,'mc','auto','솔이네 기억 상자 ②에서 증조할아버지의 동생이 간 만주의 학교는 무엇을 하던 곳이었나요?',ARRAY['SO5-2-u3-X13','SO5-2-u3-X10']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C7","difficulty":2,"kind":"mc","stem":"솔이네 기억 상자 ②에서 증조할아버지의 동생이 간 만주의 학교는 무엇을 하던 곳이었나요?","options":[{"t":"독립군을 기르던 곳","correct":true},{"t":"일본어를 가르치던 곳","mis":"SO5-2-u3-X13"},{"t":"땅을 조사하던 곳","mis":"SO5-2-u3-X10"},{"t":"신문을 팔던 곳","mis":"SO5-2-u3-X13"}],"explanation":["만주에 있었어요.","신흥 무관 학교예요.","독립군을 길렀어요."],"asset":{"type":"passage","lines":["② 빛바랜 교실 사진 속 선생님은 허리에 칼을 차고 있었다.","증조할아버지는 땅을 신고하지 못해 빼앗기고 남의 땅을 빌려 농사지었다.","증조할아버지의 동생은 집을 떠나 만주의 학교로 갔다."],"title":"솔이네 할머니의 기억 상자 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#11','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C10',2,'mc','auto','임시 정부가 한인 애국단을 만든 때로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X18','SO5-2-u3-X46']::text[],false,'{"seq":11,"concept":"SO5-2-u3-C10","difficulty":2,"kind":"mc","stem":"임시 정부가 한인 애국단을 만든 때로 알맞은 것은 어느 것인가요?","options":[{"t":"일제의 탄압으로 임시 정부의 활동이 힘들어졌을 때","correct":true},{"t":"임시 정부를 처음 세우기 전","mis":"SO5-2-u3-X18"},{"t":"광복을 맞은 다음 날","mis":"SO5-2-u3-X46"},{"t":"6·25 전쟁이 끝난 뒤","mis":"SO5-2-u3-X46"}],"explanation":["활동이 힘들어졌어요.","새 방법을 찾았어요.","한인 애국단을 만들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#12','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C14',2,'mc','auto','봉오동과 청산리에서 일본군과 싸운 사람들은 누구인가요?',ARRAY['SO5-2-u3-X25']::text[],false,'{"seq":12,"concept":"SO5-2-u3-C14","difficulty":2,"kind":"mc","stem":"봉오동과 청산리에서 일본군과 싸운 사람들은 누구인가요?","options":[{"t":"만주의 독립군","correct":true},{"t":"서울의 학생들","mis":"SO5-2-u3-X25"},{"t":"조선어 학회 사람들","mis":"SO5-2-u3-X25"},{"t":"헌병 경찰","mis":"SO5-2-u3-X25"}],"explanation":["만주에서 싸웠어요.","무기를 들었어요.","독립군이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#13','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C16',2,'mc','auto','일제 통치 시기 인공 조미료가 인기를 끈 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X29']::text[],false,'{"seq":13,"concept":"SO5-2-u3-C16","difficulty":2,"kind":"mc","stem":"일제 통치 시기 인공 조미료가 인기를 끈 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"국물 요리가 많은 우리나라에서 맛을 쉽고 똑같이 낼 수 있었기 때문에","correct":true},{"t":"모든 한국인이 냉면을 배달해 먹었기 때문에","mis":"SO5-2-u3-X29"},{"t":"조미료가 전통 장을 대신해 맛이 다양해졌기 때문에","mis":"SO5-2-u3-X29"},{"t":"일제가 조미료를 쓰지 못하게 했기 때문에","mis":"SO5-2-u3-X29"}],"explanation":["국물 요리가 많아요.","맛을 쉽게 냈어요.","그래서 인기였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#14','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C20',2,'mc','auto','5·10 총선거를 남한에서만 치른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X38','SO5-2-u3-X37']::text[],false,'{"seq":14,"concept":"SO5-2-u3-C20","difficulty":2,"kind":"mc","stem":"5·10 총선거를 남한에서만 치른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"통일 정부가 어려워지자 국제 연합이 선거가 가능한 지역에서만 치르게 했기 때문에","correct":true},{"t":"북한 사람들은 선거를 원하지 않았기 때문에","mis":"SO5-2-u3-X38"},{"t":"일제가 남한만 허락했기 때문에","mis":"SO5-2-u3-X37"},{"t":"처음부터 남북이 다른 나라였기 때문에","mis":"SO5-2-u3-X37"}],"explanation":["통일 정부가 어려웠어요.","국제 연합이 정했어요.","가능한 곳에서 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#15','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C21',2,'mc','auto','6·25 전쟁에서 중국군이 들어온 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X39','SO5-2-u3-X40','SO5-2-u3-X46']::text[],false,'{"seq":15,"concept":"SO5-2-u3-C21","difficulty":2,"kind":"mc","stem":"6·25 전쟁에서 중국군이 들어온 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"북한을 도우려고","correct":true},{"t":"남한을 도우려고","mis":"SO5-2-u3-X39"},{"t":"정전 협정을 맺으려고","mis":"SO5-2-u3-X40"},{"t":"일본군을 막으려고","mis":"SO5-2-u3-X46"}],"explanation":["국군이 압록강까지 갔어요.","중국군이 들어왔어요.","북한을 도왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#16','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C24',2,'mc','auto','솔이네 기억 상자 ④의 광주 신문과 가장 관계 깊은 기념일은 어느 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":16,"concept":"SO5-2-u3-C24","difficulty":2,"kind":"mc","stem":"솔이네 기억 상자 ④의 광주 신문과 가장 관계 깊은 기념일은 어느 것인가요?","options":[{"t":"학생 독립운동 기념일","correct":true},{"t":"삼일절","mis":"SO5-2-u3-X45"},{"t":"광복절","mis":"SO5-2-u3-X45"},{"t":"제헌절","mis":"SO5-2-u3-X45"}],"explanation":["광주의 학생이에요.","차별에 맞섰어요.","11월 3일 기념일이에요."],"asset":{"type":"passage","lines":["④ 「우리가 만든 것 우리가 쓰자」라고 적힌 광고지가 있었다.","방학이면 할머니의 오빠는 농촌에 가서 아이들에게 한글을 가르쳤다.","광주의 학생들이 차별에 맞서 일어났다는 신문도 남아 있었다."],"title":"솔이네 할머니의 기억 상자 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#17','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C12',3,'error','auto','솔이네 기억 상자 ④를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X22','SO5-2-u3-X21']::text[],false,'{"seq":17,"concept":"SO5-2-u3-C12","difficulty":3,"kind":"error","stem":"솔이네 기억 상자 ④를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이든 — 「광고지나 한글 가르치기는 독립과 아무 관계가 없어.」","correct":true,"mis_target":"SO5-2-u3-X22"},{"t":"새봄 — 「우리 물건을 쓰면 경제적으로 독립하는 데 도움이 돼.」","mis":"SO5-2-u3-X21"},{"t":"찬희 — 「한글을 가르쳐 민족의 힘을 길렀어.」","mis":"SO5-2-u3-X21"}],"explanation":["경제로 힘을 길렀어요.","글로도 힘을 길렀어요.","이든의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["④ 「우리가 만든 것 우리가 쓰자」라고 적힌 광고지가 있었다.","방학이면 할머니의 오빠는 농촌에 가서 아이들에게 한글을 가르쳤다.","광주의 학생들이 차별에 맞서 일어났다는 신문도 남아 있었다."],"title":"솔이네 할머니의 기억 상자 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#18','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C11',3,'error','auto','솔이네 기억 상자 ⑤의 쌀가마를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X20','SO5-2-u3-X27']::text[],false,'{"seq":18,"concept":"SO5-2-u3-C11","difficulty":3,"kind":"error","stem":"솔이네 기억 상자 ⑤의 쌀가마를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지율 — 「쌀이 많이 쌓였으니 마을 농민들은 배불리 먹었을 거야.」","correct":true,"mis_target":"SO5-2-u3-X20"},{"t":"라온 — 「쌀이 일본으로 실려 가 농민은 오히려 배고팠을 거야.」","mis":"SO5-2-u3-X20"},{"t":"예빈 — 「철도는 쌀을 실어 나르는 데 쓰였어.」","mis":"SO5-2-u3-X27"}],"explanation":["쌀은 실려 갔어요.","농민은 먹지 못했어요.","지율의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["⑤ 마을 역에 쌓인 쌀가마가 기차로 실려 갔다는 메모가 있었다.","어린 할머니는 학교에서 일본식 이름을 써야 했다.","집의 놋그릇과 숟가락까지 거두어 가 나무 숟가락을 썼다고 한다."],"title":"솔이네 할머니의 기억 상자 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#19','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C13',3,'error','auto','학생들의 독립운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X23','SO5-2-u3-X24']::text[],false,'{"seq":19,"concept":"SO5-2-u3-C13","difficulty":3,"kind":"error","stem":"학생들의 독립운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소담 — 「6·10 만세 운동은 광주에서 학생끼리 다툰 일로 시작됐어.」","correct":true,"mis_target":"SO5-2-u3-X23"},{"t":"정빈 — 「6·10 만세 운동은 마지막 황제의 장례식 날 일어났어.」","mis":"SO5-2-u3-X23"},{"t":"유주 — 「광주의 일은 학교 속 차별이 쌓여 있다가 터졌어.」","mis":"SO5-2-u3-X24"}],"explanation":["6·10은 장례식 날이에요.","광주는 다른 운동이에요.","소담의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#20','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C19',3,'error','auto','솔이네 기억 상자 ⑥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X35']::text[],false,'{"seq":20,"concept":"SO5-2-u3-C19","difficulty":3,"kind":"error","stem":"솔이네 기억 상자 ⑥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하진 — 「광복 뒤에도 학교에서는 일본어로만 수업했어.」","correct":true,"mis_target":"SO5-2-u3-X35"},{"t":"윤슬 — 「다시 나온 한글 신문을 읽을 수 있었어.」","mis":"SO5-2-u3-X35"},{"t":"시온 — 「자기 이름을 다시 쓸 수 있게 되었어.」","mis":"SO5-2-u3-X35"}],"explanation":["우리말로 수업했어요.","한글 신문이 나왔어요.","하진의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["⑥ 「광복 다음 날, 처음으로 내 이름을 크게 말했다.」 할머니의 쪽지다.","할머니는 다시 나온 한글 신문을 읽으며 기뻐했다.","할아버지는 남한에서 처음 치른 총선거 날 투표소 앞에서 사진을 찍었다."],"title":"솔이네 할머니의 기억 상자 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#21','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C22',3,'error','auto','솔이네 기억 상자 ⑦을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X41']::text[],false,'{"seq":21,"concept":"SO5-2-u3-C22","difficulty":3,"kind":"error","stem":"솔이네 기억 상자 ⑦을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여름 — 「피란민들은 물이 넉넉해서 줄을 설 필요가 없었어.」","correct":true,"mis_target":"SO5-2-u3-X41"},{"t":"가람 — 「물동이를 들고 수도꼭지 앞에 줄을 섰어.」","mis":"SO5-2-u3-X41"},{"t":"담우 — 「천막 학교에서 공부를 이어 갔어.」","mis":"SO5-2-u3-X41"}],"explanation":["물이 부족했어요.","줄을 섰어요.","여름의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["⑦ 피란 가서 부산 산비탈에 지은 판잣집 사진이 있었다.","물동이를 들고 수도꼭지 앞에 줄을 서던 이야기가 적혀 있었다.","할머니는 천막 학교에서 공부했고, 밀가루로 만든 국수를 먹었다고 했다."],"title":"솔이네 할머니의 기억 상자 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#22','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C24',3,'error','auto','솔이네 기억 상자로 기념일 옷을 계획했어요. 알맞지 않은 계획은 누구의 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":22,"concept":"SO5-2-u3-C24","difficulty":3,"kind":"error","stem":"솔이네 기억 상자로 기념일 옷을 계획했어요. 알맞지 않은 계획은 누구의 것인가요?","options":[{"t":"서하 — 「⑦의 판잣집을 광복절 옷에 그리고 「나라를 되찾았다」라고 쓸래.」","correct":true,"mis_target":"SO5-2-u3-X45"},{"t":"지온 — 「③의 태극기를 삼일절 옷에 그릴래.」","mis":"SO5-2-u3-X45"},{"t":"민아 — 「④의 광주 신문을 학생 독립운동 기념일 옷에 넣을래.」","mis":"SO5-2-u3-X45"}],"explanation":["판잣집은 6·25 전쟁 때예요.","광복절과 맞지 않아요.","서하의 계획이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#23','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C15',4,'mc','auto','솔이네 기억 상자 ⑤처럼 철도·도시 같은 근대 문물을 일제 통치 시기에 볼 때 가장 알맞은 생각은 어느 것인가요?',ARRAY['SO5-2-u3-X28','SO5-2-u3-X27']::text[],false,'{"seq":23,"concept":"SO5-2-u3-C15","difficulty":4,"kind":"mc","stem":"솔이네 기억 상자 ⑤처럼 철도·도시 같은 근대 문물을 일제 통치 시기에 볼 때 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"근대 문물이 들어왔지만 식민 통치 아래에서 주로 일제를 위해 쓰여 우리 민족은 혜택을 제대로 누리지 못했다","correct":true},{"t":"근대 문물 덕분에 모든 한국인이 넉넉해졌다","mis":"SO5-2-u3-X28"},{"t":"근대 문물은 하나도 들어오지 않았다","mis":"SO5-2-u3-X27"},{"t":"철도는 독립군만을 위해 놓였다","mis":"SO5-2-u3-X27"}],"explanation":["철도와 도시가 생겼어요.","누구를 위한 것인지 봐요.","혜택을 누리지 못했어요."],"asset":{"type":"passage","lines":["⑤ 마을 역에 쌓인 쌀가마가 기차로 실려 갔다는 메모가 있었다.","어린 할머니는 학교에서 일본식 이름을 써야 했다.","집의 놋그릇과 숟가락까지 거두어 가 나무 숟가락을 썼다고 한다."],"title":"솔이네 할머니의 기억 상자 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#24','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C6',4,'essay','teacher','솔이네 기억 상자 ②와 ⑤를 보고 일제의 식민 통치가 솔이네 집안의 생활에 준 영향을 땅·쌀·이름·물건 가운데 세 가지를 골라 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-2-u3-C6","difficulty":4,"kind":"essay","stem":"솔이네 기억 상자 ②와 ⑤를 보고 일제의 식민 통치가 솔이네 집안의 생활에 준 영향을 땅·쌀·이름·물건 가운데 세 가지를 골라 쓰세요.","answer_guide":{"answer":"예: 땅 — 증조할아버지는 토지 조사 사업 때 땅을 빼앗겨 남의 땅을 빌려 농사지었다. 쌀 — 마을 역에 쌓인 쌀이 기차로 일본으로 실려 가 농민들은 배를 곯았다. 이름 — 어린 할머니는 학교에서 일본식 이름을 써야 했다.","scoring_points":["세 가지를 골랐는가","기억 상자를 근거로 썼는가","생활이 어려워진 모습을 썼는가"]},"explanation":["땅을 빼앗겼어요.","쌀이 실려 갔어요.","이름도 바꾸게 했어요."],"asset":{"type":"passage","lines":["⑤ 마을 역에 쌓인 쌀가마가 기차로 실려 갔다는 메모가 있었다.","어린 할머니는 학교에서 일본식 이름을 써야 했다.","집의 놋그릇과 숟가락까지 거두어 가 나무 숟가락을 썼다고 한다."],"title":"솔이네 할머니의 기억 상자 ⑤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_b#25','soc',5,2,'u3','','g5_2_soc_u3_review_b','unit_review','SO5-2-u3-C23',4,'essay','teacher','솔이네 기억 상자 ⑧을 보고 6·25 전쟁이 오늘날까지 미치는 영향을 두 가지 쓰고, 할머니께 드리고 싶은 말을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-2-u3-C23","difficulty":4,"kind":"essay","stem":"솔이네 기억 상자 ⑧을 보고 6·25 전쟁이 오늘날까지 미치는 영향을 두 가지 쓰고, 할머니께 드리고 싶은 말을 쓰세요.","answer_guide":{"answer":"예: 전쟁으로 헤어진 이산가족이 휴전선 때문에 오래도록 만나지 못하고 있다. 남북이 서로를 적으로 여기는 감정이 깊어져 분단이 이어지고 있다. 할머니, 동생분을 그리워하신 마음을 저도 기억할게요. 다시는 이런 이별이 없도록 평화를 소중히 여기겠습니다.","scoring_points":["오늘날까지의 영향 두 가지를 썼는가","기억 상자를 근거로 썼는가","할머니의 아픔을 헤아린 말을 썼는가"]},"explanation":["이산가족이 있어요.","분단이 이어져요.","마음을 담아 써요."],"asset":{"type":"passage","lines":["⑧ 마지막으로 낡은 종이 한 장이 나왔다.","헤어진 동생의 이름과 생김새를 적은 가족 찾기 방송 신청서였다.","할머니는 휴전선 너머 고향에 끝내 가 보지 못했다고 말씀하셨다."],"title":"솔이네 할머니의 기억 상자 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#1','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C2',1,'ox','auto','을사늑약 소식에 상인은 가게 문을 닫고 학생은 등교를 거부했어요.',ARRAY['SO5-2-u3-X01']::text[],false,'{"seq":1,"concept":"SO5-2-u3-C2","difficulty":1,"kind":"ox","stem":"을사늑약 소식에 상인은 가게 문을 닫고 학생은 등교를 거부했어요.","answer":"O","reason_options":[{"t":"억지로 맺은 조약에 반대하는 뜻을 보였기 때문에","correct":true},{"t":"조약을 축하하려 했기 때문에","mis":"SO5-2-u3-X01"}],"mis":"SO5-2-u3-X01","explanation":["늑약에 반대했어요.","가게를 닫았어요.","등교를 거부했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#2','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C5',1,'sa','auto','일제가 경찰 일을 맡겨 한국인을 감시하게 한 군인을 무엇이라 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-2-u3-C5","difficulty":1,"kind":"sa","stem":"일제가 경찰 일을 맡겨 한국인을 감시하게 한 군인을 무엇이라 하나요? 두 글자로 쓰세요.","answer":["헌병"],"explanation":["군인이에요.","경찰 일을 했어요.","헌병이에요."],"mis":"SO5-2-u3-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#3','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C8',1,'sa','auto','3·1 운동 때 민족 대표들이 발표한 글은 무엇인가요? (독립 ○○○)','{}'::text[],false,'{"seq":3,"concept":"SO5-2-u3-C8","difficulty":1,"kind":"sa","stem":"3·1 운동 때 민족 대표들이 발표한 글은 무엇인가요? (독립 ○○○)","answer":["독립 선언서","독립선언서","선언서"],"explanation":["독립을 알렸어요.","여러 사람이 읽었어요.","독립 선언서예요."],"mis":"SO5-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#4','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C13',1,'sa','auto','마지막 황제의 장례식 날 학생들이 서울에서 일으킨 만세 운동은 무엇인가요? (○·○○ 만세 운동)','{}'::text[],false,'{"seq":4,"concept":"SO5-2-u3-C13","difficulty":1,"kind":"sa","stem":"마지막 황제의 장례식 날 학생들이 서울에서 일으킨 만세 운동은 무엇인가요? (○·○○ 만세 운동)","answer":["6·10 만세 운동","6·10만세운동","6·10"],"explanation":["장례식 날이에요.","학생들이 외쳤어요.","6·10 만세 운동이에요."],"mis":"SO5-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#5','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C17',1,'ox','auto','일제는 침략 전쟁에 쓰려고 놋그릇과 숟가락까지 거두어 갔어요.',ARRAY['SO5-2-u3-X31']::text[],false,'{"seq":5,"concept":"SO5-2-u3-C17","difficulty":1,"kind":"ox","stem":"일제는 침략 전쟁에 쓰려고 놋그릇과 숟가락까지 거두어 갔어요.","answer":"O","reason_options":[{"t":"쇠붙이를 녹여 무기를 만들려 했기 때문에","correct":true},{"t":"집집마다 새 그릇을 나누어 주려 했기 때문에","mis":"SO5-2-u3-X31"}],"mis":"SO5-2-u3-X31","explanation":["생활 물건이에요.","쇠붙이를 모았어요.","무기를 만들려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#6','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C19',1,'ox','auto','광복 뒤 일제가 없앴던 한글 신문과 잡지가 다시 나왔어요.',ARRAY['SO5-2-u3-X35']::text[],false,'{"seq":6,"concept":"SO5-2-u3-C19","difficulty":1,"kind":"ox","stem":"광복 뒤 일제가 없앴던 한글 신문과 잡지가 다시 나왔어요.","answer":"O","reason_options":[{"t":"나라를 되찾아 우리글을 자유롭게 쓰게 되었기 때문에","correct":true},{"t":"광복 뒤 한글 쓰기를 금지했기 때문에","mis":"SO5-2-u3-X35"}],"mis":"SO5-2-u3-X35","explanation":["나라를 되찾았어요.","우리글을 썼어요.","한글 신문이 다시 나왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#7','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C22',1,'sa','auto','솔이네 기억 상자 ⑦에서 할머니가 먹은, 피란민이 밀가루로 만든 국수는 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO5-2-u3-C22","difficulty":1,"kind":"sa","stem":"솔이네 기억 상자 ⑦에서 할머니가 먹은, 피란민이 밀가루로 만든 국수는 무엇인가요? 두 글자로 쓰세요.","answer":["밀면"],"explanation":["밀가루로 만들었어요.","부산에서 생겼어요.","밀면이에요."],"mis":"SO5-2-u3-X41"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#8','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C23',1,'ox','auto','6·25 전쟁 때 민간인도 많이 목숨을 잃거나 다쳤어요.',ARRAY['SO5-2-u3-X43']::text[],false,'{"seq":8,"concept":"SO5-2-u3-C23","difficulty":1,"kind":"ox","stem":"6·25 전쟁 때 민간인도 많이 목숨을 잃거나 다쳤어요.","answer":"O","reason_options":[{"t":"전쟁이 마을과 도시까지 덮쳤기 때문에","correct":true},{"t":"전쟁은 군인끼리만 싸웠기 때문에","mis":"SO5-2-u3-X43"}],"mis":"SO5-2-u3-X43","explanation":["마을까지 번졌어요.","민간인도 피해를 입었어요.","피해가 컸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#9','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C4',2,'error','auto','솔이네 기억 상자 ①의 옆집 형 같은 의병을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X06','SO5-2-u3-X07']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C4","difficulty":2,"kind":"error","stem":"솔이네 기억 상자 ①의 옆집 형 같은 의병을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다빈 — 「의병은 훈련받은 군인만 될 수 있었어.」","correct":true,"mis_target":"SO5-2-u3-X06"},{"t":"은재 — 「농민과 여성도 의병을 도왔어.」","mis":"SO5-2-u3-X06"},{"t":"한결 — 「뒤에는 만주와 연해주에서도 싸웠어.」","mis":"SO5-2-u3-X07"}],"explanation":["여러 사람이 나섰어요.","여성도 함께했어요.","다빈의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#10','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C7',2,'error','auto','만주와 미국에서 이어진 독립운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X13']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C7","difficulty":2,"kind":"error","stem":"만주와 미국에서 이어진 독립운동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"정우 — 「흥사단은 만주에서 독립군을 기른 학교야.」","correct":true,"mis_target":"SO5-2-u3-X13"},{"t":"서윤 — 「신흥 무관 학교는 만주에 있었어.」","mis":"SO5-2-u3-X13"},{"t":"하민 — 「흥사단은 미국에서 실력을 키웠어.」","mis":"SO5-2-u3-X13"}],"explanation":["흥사단은 미국이에요.","만주 학교는 신흥 무관 학교예요.","정우의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#11','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C9',2,'error','auto','임시 정부를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X16','SO5-2-u3-X17']::text[],false,'{"seq":11,"concept":"SO5-2-u3-C9","difficulty":2,"kind":"error","stem":"임시 정부를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수빈 — 「임시 정부는 일제가 허락해서 서울 한가운데 세웠어.」","correct":true,"mis_target":"SO5-2-u3-X16"},{"t":"도현 — 「비밀 연락망으로 나라 안 독립운동을 이끌었어.」","mis":"SO5-2-u3-X17"},{"t":"채아 — 「외교 활동으로 독립의 뜻을 알렸어.」","mis":"SO5-2-u3-X17"}],"explanation":["상하이에 세웠어요.","탄압을 피했어요.","수빈의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#12','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C11',2,'error','auto','3·1 운동 뒤 일제의 통치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X19','SO5-2-u3-X20']::text[],false,'{"seq":12,"concept":"SO5-2-u3-C11","difficulty":2,"kind":"error","stem":"3·1 운동 뒤 일제의 통치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤호 — 「일제가 부드러워져서 우리 민족은 살기 편해졌어.」","correct":true,"mis_target":"SO5-2-u3-X19"},{"t":"미르 — 「친일 세력을 늘려 민족을 나누려 했어.」","mis":"SO5-2-u3-X19"},{"t":"가온 — 「쌀을 더 가져가 생활이 어려워졌어.」","mis":"SO5-2-u3-X20"}],"explanation":["방법만 바꿨어요.","쌀을 더 가져갔어요.","윤호의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#13','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C17',2,'error','auto','일제가 침략 전쟁을 일으킨 뒤를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X30','SO5-2-u3-X31']::text[],false,'{"seq":13,"concept":"SO5-2-u3-C17","difficulty":2,"kind":"error","stem":"일제가 침략 전쟁을 일으킨 뒤를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"규리 — 「학교에서 우리말과 우리 역사를 더 많이 가르쳤어.」","correct":true,"mis_target":"SO5-2-u3-X30"},{"t":"태하 — 「일본식 이름을 쓰게 했어.」","mis":"SO5-2-u3-X30"},{"t":"나래 — 「사람과 물자를 강제로 동원했어.」","mis":"SO5-2-u3-X31"}],"explanation":["우리말을 못 배웠어요.","이름도 바꾸게 했어요.","규리의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#14','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C20',2,'error','auto','5·10 총선거를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X38']::text[],false,'{"seq":14,"concept":"SO5-2-u3-C20","difficulty":2,"kind":"error","stem":"5·10 총선거를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「5·10 총선거에는 남자만 투표할 수 있었어.」","correct":true,"mis_target":"SO5-2-u3-X38"},{"t":"선우 — 「우리 역사에서 처음 치른 민주 선거야.」","mis":"SO5-2-u3-X38"},{"t":"로운 — 「이 선거로 국회의원을 뽑았어.」","mis":"SO5-2-u3-X38"}],"explanation":["여성도 투표했어요.","첫 민주 선거예요.","지아의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#15','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C21',2,'error','auto','6·25 전쟁의 차례를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-2-u3-X39']::text[],false,'{"seq":15,"concept":"SO5-2-u3-C21","difficulty":2,"kind":"error","stem":"6·25 전쟁의 차례를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하늘 — 「인천 상륙 작전 다음에 북한군이 처음 쳐들어왔어.」","correct":true,"mis_target":"SO5-2-u3-X39"},{"t":"보람 — 「북한군이 쳐들어와 낙동강까지 밀렸어.」","mis":"SO5-2-u3-X39"},{"t":"주하 — 「중국군이 들어와 다시 서울을 빼앗겼어.」","mis":"SO5-2-u3-X39"}],"explanation":["남침이 먼저예요.","그다음 인천 상륙이에요.","하늘의 차례가 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#16','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C24',2,'mc','auto','솔이네 기억 상자 ⑥의 할아버지가 투표한 선거로 뽑힌 국회가 헌법을 알린 날을 기념하는 날은 어느 것인가요?',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":16,"concept":"SO5-2-u3-C24","difficulty":2,"kind":"mc","stem":"솔이네 기억 상자 ⑥의 할아버지가 투표한 선거로 뽑힌 국회가 헌법을 알린 날을 기념하는 날은 어느 것인가요?","options":[{"t":"제헌절","correct":true},{"t":"삼일절","mis":"SO5-2-u3-X45"},{"t":"광복절","mis":"SO5-2-u3-X45"},{"t":"학생 독립운동 기념일","mis":"SO5-2-u3-X45"}],"explanation":["총선거로 국회를 뽑았어요.","헌법을 만들었어요.","제헌절이에요."],"asset":{"type":"passage","lines":["⑥ 「광복 다음 날, 처음으로 내 이름을 크게 말했다.」 할머니의 쪽지다.","할머니는 다시 나온 한글 신문을 읽으며 기뻐했다.","할아버지는 남한에서 처음 치른 총선거 날 투표소 앞에서 사진을 찍었다."],"title":"솔이네 할머니의 기억 상자 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#17','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C4',3,'mc','auto','솔이네 기억 상자 ①의 옆집 형과 ②의 증조할아버지 동생이 한 일을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X12','SO5-2-u3-X01']::text[],false,'{"seq":17,"concept":"SO5-2-u3-C4","difficulty":3,"kind":"mc","stem":"솔이네 기억 상자 ①의 옆집 형과 ②의 증조할아버지 동생이 한 일을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라 안 싸움이 막히자 나라 밖으로 옮겨 가 힘을 기르는 저항으로 이어졌다","correct":true},{"t":"두 사람 모두 싸움을 그만두었다","mis":"SO5-2-u3-X12"},{"t":"두 사람은 일제를 도왔다","mis":"SO5-2-u3-X01"},{"t":"나라 밖에서는 독립운동이 없었다","mis":"SO5-2-u3-X12"}],"explanation":["①은 의병이에요.","②는 만주의 학교예요.","저항이 나라 밖으로 이어졌어요."],"asset":{"type":"passage","lines":["② 빛바랜 교실 사진 속 선생님은 허리에 칼을 차고 있었다.","증조할아버지는 땅을 신고하지 못해 빼앗기고 남의 땅을 빌려 농사지었다.","증조할아버지의 동생은 집을 떠나 만주의 학교로 갔다."],"title":"솔이네 할머니의 기억 상자 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#18','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C11',3,'mc','auto','토지 조사 사업과 3·1 운동 뒤 쌀을 더 가져간 일의 공통점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X10','SO5-2-u3-X17','SO5-2-u3-X46']::text[],false,'{"seq":18,"concept":"SO5-2-u3-C11","difficulty":3,"kind":"mc","stem":"토지 조사 사업과 3·1 운동 뒤 쌀을 더 가져간 일의 공통점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"겉으로 내세운 까닭과 달리 우리 농민의 것을 빼앗아 갔다","correct":true},{"t":"두 가지 모두 농민을 도우려는 일이었다","mis":"SO5-2-u3-X10"},{"t":"두 가지 모두 임시 정부가 한 일이다","mis":"SO5-2-u3-X17"},{"t":"두 가지 모두 광복 뒤의 일이다","mis":"SO5-2-u3-X46"}],"explanation":["땅을 빼앗았어요.","쌀도 가져갔어요.","모두 빼앗는 일이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#19','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C8',3,'mc','auto','3·1 운동 때 서울의 학생들이 고향으로 내려가 장날 만세를 이끈 것으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X14']::text[],false,'{"seq":19,"concept":"SO5-2-u3-C8","difficulty":3,"kind":"mc","stem":"3·1 운동 때 서울의 학생들이 고향으로 내려가 장날 만세를 이끈 것으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학생들이 소식을 전하며 만세가 전국으로 퍼지는 데 큰 힘이 되었다","correct":true},{"t":"학생들은 만세에 함께하지 않았다","mis":"SO5-2-u3-X14"},{"t":"만세는 서울에서만 일어났다","mis":"SO5-2-u3-X14"},{"t":"학생들이 일제의 진압을 도왔다","mis":"SO5-2-u3-X14"}],"explanation":["고향으로 내려갔어요.","장날을 골랐어요.","전국으로 퍼졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#20','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C17',3,'mc','auto','일제가 이름과 말을 바꾸게 한 일이 우리 민족에게 준 상처로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X30']::text[],false,'{"seq":20,"concept":"SO5-2-u3-C17","difficulty":3,"kind":"mc","stem":"일제가 이름과 말을 바꾸게 한 일이 우리 민족에게 준 상처로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자기를 나타내는 이름과 말까지 빼앗겨 민족의 정신이 흔들릴 위기를 겪었다","correct":true},{"t":"새 이름이 생겨 모두 기뻐했다","mis":"SO5-2-u3-X30"},{"t":"이름은 민족정신과 관계없다","mis":"SO5-2-u3-X30"},{"t":"우리말이 더 널리 퍼졌다","mis":"SO5-2-u3-X30"}],"explanation":["이름은 나를 나타내요.","말은 민족을 이어요.","그것을 빼앗겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#21','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C22',3,'mc','auto','전쟁 중 흥남 부두의 배가 짐을 버리고 피란민을 태운 일과 천막 학교의 공통점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X39','SO5-2-u3-X41','SO5-2-u3-X40']::text[],false,'{"seq":21,"concept":"SO5-2-u3-C22","difficulty":3,"kind":"mc","stem":"전쟁 중 흥남 부두의 배가 짐을 버리고 피란민을 태운 일과 천막 학교의 공통점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어려운 전쟁 속에서도 사람과 배움을 지키려 했다","correct":true},{"t":"둘 다 전쟁을 시작한 일이다","mis":"SO5-2-u3-X39"},{"t":"둘 다 피란민과 관계없다","mis":"SO5-2-u3-X41"},{"t":"둘 다 정전 협정의 내용이다","mis":"SO5-2-u3-X40"}],"explanation":["배는 사람을 지켰어요.","학교는 배움을 지켰어요.","둘 다 지키려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#22','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C21',3,'mc','auto','6·25 전쟁의 장면을 차례대로 바르게 놓은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X39']::text[],false,'{"seq":22,"concept":"SO5-2-u3-C21","difficulty":3,"kind":"mc","stem":"6·25 전쟁의 장면을 차례대로 바르게 놓은 것은 어느 것인가요?","options":[{"t":"북한군의 남침 → 인천 상륙 작전 → 중국군 참전 → 정전 협정","correct":true},{"t":"인천 상륙 작전 → 북한군의 남침 → 정전 협정 → 중국군 참전","mis":"SO5-2-u3-X39"},{"t":"중국군 참전 → 북한군의 남침 → 인천 상륙 작전 → 정전 협정","mis":"SO5-2-u3-X39"},{"t":"북한군의 남침 → 정전 협정 → 인천 상륙 작전 → 중국군 참전","mis":"SO5-2-u3-X39"}],"explanation":["남침이 먼저예요.","인천 다음 중국군이에요.","정전이 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#23','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C23',4,'mc','auto','솔이네 기억 상자 ⑥~⑧을 이어 가장 알맞게 정리한 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46','SO5-2-u3-X43']::text[],false,'{"seq":23,"concept":"SO5-2-u3-C23","difficulty":4,"kind":"mc","stem":"솔이네 기억 상자 ⑥~⑧을 이어 가장 알맞게 정리한 것은 어느 것인가요?","options":[{"t":"광복으로 되찾은 생활을 누리던 중 6·25 전쟁이 일어나 피란과 이별을 겪고 그 아픔이 오늘까지 이어진다","correct":true},{"t":"광복 뒤 전쟁 없이 평화롭게 오늘에 이르렀다","mis":"SO5-2-u3-X46"},{"t":"6·25 전쟁으로 나라를 되찾았다","mis":"SO5-2-u3-X46"},{"t":"전쟁의 아픔은 정전과 함께 모두 사라졌다","mis":"SO5-2-u3-X43"}],"explanation":["⑥은 광복이에요.","⑦은 전쟁 속 생활이에요.","⑧은 오늘까지 이어진 아픔이에요."],"asset":{"type":"passage","lines":["⑦ 피란 가서 부산 산비탈에 지은 판잣집 사진이 있었다.","물동이를 들고 수도꼭지 앞에 줄을 서던 이야기가 적혀 있었다.","할머니는 천막 학교에서 공부했고, 밀가루로 만든 국수를 먹었다고 했다."],"title":"솔이네 할머니의 기억 상자 ⑦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#24','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C12',4,'essay','teacher','솔이네 기억 상자 ④를 보고 3·1 운동 뒤 나라 안에서 일어난 민족 운동 세 가지를 쓰고, 이 운동들이 독립에 도움이 된다고 본 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-2-u3-C12","difficulty":4,"kind":"essay","stem":"솔이네 기억 상자 ④를 보고 3·1 운동 뒤 나라 안에서 일어난 민족 운동 세 가지를 쓰고, 이 운동들이 독립에 도움이 된다고 본 까닭을 쓰세요.","answer_guide":{"answer":"예: 「우리가 만든 것 우리가 쓰자」는 물산 장려 운동, 할머니의 오빠가 농촌에서 한글을 가르친 농촌 계몽 운동, 광주의 학생들이 차별에 맞선 광주 학생 항일 운동이 있었다. 우리 경제와 말과 글을 지키고 차별에 맞서야 민족의 힘이 길러져 독립을 이룰 수 있다고 보았다.","scoring_points":["운동 세 가지를 썼는가","기억 상자를 근거로 썼는가","독립에 도움이 된다고 본 까닭을 썼는가"]},"explanation":["물산 장려 운동이에요.","농촌 계몽과 학생 운동이에요.","민족의 힘을 길렀어요."],"asset":{"type":"passage","lines":["④ 「우리가 만든 것 우리가 쓰자」라고 적힌 광고지가 있었다.","방학이면 할머니의 오빠는 농촌에 가서 아이들에게 한글을 가르쳤다.","광주의 학생들이 차별에 맞서 일어났다는 신문도 남아 있었다."],"title":"솔이네 할머니의 기억 상자 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_c#25','soc',5,2,'u3','','g5_2_soc_u3_review_c','unit_review','SO5-2-u3-C24',4,'essay','teacher','솔이네 기억 상자 ①~⑧ 가운데 하나를 골라 그와 관계있는 기념일을 쓰고, 그 기념일을 알리는 옷의 그림과 문구를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-2-u3-C24","difficulty":4,"kind":"essay","stem":"솔이네 기억 상자 ①~⑧ 가운데 하나를 골라 그와 관계있는 기념일을 쓰고, 그 기념일을 알리는 옷의 그림과 문구를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: ⑥을 골랐다. 관계있는 기념일은 광복절이다. 옷에는 태극기를 흔드는 사람들과 이름표를 단 아이를 그리고, 「되찾은 나라, 되찾은 내 이름」이라고 쓰겠다. 광복으로 나라와 함께 빼앗겼던 이름까지 되찾았다는 뜻을 담고 싶기 때문이다.","scoring_points":["꼭지 하나와 관계있는 기념일을 바르게 짝지었는가","그림과 문구를 썼는가","사실에 맞는 까닭을 썼는가"]},"explanation":["하나를 골라요.","기념일을 짝지어요.","그림과 문구를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#1','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C4',1,'mc','auto','솔이네 기억 상자 ①에서 옆집 형이 해산된 군인들과 함께 한 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X09','SO5-2-u3-X05','SO5-2-u3-X08']::text[],false,'{"seq":1,"concept":"SO5-2-u3-C4","difficulty":1,"kind":"mc","stem":"솔이네 기억 상자 ①에서 옆집 형이 해산된 군인들과 함께 한 일로 알맞은 것은 어느 것인가요?","options":[{"t":"의병이 되어 일제와 싸웠다","correct":true},{"t":"헌병이 되어 감시했다","mis":"SO5-2-u3-X09"},{"t":"특사가 되어 헤이그에 갔다","mis":"SO5-2-u3-X05"},{"t":"조선 총독부에서 일했다","mis":"SO5-2-u3-X08"}],"explanation":["산으로 들어갔어요.","해산된 군인과 함께했어요.","의병이에요."],"asset":{"type":"passage","lines":["① 상자 맨 아래에 증조할아버지가 젊을 때 쓴 일기가 있었다.","「억지로 조약을 맺었다는 소식에 시장 가게들이 문을 닫았다.」","「옆집 형은 해산된 군인들과 함께 산으로 들어갔다.」"],"title":"솔이네 할머니의 기억 상자 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#2','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C5',1,'ox','auto','조선 총독부는 우리 민족이 스스로 세운 정부예요.',ARRAY['SO5-2-u3-X08']::text[],false,'{"seq":2,"concept":"SO5-2-u3-C5","difficulty":1,"kind":"ox","stem":"조선 총독부는 우리 민족이 스스로 세운 정부예요.","answer":"X","reason_options":[{"t":"일제가 나라를 빼앗은 뒤 다스리려고 세운 기관이기 때문에","correct":true},{"t":"대한 제국이 세운 학교이기 때문에","mis":"SO5-2-u3-X08"}],"mis":"SO5-2-u3-X08","explanation":["일제가 세웠어요.","다스리는 기관이에요.","우리 정부가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#3','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C8',1,'ox','auto','3·1 운동의 만세 시위는 전국으로 퍼졌어요.',ARRAY['SO5-2-u3-X14']::text[],false,'{"seq":3,"concept":"SO5-2-u3-C8","difficulty":1,"kind":"ox","stem":"3·1 운동의 만세 시위는 전국으로 퍼졌어요.","answer":"O","reason_options":[{"t":"서울에서 시작해 장터와 마을까지 석 달 넘게 이어졌기 때문에","correct":true},{"t":"서울 한곳에서만 하루 하고 끝났기 때문에","mis":"SO5-2-u3-X14"}],"mis":"SO5-2-u3-X14","explanation":["서울에서 시작했어요.","전국으로 퍼졌어요.","석 달 넘게 이어졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#4','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C13',1,'ox','auto','광주 학생 항일 운동은 학생들이 차별에 맞서 일으켜 전국으로 퍼졌어요.',ARRAY['SO5-2-u3-X24']::text[],false,'{"seq":4,"concept":"SO5-2-u3-C13","difficulty":1,"kind":"ox","stem":"광주 학생 항일 운동은 학생들이 차별에 맞서 일으켜 전국으로 퍼졌어요.","answer":"O","reason_options":[{"t":"한국 학생만 붙잡은 일에 쌓인 차별이 더해져 일어났기 때문에","correct":true},{"t":"학생들이 일본 경찰을 도왔기 때문에","mis":"SO5-2-u3-X24"}],"mis":"SO5-2-u3-X24","explanation":["한국 학생만 붙잡혔어요.","차별에 맞섰어요.","전국으로 퍼졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#5','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C17',1,'sa','auto','일제가 우리 민족에게 억지로 절을 하게 한 일본의 사당은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO5-2-u3-C17","difficulty":1,"kind":"sa","stem":"일제가 우리 민족에게 억지로 절을 하게 한 일본의 사당은 무엇인가요? 두 글자로 쓰세요.","answer":["신사"],"explanation":["일본의 사당이에요.","억지로 절하게 했어요.","신사예요."],"mis":"SO5-2-u3-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#6','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C20',1,'sa','auto','5·10 총선거로 뽑힌 국회의원들이 만든 나라의 기본 법은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO5-2-u3-C20","difficulty":1,"kind":"sa","stem":"5·10 총선거로 뽑힌 국회의원들이 만든 나라의 기본 법은 무엇인가요? 두 글자로 쓰세요.","answer":["헌법"],"explanation":["나라의 기본이에요.","국회가 만들었어요.","헌법이에요."],"mis":"SO5-2-u3-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#7','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C21',1,'ox','auto','정전 협정으로 전쟁이 완전히 끝나 남북이 다시 하나가 되었어요.',ARRAY['SO5-2-u3-X40']::text[],false,'{"seq":7,"concept":"SO5-2-u3-C21","difficulty":1,"kind":"ox","stem":"정전 협정으로 전쟁이 완전히 끝나 남북이 다시 하나가 되었어요.","answer":"X","reason_options":[{"t":"전투를 잠시 멈춘 것이라 휴전선과 분단이 남았기 때문에","correct":true},{"t":"남북이 함께 정부를 세웠기 때문에","mis":"SO5-2-u3-X40"}],"mis":"SO5-2-u3-X40","explanation":["정전은 멈춤이에요.","휴전선이 남았어요.","하나가 되지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#8','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C23',1,'sa','auto','6·25 전쟁으로 부모를 잃은 아이들을 무엇이라 하나요? (전쟁○○)','{}'::text[],false,'{"seq":8,"concept":"SO5-2-u3-C23","difficulty":1,"kind":"sa","stem":"6·25 전쟁으로 부모를 잃은 아이들을 무엇이라 하나요? (전쟁○○)","answer":["전쟁고아","고아"],"explanation":["부모를 잃었어요.","혼자 남았어요.","전쟁고아예요."],"mis":"SO5-2-u3-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#9','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C3',2,'ox','auto','헤이그 특사는 회의장에 들어가지 못했지만 여러 나라 기자들에게 대한 제국의 처지를 알렸어요.',ARRAY['SO5-2-u3-X05']::text[],false,'{"seq":9,"concept":"SO5-2-u3-C3","difficulty":2,"kind":"ox","stem":"헤이그 특사는 회의장에 들어가지 못했지만 여러 나라 기자들에게 대한 제국의 처지를 알렸어요.","answer":"O","reason_options":[{"t":"일제의 방해로 회의장은 막혔지만 다른 방법으로 부당함을 알렸기 때문에","correct":true},{"t":"특사는 아무에게도 말하지 않고 돌아왔기 때문에","mis":"SO5-2-u3-X05"}],"mis":"SO5-2-u3-X05","explanation":["회의장은 막혔어요.","기자들을 만났어요.","부당함을 알렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#10','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C6',2,'ox','auto','토지 조사 사업 뒤 시간이 지날수록 남의 땅을 빌려 농사짓는 농민이 늘었어요.',ARRAY['SO5-2-u3-X11']::text[],false,'{"seq":10,"concept":"SO5-2-u3-C6","difficulty":2,"kind":"ox","stem":"토지 조사 사업 뒤 시간이 지날수록 남의 땅을 빌려 농사짓는 농민이 늘었어요.","answer":"O","reason_options":[{"t":"많은 농민이 땅을 잃거나 불리하게 계약했기 때문에","correct":true},{"t":"농민 모두가 땅을 새로 받았기 때문에","mis":"SO5-2-u3-X11"}],"mis":"SO5-2-u3-X11","explanation":["땅을 잃었어요.","빌려 지었어요.","그런 농민이 늘었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#11','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C9',2,'ox','auto','대한민국 임시 정부는 비밀 연락망으로 나라 안 독립운동을 이끌고 돈을 모았어요.',ARRAY['SO5-2-u3-X17']::text[],false,'{"seq":11,"concept":"SO5-2-u3-C9","difficulty":2,"kind":"ox","stem":"대한민국 임시 정부는 비밀 연락망으로 나라 안 독립운동을 이끌고 돈을 모았어요.","answer":"O","reason_options":[{"t":"멀리서도 나라 안과 이어져 독립운동을 지휘하려 했기 때문에","correct":true},{"t":"일제가 연락망을 만들어 주었기 때문에","mis":"SO5-2-u3-X17"}],"mis":"SO5-2-u3-X17","explanation":["비밀 연락망이 있었어요.","지휘하고 돈을 모았어요.","독립운동을 이끌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#12','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C14',2,'ox','auto','나라 밖 독립군은 먹을 것이 끊기고 추위에 떨면서도 싸움을 이어 갔어요.',ARRAY['SO5-2-u3-X25']::text[],false,'{"seq":12,"concept":"SO5-2-u3-C14","difficulty":2,"kind":"ox","stem":"나라 밖 독립군은 먹을 것이 끊기고 추위에 떨면서도 싸움을 이어 갔어요.","answer":"O","reason_options":[{"t":"어려운 처지에서도 독립을 이루려는 뜻이 컸기 때문에","correct":true},{"t":"독립군은 늘 먹을 것이 넉넉했기 때문에","mis":"SO5-2-u3-X25"}],"mis":"SO5-2-u3-X25","explanation":["먹을 것이 끊겼어요.","추위도 견뎠어요.","싸움을 이어 갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#13','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C15',2,'ox','auto','일제 통치 시기에 한국인이 많이 산 동네는 전기가 잘 들어오지 않는 곳이 많았어요.',ARRAY['SO5-2-u3-X28']::text[],false,'{"seq":13,"concept":"SO5-2-u3-C15","difficulty":2,"kind":"ox","stem":"일제 통치 시기에 한국인이 많이 산 동네는 전기가 잘 들어오지 않는 곳이 많았어요.","answer":"O","reason_options":[{"t":"도시가 일본인이 사는 곳을 중심으로 발달했기 때문에","correct":true},{"t":"한국인은 전기를 원하지 않았기 때문에","mis":"SO5-2-u3-X28"}],"mis":"SO5-2-u3-X28","explanation":["일본인 동네는 환했어요.","한국인 동네는 달랐어요.","전기가 부족했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#14','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C20',2,'ox','auto','대한민국 정부는 8월 15일에 세워졌어요.',ARRAY['SO5-2-u3-X36']::text[],false,'{"seq":14,"concept":"SO5-2-u3-C20","difficulty":2,"kind":"ox","stem":"대한민국 정부는 8월 15일에 세워졌어요.","answer":"O","reason_options":[{"t":"광복을 맞은 날과 같은 날에 정부 수립을 알렸기 때문에","correct":true},{"t":"정부는 3월 1일에 세워졌기 때문에","mis":"SO5-2-u3-X36"}],"mis":"SO5-2-u3-X36","explanation":["헌법·대통령 다음이에요.","8월 15일이에요.","광복절과 같은 날이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#15','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C21',2,'ox','auto','6·25 전쟁 때 38도선 부근에서 싸우는 동안 전쟁을 멈추려는 회담도 이어졌어요.',ARRAY['SO5-2-u3-X40']::text[],false,'{"seq":15,"concept":"SO5-2-u3-C21","difficulty":2,"kind":"ox","stem":"6·25 전쟁 때 38도선 부근에서 싸우는 동안 전쟁을 멈추려는 회담도 이어졌어요.","answer":"O","reason_options":[{"t":"싸움이 길어지자 정전을 위한 회담이 함께 열렸기 때문에","correct":true},{"t":"회담은 전쟁이 시작되기 전에만 열렸기 때문에","mis":"SO5-2-u3-X40"}],"mis":"SO5-2-u3-X40","explanation":["싸움이 길어졌어요.","회담도 열렸어요.","정전 협정으로 이어졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#16','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C24',2,'ox','auto','광복절 옷에는 「나라를 되찾은 기쁨」을 담은 그림이 어울려요.',ARRAY['SO5-2-u3-X45']::text[],false,'{"seq":16,"concept":"SO5-2-u3-C24","difficulty":2,"kind":"ox","stem":"광복절 옷에는 「나라를 되찾은 기쁨」을 담은 그림이 어울려요.","answer":"O","reason_options":[{"t":"광복절은 빼앗긴 나라를 되찾은 날이기 때문에","correct":true},{"t":"광복절은 6·25 전쟁이 시작된 날이기 때문에","mis":"SO5-2-u3-X45"}],"mis":"SO5-2-u3-X45","explanation":["8월 15일이에요.","나라를 되찾았어요.","기쁨을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#17','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C14',3,'mc','auto','나라 안 실력 기르기 운동과 나라 밖 무장 투쟁을 함께 본 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X26','SO5-2-u3-X01']::text[],false,'{"seq":17,"concept":"SO5-2-u3-C14","difficulty":3,"kind":"mc","stem":"나라 안 실력 기르기 운동과 나라 밖 무장 투쟁을 함께 본 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말·글·경제를 지키는 힘과 맞서 싸우는 힘이 함께 독립을 향했다","correct":true},{"t":"무장 투쟁만 독립에 쓸모 있었다","mis":"SO5-2-u3-X26"},{"t":"실력 기르기만 독립에 쓸모 있었다","mis":"SO5-2-u3-X26"},{"t":"두 가지 모두 독립과 관계없었다","mis":"SO5-2-u3-X01"}],"explanation":["안에서는 힘을 길렀어요.","밖에서는 싸웠어요.","함께 필요했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#18','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C6',3,'ox','auto','솔이네 기억 상자 ②의 증조할아버지처럼 땅을 잃은 것은 일제가 내세운 「땅 주인 확인」과 다른 결과였어요.',ARRAY['SO5-2-u3-X10']::text[],false,'{"seq":18,"concept":"SO5-2-u3-C6","difficulty":3,"kind":"ox","stem":"솔이네 기억 상자 ②의 증조할아버지처럼 땅을 잃은 것은 일제가 내세운 「땅 주인 확인」과 다른 결과였어요.","answer":"O","reason_options":[{"t":"주인을 확인한다고 했지만 실제로는 많은 농민이 땅을 잃었기 때문에","correct":true},{"t":"토지 조사 사업으로 모든 농민이 땅을 새로 얻었기 때문에","mis":"SO5-2-u3-X10"}],"mis":"SO5-2-u3-X10","explanation":["내세운 까닭이 있어요.","실제로는 빼앗겼어요.","결과가 달랐어요."],"asset":{"type":"passage","lines":["② 빛바랜 교실 사진 속 선생님은 허리에 칼을 차고 있었다.","증조할아버지는 땅을 신고하지 못해 빼앗기고 남의 땅을 빌려 농사지었다.","증조할아버지의 동생은 집을 떠나 만주의 학교로 갔다."],"title":"솔이네 할머니의 기억 상자 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#19','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C13',3,'ox','auto','솔이네 기억 상자 ④의 광주 신문 속 학생들은 쌓여 있던 차별에 맞서 일어났어요.',ARRAY['SO5-2-u3-X24']::text[],false,'{"seq":19,"concept":"SO5-2-u3-C13","difficulty":3,"kind":"ox","stem":"솔이네 기억 상자 ④의 광주 신문 속 학생들은 쌓여 있던 차별에 맞서 일어났어요.","answer":"O","reason_options":[{"t":"학교에서 우리말과 역사를 제대로 배우지 못하고 차별받았기 때문에","correct":true},{"t":"학생들끼리 놀다 생긴 장난이었기 때문에","mis":"SO5-2-u3-X24"}],"mis":"SO5-2-u3-X24","explanation":["차별이 쌓였어요.","한국 학생만 붙잡혔어요.","그래서 일어났어요."],"asset":{"type":"passage","lines":["④ 「우리가 만든 것 우리가 쓰자」라고 적힌 광고지가 있었다.","방학이면 할머니의 오빠는 농촌에 가서 아이들에게 한글을 가르쳤다.","광주의 학생들이 차별에 맞서 일어났다는 신문도 남아 있었다."],"title":"솔이네 할머니의 기억 상자 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#20','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C19',3,'ox','auto','할머니가 광복 다음 날 처음으로 이름을 크게 말한 것은 나라를 되찾은 일이 한 사람의 생활까지 바꾸었음을 보여 줘요.',ARRAY['SO5-2-u3-X47']::text[],false,'{"seq":20,"concept":"SO5-2-u3-C19","difficulty":3,"kind":"ox","stem":"할머니가 광복 다음 날 처음으로 이름을 크게 말한 것은 나라를 되찾은 일이 한 사람의 생활까지 바꾸었음을 보여 줘요.","answer":"O","reason_options":[{"t":"빼앗겼던 이름을 되찾아 생활 속에서 쓰게 되었기 때문에","correct":true},{"t":"광복은 사람들의 생활과 관계없기 때문에","mis":"SO5-2-u3-X47"}],"mis":"SO5-2-u3-X47","explanation":["이름을 빼앗겼었어요.","광복으로 되찾았어요.","생활이 바뀌었어요."],"asset":{"type":"passage","lines":["⑥ 「광복 다음 날, 처음으로 내 이름을 크게 말했다.」 할머니의 쪽지다.","할머니는 다시 나온 한글 신문을 읽으며 기뻐했다.","할아버지는 남한에서 처음 치른 총선거 날 투표소 앞에서 사진을 찍었다."],"title":"솔이네 할머니의 기억 상자 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#21','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C23',3,'ox','auto','솔이네 기억 상자 ⑧의 신청서는 전쟁이 끝난 지 오랜 세월이 지나도 이어진 아픔을 보여 줘요.',ARRAY['SO5-2-u3-X43']::text[],false,'{"seq":21,"concept":"SO5-2-u3-C23","difficulty":3,"kind":"ox","stem":"솔이네 기억 상자 ⑧의 신청서는 전쟁이 끝난 지 오랜 세월이 지나도 이어진 아픔을 보여 줘요.","answer":"O","reason_options":[{"t":"휴전선 때문에 헤어진 가족을 오래도록 찾고 그리워했기 때문에","correct":true},{"t":"신청서는 전쟁이 시작된 날 쓴 것이기 때문에","mis":"SO5-2-u3-X43"}],"mis":"SO5-2-u3-X43","explanation":["오랜 세월이 지났어요.","아직 동생을 찾았어요.","아픔이 이어졌어요."],"asset":{"type":"passage","lines":["⑧ 마지막으로 낡은 종이 한 장이 나왔다.","헤어진 동생의 이름과 생김새를 적은 가족 찾기 방송 신청서였다.","할머니는 휴전선 너머 고향에 끝내 가 보지 못했다고 말씀하셨다."],"title":"솔이네 할머니의 기억 상자 ⑧"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#22','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C20',3,'mc','auto','광복과 대한민국 정부 수립 사이에 있었던 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X46']::text[],false,'{"seq":22,"concept":"SO5-2-u3-C20","difficulty":3,"kind":"mc","stem":"광복과 대한민국 정부 수립 사이에 있었던 일로 알맞은 것은 어느 것인가요?","options":[{"t":"38도선 남북에 미군과 소련군이 들어오고 5·10 총선거를 치렀다","correct":true},{"t":"3·1 운동이 일어났다","mis":"SO5-2-u3-X46"},{"t":"6·25 전쟁이 일어났다","mis":"SO5-2-u3-X46"},{"t":"을사늑약을 맺었다","mis":"SO5-2-u3-X46"}],"explanation":["광복 뒤 38도선이 생겼어요.","총선거를 치렀어요.","그 뒤 정부를 세웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#23','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C23',4,'mc','auto','솔이네 할머니의 기억 상자를 공부한 뒤 가질 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-2-u3-X43','SO5-2-u3-X47']::text[],false,'{"seq":23,"concept":"SO5-2-u3-C23","difficulty":4,"kind":"mc","stem":"솔이네 할머니의 기억 상자를 공부한 뒤 가질 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라를 되찾으려 애쓴 사람들과 전쟁의 아픔을 기억하고 평화를 소중히 여긴다","correct":true},{"t":"지난 일이니 모두 잊는다","mis":"SO5-2-u3-X43"},{"t":"날짜만 외우고 넘어간다","mis":"SO5-2-u3-X47"},{"t":"다른 집안 이야기는 나와 관계없다고 여긴다","mis":"SO5-2-u3-X47"}],"explanation":["노력을 기억해요.","아픔도 기억해요.","평화를 소중히 여겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#24','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C19',4,'essay','teacher','솔이네 기억 상자 ⑥을 보고 8·15 광복 뒤 달라진 생활 두 가지를 쓰고, 대한민국 정부가 세워지는 과정을 차례대로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-2-u3-C19","difficulty":4,"kind":"essay","stem":"솔이네 기억 상자 ⑥을 보고 8·15 광복 뒤 달라진 생활 두 가지를 쓰고, 대한민국 정부가 세워지는 과정을 차례대로 쓰세요.","answer_guide":{"answer":"예: 할머니는 일본식 이름 대신 자기 이름을 다시 썼고, 다시 나온 한글 신문을 읽었다. 정부는 남한에서 5·10 총선거를 치러 국회의원을 뽑고, 국회가 헌법을 만들어 알린 뒤, 헌법에 따라 대통령을 뽑고, 8월 15일에 대한민국 정부를 세웠다.","scoring_points":["달라진 생활 두 가지를 썼는가","총선거부터 정부 수립까지 차례를 썼는가","기억 상자를 근거로 들었는가"]},"explanation":["이름을 되찾았어요.","한글 신문을 읽었어요.","선거 → 헌법 → 대통령 → 정부예요."],"asset":{"type":"passage","lines":["⑥ 「광복 다음 날, 처음으로 내 이름을 크게 말했다.」 할머니의 쪽지다.","할머니는 다시 나온 한글 신문을 읽으며 기뻐했다.","할아버지는 남한에서 처음 치른 총선거 날 투표소 앞에서 사진을 찍었다."],"title":"솔이네 할머니의 기억 상자 ⑥"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_soc_u3_review_d#25','soc',5,2,'u3','','g5_2_soc_u3_review_d','unit_review','SO5-2-u3-C22',4,'essay','teacher','이 단원에서 배운 사람들 가운데 가장 마음에 남는 사람들(예: 의병, 3·1 운동의 학생, 피란민)을 골라, 그 사람들의 생활과 마음을 그때의 사실에 맞게 쓰고 오늘의 나와 이어 생각을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-2-u3-C22","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 사람들 가운데 가장 마음에 남는 사람들(예: 의병, 3·1 운동의 학생, 피란민)을 골라, 그 사람들의 생활과 마음을 그때의 사실에 맞게 쓰고 오늘의 나와 이어 생각을 쓰세요.","answer_guide":{"answer":"예: 천막 학교에서 공부한 피란민 학생들이 마음에 남는다. 집은 판잣집이고 물도 모자랐지만 전쟁이 끝난 뒤를 위해 배움을 멈추지 않았다. 오늘 나는 튼튼한 교실에서 공부하니, 그 학생들처럼 배움을 소중히 여기고 평화를 지키는 사람이 되고 싶다.","scoring_points":["사람들을 하나 골랐는가","생활과 마음을 사실에 맞게 썼는가","오늘의 나와 이어 썼는가"]},"explanation":["사람들을 골라요.","사실에 맞게 써요.","오늘의 나와 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
